registerClass12ExerciseBanks("islhist", {"1":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l1-exercise-10",3]],"tf":"yn","s":["ہاں۔ حضرت عباس بن عبدالمطلبؓ حضور ﷺ کے چچا تھے اور بنو عباس انہی کی نسل سے تھے۔"],"c":0},{"q":[["ihist12-l1-exercise-10",4]],"tf":"yn","s":["نہیں۔ بنو عباس تقریباً پانچ سو سال (132ھ سے 656ھ تک) برسرِ اقتدار رہے، تین صدیاں نہیں۔"],"c":1},{"q":[["ihist12-l1-exercise-10",5]],"tf":"yn","s":["نہیں۔ سانحۂ کربلا کے بعد شیعانِ علیؓ تین گروہوں میں تقسیم ہوئے: امامیہ، زیدیہ اور کیسانیہ۔"],"c":1},{"q":[["ihist12-l1-exercise-10",6]],"tf":"yn","s":["ہاں۔ امامیہ فرقے نے امام باقر کے بعد ان کے بیٹے امام جعفر صادق کی امامت تسلیم کی۔"],"c":0},{"q":[["ihist12-l1-exercise-10",7]],"tf":"yn","s":["ہاں۔ مختار ثقفی نے اپنے سیاسی مقاصد کے لیے قصاصِ حسینؓ کا نعرہ لگا کر لوگوں کو جمع کیا۔"],"c":0},{"q":[["ihist12-l1-exercise-10",8]],"tf":"yn","s":["ہاں۔ حضرت عبداللہ بن زبیرؓ نے اپنے بھائی حضرت مصعب بن زبیرؓ کو بھیجا جنہوں نے مختار ثقفی کا خاتمہ کر دیا۔"],"c":0},{"q":[["ihist12-l1-exercise-10",9]],"tf":"yn","s":["نہیں۔ ابو مسلم خراسانی نے خراسان پر قبضہ کیا تھا (ایران پر نہیں)؛ وہاں سے عباسی فتوحات آگے بڑھیں۔"],"c":1},{"q":[["ihist12-l1-exercise-10",10]],"tf":"yn","s":["ہاں۔ محمد بن علی کی وفات کے بعد امام ابراہیم نے ابو مسلم خراسانی کو تمام داعیوں اور نقیبوں کا سربراہ مقرر کیا۔"],"c":0}],"longQuestions":[{"q":[["ihist12-l1-exercise-10",1]],"s":["حضرت امام حسینؓ کی شہادت کے بعد شیعانِ علیؓ تین گروہوں میں تقسیم ہو گئے:","1۔ امامیہ: ان کا عقیدہ تھا کہ امامت صرف حضرت علیؓ کی فاطمی اولاد کا حق ہے؛ انہوں نے امام حسینؓ کے بیٹے امام زین العابدین (علی بن حسین) کو امام مانا، ان کے بعد امام باقر اور پھر امام جعفر صادق کو؛ چونکہ انہوں نے بنو امیہ کی خلافت قبول کر لی تھی اس لیے خلافت کا مطالبہ نہیں کیا۔","2۔ زیدیہ: عقائد امامیہ سے کافی ملتے جلتے؛ حضرت علیؓ کو نبی ﷺ کا وصی اور پہلا امام، امام حسنؓ کو دوسرا، امام حسینؓ کو تیسرا اور زین العابدین کو چوتھا امام مانتے؛ اس کے بعد اختلاف ہوا — امامیہ امام باقر کے حامی تھے جبکہ زیدیہ نے امام زید بن علی کو امام تسلیم کیا جو ظالم حکمران کے خلاف خروج کے قائل تھے۔","3۔ کیسانیہ: اس کی بنیاد مختار ثقفی نے اپنے سیاسی مقاصد کے لیے رکھی؛ قصاصِ حسینؓ کا نعرہ لگایا؛ امام زین العابدین نے سرپرستی سے انکار کیا تو حضرت علیؓ کے غیر فاطمی بیٹے محمد بن حنفیہ کو امام بنایا؛ حضرت مصعب بن زبیرؓ نے مختار کا خاتمہ کیا اور محمد بن حنفیہ نے عبدالملک کی بیعت کر لی؛ بعد میں اسی فرقے کی امامت ابو ہاشم سے عباسی خاندان (محمد بن علی) کو منتقل ہوئی جو عباسی تحریک کی بنیاد بنی۔"]}]}},"3":{"lang":"ur","items":{"mcqs":[{"q":[["ihist12-l3-exercise-21",8]],"os":1,"s":["دوسرا جملہ درست ہے: سفاح نے انبار کے قریب ہاشمیہ کا نیا شہر آباد کر کے اسے دار الخلافہ بنایا؛ بغداد منصور نے آباد کیا۔"],"c":1},{"q":[["ihist12-l3-exercise-21",9]],"os":1,"s":["دوسرا جملہ درست ہے: بنو عباس کا حقیقی بانی منصور تھا جس نے مسلسل محنت سے عباسی خلافت کو مستحکم کیا۔"],"c":1},{"q":[["ihist12-l3-exercise-21",10]],"os":1,"s":["دوسرا جملہ درست ہے: مروان ثانی نے امام ابراہیم کو قید کر کے قتل کروایا؛ محمد بن علی کی وفات طبعی تھی۔"],"c":1}],"objective":[{"q":[["ihist12-l3-exercise-21",12]],"s":["کوفہ","امام ابراہیم کی وصیت کے مطابق سفاح اور منصور حمیمہ سے کوفہ آئے جہاں سفاح کی خلافت کا اعلان ہوا۔"],"a":"کوفہ"},{"q":[["ihist12-l3-exercise-21",13]],"s":["دس","بنو عباس کا ابتدائی دور عروج کا دور تھا اور اس کے دس حکمران اعلیٰ صلاحیتوں کے مالک تھے۔"],"a":"دس"},{"q":[["ihist12-l3-exercise-22",0]],"s":["656","656ھ (1258ء) میں ہلاکو خان نے بغداد پر حملہ کر کے اس خاندان کا چراغ گل کر دیا۔"],"a":"656"},{"q":[["ihist12-l3-exercise-22",1]],"s":["شام","سفاح نے اپنے چچا عبداللہ بن علی کو شام کا گورنر مقرر کیا۔"],"a":"شام"},{"q":[["ihist12-l3-exercise-22",2]],"s":["یزید بن ہبیرہ","یزید بن ہبیرہ مروان کی طرف سے عراق کا گورنر تھا؛ واسط اس کے قبضے میں تھا۔"],"a":"یزید بن ہبیرہ"},{"q":[["ihist12-l3-exercise-22",3]],"s":["ابو سلمہ","سفاح نے عباسی تحریک کے مشہور داعی ابو سلمہ کو پہلا وزیر مقرر کیا؛ بعد میں اسے قتل کروا کر وزارت خالد برمکی کو دی۔"],"a":"ابو سلمہ"},{"q":[["ihist12-l3-exercise-22",4]],"s":["136","سفاح نے 136ھ میں وفات پائی۔"],"a":"136"},{"q":[["ihist12-l3-exercise-22",5]],"s":["منصور","سفاح نے اپنے بھائی ابو جعفر منصور کو ولی عہد مقرر کیا (اور اس کے بعد بھتیجے عیسیٰ بن موسیٰ کو)۔"],"a":"منصور"},{"q":[["ihist12-l3-exercise-22",6]],"s":["مکہ (حج)","سفاح کی وفات کے وقت منصور حج کے لیے مکہ گیا ہوا تھا۔"],"a":"مکہ (حج)"},{"q":[["ihist12-l3-exercise-22",7]],"s":["شام","عبداللہ بن علی نے شام میں اپنی خلافت کا اعلان کر کے بغاوت کی؛ منصور نے ابو مسلم کی مدد سے اسے شکست دی۔"],"a":"شام"},{"q":[["ihist12-l3-exercise-22",8]],"s":["موصل میں","خارجی سردار حسان بن مجاہد نے موصل میں بغاوت کی، مگر امام ابو حنیفہ کے ذریعے اس سے صلح ہو گئی۔"],"a":"موصل میں"},{"q":[["ihist12-l3-exercise-22",9]],"s":["عمر بن علاء","عمر بن علاء نے کوہستان، طبرستان اور دماوند کے علاقے فتح کیے۔"],"a":"عمر بن علاء"},{"q":[["ihist12-l3-exercise-22",10]],"s":["پیشوائی (قیادت)","منصور نے اعلان کیا کہ بنو عباس صرف دنیاوی حکمران نہیں بلکہ مذہبی پیشوا بھی ہیں؛ اس کے لیے علما سے فتوے بھی لیے۔"],"a":"پیشوائی (قیادت)"},{"q":[["ihist12-l3-exercise-22",11]],"s":["عبدالرحمٰن (الداخل)","ہشام کے پوتے عبدالرحمٰن نے بچ نکل کر ہسپانیہ (سپین) میں بنو امیہ کی حکومت قائم کی جو کئی صدیوں تک رہی۔"],"a":"عبدالرحمٰن (الداخل)"},{"q":[["ihist12-l3-exercise-22",12]],"n":"سبق میں ربیع کا نام \"ربیع بن یوسف\" لکھا ہے؛ تاریخ میں معروف نام ربیع بن یونس ہے۔ دونوں وزرا (ابو ایوب اور ربیع) درست جواب ہیں۔","s":["ابو ایوب","منصور نے خالد برمکی کو صوبے کا گورنر بنا کر وزارت ابو ایوب کو دی؛ بعد میں اس کی جائیداد ضبط کر کے قید کیا اور وزارت ربیع بن یونس کو دی۔"],"a":"ابو ایوب"},{"q":[["ihist12-l3-exercise-22",13]],"s":["والی","صوبوں کے گورنر والی کہلاتے تھے اور ان میں سے اکثر شاہی خاندان کے افراد تھے۔"],"a":"والی"},{"q":[["ihist12-l3-exercise-22",14]],"s":["حاجب","منصور نے وزیر کے علاوہ حاجب کا عہدہ قائم کیا؛ حاجب کی اجازت کے بغیر کوئی خلیفہ سے نہیں مل سکتا تھا۔"],"a":"حاجب"},{"q":[["ihist12-l3-exercise-22",15]],"s":["عیسیٰ بن موسیٰ","سفاح نے عیسیٰ بن موسیٰ کو دوسرا ولی عہد مقرر کیا تھا؛ منصور نے اسے منسوخ کر کے اپنے بیٹے مہدی کو ولی عہد بنایا۔"],"a":"عیسیٰ بن موسیٰ"},{"q":[["ihist12-l3-exercise-22",16]],"s":["پابند","منصور روزے اور نماز کا پابند تھا، عیش و عشرت سے نفرت کرتا اور سادہ لباس پہنتا تھا۔"],"a":"پابند"},{"q":[["ihist12-l3-exercise-22",17]],"s":["منصور","منصور کا معمول تھا کہ فجر کی نماز خود پڑھاتا، پھر دربار میں اپنے فرائض انجام دیتا۔"],"a":"منصور"}],"longQuestions":[{"q":[["ihist12-l3-exercise-21",2]],"s":["ابو العباس عبداللہ سفاح (132–136ھ / 750–754ء) پہلا عباسی خلیفہ تھا؛ امام ابراہیم کی وصیت کے مطابق کوفہ میں اس کی خلافت کا اعلان ہوا؛ بنو امیہ سے سخت انتقام اور خون ریزی کی وجہ سے \"سفاح\" (خون بہانے والا) مشہور ہوا۔","صوبوں کی نئی تنظیم: رشتہ داروں کو گورنر بنایا — داؤد بن علی کو حجاز، یمن و یمامہ؛ عبداللہ بن علی کو شام؛ منصور کو جزیرہ، آرمینیا اور آذربائیجان؛ سلیمان کو بصرہ؛ ابو عون کو مصر اور ابو مسلم کو خراسان۔","یزید بن ہبیرہ کا قتل: مروان کے گورنرِ عراق نے واسط میں امان کی شرط پر ہتھیار ڈالے مگر ابو مسلم کے اکسانے پر قتل کیا گیا؛ وزارت کا باقاعدہ قیام — پہلا وزیر ابو سلمہ جسے اہلِ بیت سے عقیدت کی وجہ سے قتل کروایا، پھر خالد برمکی وزیر بنا۔","بغاوتیں: موصل، آرمینیا اور سندھ کے گورنروں اور حامیانِ اہلِ بیت کی بغاوتیں کچل دیں؛ فتوحات: رومیوں سے شکست کے بعد خالد بن ابراہیم اور صالح بن زیاد نے چینی سرحد پر ختل، چاچ، فرغانہ اور کش فتح کیے؛ نیا شہر ہاشمیہ آباد کر کے دار الخلافہ بنایا۔","136ھ میں وفات؛ منصور اور عیسیٰ بن موسیٰ کو ولی عہد مقرر کیا؛ سخت گیری کے ساتھ دانش مندی اور سخاوت میں بے مثال، عیش پرستی سے نفرت اور شاعری کا شوقین۔"]},{"q":[["ihist12-l3-exercise-21",3]],"s":["سفاح نے صرف چار سال حکومت کی اور اس کا دور خون ریزی میں گزرا؛ خلافت ابھی کمزور تھی — منصور نے اسے مضبوط بنیادوں پر استوار کیا۔","خطرناک حریفوں کا خاتمہ: چچا عبداللہ بن علی کی بغاوت کچلی؛ طاقتور ابو مسلم خراسانی کو قتل کر کے ممکنہ خطرہ ختم کیا؛ راوندیوں، سنباد اور نفس زکیہ (محمد بن عبداللہ) اور ابراہیم کی بغاوتیں کچلیں۔","انتظامی ڈھانچہ: وزارت کے ساتھ حاجب اور کاتب کے عہدے؛ صوبوں میں والی، قاضی اور سپہ سالار خلیفہ کی طرف سے؛ جاسوسی کا جال؛ فوج میں خراسانیوں کو ترجیح؛ منظم مالیات اور کفایت شعاری سے خزانہ بھر دیا۔","نیا دار الخلافہ بغداد آباد کیا جو صدیوں تک اسلامی تہذیب اور علم کا مرکز رہا؛ مذہبی پیشوائی کا اعلان کر کے خلافت کو دینی حیثیت دی، اسی لیے یہ خاندان پانچ سو سال حکمران رہا۔","ولی عہدی اپنے بیٹے مہدی کو منتقل کر کے جانشینی کا نظام طے کیا؛ رومیوں اور سرحدی علاقوں میں فتوحات — ان مسلسل اور انتھک کوششوں کی وجہ سے منصور کو بنو عباس کا حقیقی بانی کہا جاتا ہے۔"]},{"q":[["ihist12-l3-exercise-21",4]],"s":["سیرت: روزے اور نماز کا پابند؛ فجر کی نماز خود پڑھاتا؛ عیش و عشرت سے نفرت؛ سادہ اور معمولی لباس؛ اعلیٰ درجے کا کفایت شعار اور فضول خرچی کا سخت مخالف؛ حاکم و محکوم، آقا و غلام، امیر و غریب سب سے یکساں انصاف؛ انتہائی نامساعد حالات میں بھی ثابت قدم۔","نظم و ضبط: دن کا باقاعدہ معمول — فجر کے بعد عصر تک دربار، رات کو بھی امورِ سلطنت؛ جاسوسی کے جال سے گورنروں کی نگرانی؛ باغیوں کے معاملے میں سختی بلکہ بعض اوقات بے رحمی اور وعدہ خلافی (عبداللہ بن علی اور ابو مسلم کا انجام)۔","کارنامے: عبداللہ بن علی، ابو مسلم، راوندیہ، سنباد، نفس زکیہ اور ابراہیم کی بغاوتوں کا خاتمہ؛ خارجیوں سے صلح؛ عمر بن علاء کے ذریعے کوہستان، طبرستان، دماوند کی فتح؛ سندھ میں پیش قدمی؛ رومیوں کی پسپائی۔","بغداد کی تعمیر؛ حاجب اور کاتب کے عہدے؛ صوبائی نظام کی تنظیم؛ مذہبی پیشوائی کا اعلان؛ مہدی کو ولی عہد بنانا؛ علوم کی سرپرستی — یونانی و ہندی کتب (سدھانت) کے تراجم کا آغاز۔","158ھ میں حج کے سفر میں مکہ کے قریب وفات؛ تقریباً بائیس سال حکومت کی اور ایک مضبوط اور خوشحال سلطنت چھوڑی۔"]},{"q":[["ihist12-l3-exercise-21",5]],"s":["اخلاق: ابو مسلم خراسانی ذہین، دور اندیش، بہادر، مستقل مزاج اور منتظم تھا؛ حالات کا مقابلہ حوصلے سے کرتا اور خطابت میں ملکہ رکھتا تھا؛ کم سخن، سادہ مزاج اور لوگوں کو متاثر کرنے والا، مگر سخت گیر اور بے رحم — اس کے حکم سے ہزاروں لوگ قتل ہوئے۔","کارنامے: نوجوانی میں عباسی تحریک میں شامل ہوا؛ امام ابراہیم نے اسے تمام داعیوں اور نقیبوں کا سربراہ بنا کر خراسان بھیجا؛ اس نے تحریک گھر گھر پہنچائی؛ 129ھ میں سیاہ جھنڈے بلند کر کے کھلی بغاوت کی۔","اموی گورنر نصر بن سیار کو شکست دے کر خراسان پر قبضہ کیا؛ عرب قبائل کے باہمی اختلافات سے فائدہ اٹھایا؛ اس کی فوجیں قحطبہ کی قیادت میں عراق تک پہنچیں اور بالآخر اموی حکومت ختم ہوئی۔","سفاح کے دور میں خراسان کا گورنر رہا؛ منصور کے دور میں عبداللہ بن علی کی بغاوت کچلی؛ مگر اس کی بڑھتی طاقت سے خائف ہو کر منصور نے 137ھ میں اسے قتل کروا دیا۔"]},{"q":[["ihist12-l3-exercise-21",6]],"s":["عباسی خلافت کے قیام میں ابو مسلم کا ہاتھ بنیادی اور فیصلہ کن تھا: محمد بن علی نے تحریک منظم کی مگر اسے عوامی قوت ابو مسلم نے بنایا؛ امام ابراہیم نے اسے تمام داعیوں کا سربراہ بنایا۔","اس نے خراسان کو تحریک کا مرکز بنایا جہاں ایرانی النسل لوگ اموی عرب تعصب سے نالاں تھے؛ ان کی محرومیوں کو اہلِ بیت کے نام پر منظم کیا؛ کسی خاص امام کا نام نہ لے کر شیعانِ علیؓ کی حمایت بھی حاصل رکھی۔","129ھ میں سیاہ جھنڈوں کے ساتھ کھلی بغاوت کی؛ عرب قبائل (یمنی و مضری) کی آپس کی لڑائی سے فائدہ اٹھا کر نصر بن سیار کو شکست دی اور مرو پر قبضہ کیا۔","خراسان کی فوجیں اسی کی تنظیم سے قحطبہ اور حسن بن قحطبہ کی قیادت میں عراق پہنچیں، کوفہ فتح ہوا اور زاب کی جنگ (132ھ) میں مروان ثانی کو شکست ہوئی۔","قیام کے بعد بھی اس نے یزید بن ہبیرہ اور ابو سلمہ کا خاتمہ کروایا اور عبداللہ بن علی کی بغاوت کچلی؛ اس لیے مورخین کہتے ہیں کہ اگر ابو مسلم نہ ہوتا تو شاید عباسی خلافت قائم نہ ہوتی — اگرچہ آخرکار منصور نے اسے قتل کروا دیا۔"]}]}},"5":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l5-exercise-38",3]],"s":["مہدی (ابو عبداللہ محمد)","منصور کی وفات کے بعد اس کا بیٹا ابو عبداللہ محمد مہدی تخت نشین ہوا۔"],"a":"مہدی (ابو عبداللہ محمد)"},{"q":[["ihist12-l5-exercise-38",4]],"s":["اہلِ بیت","منصور نے اہلِ بیت سے سخت سلوک کیا تھا؛ مہدی نے انہیں قید خانوں سے رہا کیا اور ان کی ضبط شدہ جائیدادیں واپس کیں۔"],"a":"اہلِ بیت"},{"q":[["ihist12-l5-exercise-38",5]],"s":["تاویل","زند کے معنی تاویل ہیں؛ یہ لوگ دوسرے مذاہب کی کتابوں کی اپنی مرضی سے تاویل کرتے تھے، اس لیے زندیق کہلائے۔"],"a":"تاویل"},{"q":[["ihist12-l5-exercise-38",6]],"s":["ابو مسلم خراسانی","ابو مسلم خراسانی کے کاتب حکم بن حکیم (المقنع) نے خدائی کا دعویٰ کیا تھا۔"],"a":"ابو مسلم خراسانی"},{"q":[["ihist12-l5-exercise-38",7]],"s":["سلیمان بن علی","مہدی نے سلیمان بن علی کو رومیوں کے مقابلے پر بھیجا جس نے انہیں شکست دے کر کافی مالِ غنیمت حاصل کیا۔"],"a":"سلیمان بن علی"},{"q":[["ihist12-l5-exercise-38",8]],"s":["فضل بن صالح","مصر کی بغاوت فضل بن صالح نے کچلی۔"],"a":"فضل بن صالح"},{"q":[["ihist12-l5-exercise-38",9]],"s":["غلام","یعقوب بن داؤد بنیادی طور پر غلام تھا؛ بعد میں مہدی کا وزیر بنا۔"],"a":"غلام"},{"q":[["ihist12-l5-exercise-38",10]],"s":["خوشحالی (امن)","مہدی کا دور دراصل خوشحالی اور امن کا دور تھا؛ تجارت اور اصلاحات کو فروغ ملا۔"],"a":"خوشحالی (امن)"},{"q":[["ihist12-l5-exercise-38",11]],"s":["دجلہ","مہدی نے دریائے دجلہ کے کنارے ایک شاندار محل تعمیر کروایا۔"],"a":"دجلہ"},{"q":[["ihist12-l5-exercise-38",12]],"s":["ٹکسال","مہدی نے عیسیٰ آباد میں ایک نئی ٹکسال قائم کی۔"],"a":"ٹکسال"},{"q":[["ihist12-l5-exercise-38",13]],"s":["23","ہارون الرشید نے تقریباً 23 سال (170ھ سے 193ھ تک) حکومت کی۔"],"a":"23"},{"q":[["ihist12-l5-exercise-38",14]],"s":["یحییٰ (برمکی)","ہارون نے اپنے اتالیق یحییٰ بن خالد برمکی کو وزیرِ اعظم بنایا اور اسے \"باپ\" کہتا تھا۔"],"a":"یحییٰ (برمکی)"},{"q":[["ihist12-l5-exercise-38",15]],"s":["آئرین","ہارون کے دور میں قسطنطنیہ پر ملکہ آئرین (ایرینی) حکمران تھی جو ہارون کو خراج دیتی تھی۔"],"a":"آئرین"},{"q":[["ihist12-l5-exercise-38",16]],"s":["نقفور (نائسیفورس)","آئرین کو معزول کر کے بادشاہ بننے والے نقفور نے خراج بند کیا اور ہارون کو توہین آمیز خط لکھا؛ ہارون نے جواب دیا: تم اپنے خط کا جواب اپنی آنکھوں سے دیکھو گے۔"],"a":"نقفور (نائسیفورس)"},{"q":[["ihist12-l5-exercise-38",17]],"s":["زبیدہ","ہارون نے اپنی چہیتی بیوی زبیدہ کے اصرار پر قابل مامون کے بجائے امین کو ولی عہد بنایا — یہ غلط فیصلہ بہت تباہ کن ثابت ہوا۔"],"a":"زبیدہ"},{"q":[["ihist12-l5-exercise-38",18]],"s":["17","برامکہ تقریباً 17 سال خلافت پر پوری طرح چھائے رہے۔"],"a":"17"},{"q":[["ihist12-l5-exercise-38",19]],"s":["جعفر","محرم 187ھ میں جعفر برمکی کو قتل کر دیا گیا؛ یحییٰ اور فضل کو قید کیا گیا۔"],"a":"جعفر"},{"q":[["ihist12-l5-exercise-39",0]],"s":["فضل بن ربیع","فضل بن ربیع برامکہ کا جانی دشمن تھا؛ اس نے ہارون کو بہکایا کہ برامکہ اہلِ بیت کو اقتدار منتقل کرنا چاہتے ہیں۔"],"a":"فضل بن ربیع"},{"q":[["ihist12-l5-exercise-39",1]],"n":"یہ تفصیل سبق کے متن میں نہیں ملی؛ جواب تاریخ کی معروف روایت (طبری، سیوطی) سے ہے۔","s":["سو (100)","ہارون الرشید روزانہ سو رکعت نفل پڑھتا تھا (اور ہر سال حج یا جہاد کرتا)۔"],"a":"سو (100)"},{"q":[["ihist12-l5-exercise-39",2]],"n":"یہ واقعہ سبق کے متن میں نہیں ملا؛ جواب تاریخ کی معروف روایت سے ہے۔","s":["ابنِ سماک","ایک بار ابنِ سماک کی موجودگی میں ہارون کے لیے پانی کا پیالہ لایا گیا؛ انہوں نے پوچھا اگر یہ پانی نہ ملے تو کتنے میں خریدو گے؟ کہا آدھی سلطنت؛ پھر پوچھا اگر پیا ہوا پانی جسم سے نہ نکلے؟ کہا باقی آدھی؛ فرمایا: جس سلطنت کی قیمت ایک گھونٹ پانی ہو اس پر غرور کیسا — ہارون رو پڑا۔"],"a":"ابنِ سماک"}]}},"7":{"lang":"ur","items":{"mcqs":[{"q":[["ihist12-l7-exercise-52",1]],"ob":1,"s":["مامون نے فضل بن سہل کو وزیرِ اعظم بنایا کیونکہ اسی کی کوششوں سے اسے تخت ملا تھا؛ حکومت کے سارے اختیارات اسی کے پاس تھے۔"],"c":1},{"q":[["ihist12-l7-exercise-52",2]],"ob":1,"s":["یعقوب بن اسحاق الکندی کو نادر کتب اور اعلیٰ علم کی وجہ سے \"فیلسوف العرب\" کا لقب دیا گیا۔"],"c":0},{"q":[["ihist12-l7-exercise-52",3]],"ob":1,"s":["فضل بن ربیع نے امین کو مشورہ دیا کہ مامون اور مؤتمن کو ولی عہدی سے دستبردار کر کے اپنے بیٹے موسیٰ کی ولی عہدی کا اعلان کرے۔"],"c":1},{"q":[["ihist12-l7-exercise-52",4]],"ob":1,"s":["طاہر (بن حسین) مامون کا غلام تھا، بعد میں جرنیل اور خراسان کا مستقل گورنر بنا۔"],"c":0},{"q":[["ihist12-l7-exercise-52",5]],"ob":1,"s":["عجمی فوج کے سردار حسین بن علی نے امین کو معزول کیا مگر اہلِ بغداد نے پچھتا کر حسین کو قتل کر دیا اور امین کو دوبارہ تخت پر بٹھایا۔"],"c":2},{"q":[["ihist12-l7-exercise-52",6]],"ob":1,"s":["مامون کی پرورش جعفر برمکی نے کی تھی، اسی لیے اسے علم سے دلی لگاؤ تھا۔"],"c":2},{"q":[["ihist12-l7-exercise-52",7]],"ob":1,"s":["فضل بن سہل کے بہکانے پر مامون نے ہرثمہ کو جیل میں ڈال دیا جہاں فضل نے اسے خاموشی سے قتل کروا دیا۔"],"c":0},{"q":[["ihist12-l7-exercise-52",8]],"ob":1,"s":["مامون امام علی رضا سے بہت متاثر تھا اور اپنی بیٹی کی شادی ان سے کر دی (اور انہیں ولی عہد بھی بنایا)۔"],"c":0}],"objective":[{"q":[["ihist12-l7-exercise-51",8]],"s":["امین (محمد امین)","ہارون الرشید کی وصیت کے مطابق محمد امین خلیفہ بنا۔"],"a":"امین (محمد امین)"},{"q":[["ihist12-l7-exercise-51",9]],"s":["چالاک اور عیار","فضل بن ربیع ایک چالاک اور عیار شخص تھا جو عیش پرست امین کو اپنے مقاصد کے لیے استعمال کرنا چاہتا تھا۔"],"a":"چالاک اور عیار"},{"q":[["ihist12-l7-exercise-51",10]],"s":["علی بن عیسیٰ","امین نے اپنے جرنیل علی بن عیسیٰ کو پچاس ہزار کی فوج کے ساتھ خراسان میں مامون کے خلاف بھیجا؛ رے کے قریب طاہر نے اسے شکست دی اور وہ مارا گیا۔"],"a":"علی بن عیسیٰ"},{"q":[["ihist12-l7-exercise-51",11]],"s":["امین","مامون اپنے بھائی امین کے قتل کے بعد محرم 198ھ میں تخت نشین ہوا۔"],"a":"امین"}],"longQuestions":[{"q":[["ihist12-l7-exercise-51",5]],"s":["مامون کی پرورش جعفر برمکی جیسے عالم نے کی تھی، اس لیے اسے علم سے دلی لگاؤ تھا؛ وہ تفسیر، فقہ، حدیث، فلسفہ اور ریاضی میں ماہر تھا؛ اس کا دور علمی ترقی کا سنہری دور کہلاتا ہے۔","بیت الحکمہ: منصور نے دار الترجمہ قائم کیا، ہارون نے اسے بیت الحکمہ بنایا اور مامون نے اسے عظیم علمی ادارہ بنا دیا — کتب خانہ، دار الترجمہ اور تحقیقی مرکز؛ یونانی، سریانی، فارسی اور سنسکرت کی ہزاروں کتب (ارسطو، افلاطون، بقراط، جالینوس، اقلیدس، بطلیموس) عربی میں ترجمہ ہوئیں؛ مترجمین کو کتاب کے وزن کے برابر سونا دیا جاتا تھا۔","مشہور علما: حنین بن اسحاق (مترجم و طبیب)، یعقوب بن اسحاق الکندی (فیلسوف العرب)، محمد بن موسیٰ الخوارزمی (الجبرا)، بنو موسیٰ، ثابت بن قرہ؛ حدیث و فقہ میں امام احمد بن حنبل اور امام شافعی کا زمانہ۔","سائنسی کام: بغداد اور دمشق میں رصد گاہیں؛ زمین کے محیط کی پیمائش؛ فلکیاتی جداول (زیج)؛ طب، کیمیا اور جغرافیہ میں ترقی؛ قیصرِ روم سے صلح کی شرط میں کتابیں مانگیں۔","مذہبی و فکری سرگرمیاں: علمی مباحثے اور مناظرے؛ معتزلہ کی سرپرستی اور خلقِ قرآن کا مسئلہ (فتنۂ خلقِ قرآن) — یہ اس دور کا منفی پہلو تھا؛ مجموعی طور پر مامون کے دور نے یورپ کی نشاۃِ ثانیہ کی بنیاد فراہم کی۔"]},{"q":[["ihist12-l7-exercise-51",6]],"s":["تخت نشینی: امین کے قتل کے بعد محرم 198ھ میں تخت نشین ہوا؛ فضل بن سہل کو وزیرِ اعظم بنایا جس نے اسے مرو میں رکھا اور اصل حالات چھپائے۔","ہرثمہ کا قتل اور بغداد کی بغاوت: فضل کے بہکانے پر مامون نے وفادار جرنیل ہرثمہ کو جیل میں ڈالا جہاں اسے قتل کر دیا گیا؛ اس پر اہلِ بغداد نے بغاوت کی۔","امام علی رضا کی ولی عہدی: مامون نے امام علی رضا کو ولی عہد بنایا، اپنی بیٹی ان سے بیاہی اور سبز جھنڈا اختیار کیا؛ اس پر عباسی ناراض ہوئے اور بغداد میں ابراہیم بن مہدی کو خلیفہ بنا دیا؛ امام رضا کی اطلاع پر مامون کو حقیقت معلوم ہوئی؛ فضل حمام میں قتل ہوا؛ امام رضا کی وفات ہوئی۔","بغداد واپسی (204ھ) اور اصل دورِ خلافت: ابراہیم بن مہدی روپوش ہو گیا؛ طاہر کو خراسان کا مستقل گورنر بنایا جس نے طاہری خاندان کی بنیاد رکھی؛ حسن بن سہل وزیر بنا اور اس کی بیٹی بوران سے تاریخی شادی ہوئی۔","بغاوتیں اور جنگیں: بابک خرمی، مصر اور یمن کی بغاوتیں؛ رومیوں کے خلاف مہمات؛ علمی ترقی، بیت الحکمہ، اعتزال کی سرپرستی اور خلقِ قرآن کا فتنہ؛ 218ھ میں رومی مہم کے دوران طرطوس کے قریب وفات۔"]}]}},"10":{"lang":"ur","items":{"mcqs":[{"q":[["ihist12-l10-exercise-59",4]],"ob":1,"s":["مامون نے وفات کے وقت اپنے بیٹے عباس کے بجائے بھائی محمد بن ہارون (معتصم) کو ولی عہد مقرر کیا؛ عباس نے باپ کی وصیت کا احترام کرتے ہوئے معتصم کی بیعت کر لی۔"],"c":1},{"q":[["ihist12-l10-exercise-59",5]],"ob":1,"s":["افشین محمد بن ہارون (معتصم باللہ) کے دورِ حکومت کا فوجی جرنیل تھا۔"],"c":0},{"q":[["ihist12-l10-exercise-59",6]],"ob":1,"s":["معتصم (محمد بن ہارون) کے جرنیل افشین نے بابک خرمی کو گرفتار کر کے پیش کیا اور خلیفہ نے اس کے ہاتھ پاؤں کٹوا کر قتل کروا دیا۔"],"c":1},{"q":[["ihist12-l10-exercise-59",7]],"ob":1,"s":["افشین نے خلیفہ کو اپنے ساتھیوں سمیت زہر دینے کا منصوبہ بنایا مگر راز قبل از وقت فاش ہو گیا اور 226ھ میں اسے جیل میں قتل کر دیا گیا۔"],"c":1},{"q":[["ihist12-l10-exercise-59",8]],"ob":1,"s":["احمد بن نصر (امام مالک کے شاگرد) نے معتزلی عقائد کی مخالفت کی تو واثق باللہ نے مناظرے کے بعد ان کا سر قلم کروا دیا۔"],"c":0},{"q":[["ihist12-l10-exercise-59",9]],"ob":1,"s":["ترک سردار بغا نے شوال 247ھ میں قصرِ خلافت میں داخل ہو کر متوکل کو قتل کر دیا۔"],"c":1}],"longQuestions":[{"q":[["ihist12-l10-exercise-59",1]],"s":["ابو اسحاق محمد بن ہارون معتصم باللہ (833–842ء): مامون کی وصیت پر خلیفہ بنا؛ عباس بن مامون نے بیعت کر لی۔","بابک خرمی کا خاتمہ: مامون کے دور سے سرگرم بابک کو افشین نے گرفتار کیا؛ اسے ہاتھ پاؤں کاٹ کر قتل کیا گیا اور اس کا بھائی عبداللہ بغداد میں پھانسی چڑھا۔","بغاوتیں: آذربائیجان کے قائم مقام حاکم منکجور کی بغاوت کچلی گئی؛ طبرستان کا حاکم مازیار (افشین کے اکسانے پر) باغی ہوا، کوڑوں کی سزا سے مر گیا؛ افشین نے قومی تعصب اور آبائی مذہب کی وجہ سے سازش کی، زہر دینے کا منصوبہ فاش ہوا اور 226ھ میں قید میں قتل ہوا۔","ترکوں کی فوج میں شمولیت: بے مثال بہادری کی وجہ سے ترکوں کو فوج میں بھرتی کیا، ان کے لیے الگ چھاؤنی (سامرا) بنوائی اور افشین، ایتاخ اور اشناس جیسے ترک سرداروں کو کمانڈر بنایا — یہی بعد میں خلافت کی کمزوری کا سبب بنا۔","فتحِ عموریہ: تھیوفیلس کے مسلمانوں پر مظالم اور ایک ہاشمی خاتون کی پکار \"وامعتصماہ\" سن کر فوراً لشکر کشی کی؛ انقرہ فتح کر کے رومیوں کے سب سے بڑے اور مضبوط شہر عموریہ کو فتح کیا، قتلِ عام سے منع کیا؛ وزارت: فضل بن مروان، احمد بن عمار اور پھر محمد بن عبدالملک الزیات؛ محرم 227ھ میں وفات۔"]},{"q":[["ihist12-l10-exercise-59",2]],"s":["جعفر بن معتصم المتوکل علی اللہ (847–861ء): واثق نے ولی عہد مقرر نہیں کیا تھا؛ امرا اور جرنیلوں نے ابن زیات کی مخالفت کر کے متوکل کو خلیفہ بنایا؛ اس کا دور بظاہر خوشحالی اور امن و امان کا دور تھا مگر وہ خود عیش پرست تھا۔","ابن زیات کا قتل: واثق کے دور میں ابن زیات کی زیادتیوں کا بدلہ لیتے ہوئے اسے اسی لوہے کے تنور میں ڈال کر مارا جس میں وہ لوگوں کو سزا دیتا تھا؛ ترکوں کی طاقت ختم کرنے کے لیے ایتاخ اور اس کے بیٹوں کو قید کر کے قتل کروایا۔","بغاوتیں اور فتوحات: ابن بعیث کی بغاوت (ترک سردار بغا نے گرفتار کیا)، آرمینیا کی بغاوت؛ مدعیٔ نبوت محمود بن فرج نیشاپوری کا قتل؛ رومیوں کے خلاف مہمات اور قصریانہ کی فتح؛ متوکل نے معتزلہ کی سرپرستی ختم کر کے خلقِ قرآن کا فتنہ ختم کیا اور اہلِ سنت کو آزادی دی۔","زوال کا آغاز: ترکوں کی طاقت سے خلیفہ مفلوج ہو گیا؛ خود مختار ریاستوں کا آغاز اسی دور میں ہوا۔","قتل: تین بیٹوں منتصر، معتز اور معتمد کو ولی عہد بنایا مگر معتز کی ماں کی محبت میں معتز کو اول کرنا چاہا اور منتصر اور ترک سرداروں کے قتل کا منصوبہ بنایا؛ سازش ناکام ہوئی اور شوال 247ھ میں ترک سردار بغا نے محل میں گھس کر متوکل کو قتل کر دیا۔"]}]}},"13":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l13-exercise-64",4]],"tf":"tf","s":["صحیح۔ متوکل کے قتل کے بعد ترکوں نے اپنی مرضی سے محمد بن جعفر (منتصر باللہ) کو خلیفہ بنایا۔"],"c":0},{"q":[["ihist12-l13-exercise-64",5]],"tf":"tf","s":["صحیح۔ معتز باللہ کے دور میں خلیفہ ترکوں کے ہاتھ میں کٹھ پتلی تھا اور صفاریوں نے سیستان اور ایران کے علاقوں پر قبضہ کر کے اپنی حکومت قائم کی۔"],"c":0},{"q":[["ihist12-l13-exercise-64",6]],"tf":"tf","s":["غلط۔ احمد بن متوکل المعتمد نے تقریباً 23 سال حکومت کی (256–279ھ)، 10 سال نہیں۔"],"c":1},{"q":[["ihist12-l13-exercise-64",8]],"s":["معتز","مستعین سامرا سے بغداد آیا تو ترکوں نے معتز کو رہا کر کے اس کی بیعت شروع کر دی۔"],"a":"معتز"},{"q":[["ihist12-l13-exercise-64",9]],"n":"سبق کے مطابق بعد میں رجب 255ھ میں معتز بھی باقاعدہ خلافت سے دستبردار ہوا؛ سیاق (معتز کی بیعت کے بعد) کے لحاظ سے یہاں مستعین مراد ہے۔","s":["مستعین","آخرکار مستعین خلافت سے دستبردار ہو گیا اور نظر بند رہ کر مرا (بعض روایات کے مطابق قتل کیا گیا)۔"],"a":"مستعین"},{"q":[["ihist12-l13-exercise-64",10]],"s":["بغاوت","خزانہ خالی ہونے کی وجہ سے کئی ماہ تنخواہ نہ ملنے پر فوج نے بغاوت کی۔"],"a":"بغاوت"},{"q":[["ihist12-l13-exercise-64",11]],"s":["25 سال","تخت نشینی (256ھ) کے وقت معتمد کی عمر 25 سال تھی۔"],"a":"25 سال"},{"q":[["ihist12-l13-exercise-64",12]],"s":["یعقوب صفار","یعقوب بن لیث صفار نے طاہری حکومت کا خاتمہ کیا۔"],"a":"یعقوب صفار"},{"q":[["ihist12-l13-exercise-64",13]],"s":["ابنِ طولون","معتمد نے اپنی بے بسی سے تنگ آ کر مصر کے امیر ابنِ طولون کے پاس پناہ لینے کی کوشش کی مگر موفق نے اسے راستے سے واپس بلوا لیا۔"],"a":"ابنِ طولون"}],"longQuestions":[{"q":[["ihist12-l13-exercise-64",1]],"s":["محمد بن جعفر المنتصر باللہ (861–862ء) متوکل کا بیٹا تھا؛ متوکل کے قتل کے بعد ترکوں نے اپنی مرضی سے اسے خلیفہ بنایا اور امرا، وزرا اور عوام سے بیعت لی گئی۔","متوکل کے قتل میں اس کی شمولیت کا الزام تھا کیونکہ متوکل اسے ولی عہدی سے محروم کر کے معتز کو مقدم کرنا چاہتا تھا؛ اس لیے اس کی خلافت ترکوں کی مرہونِ منت تھی اور خلیفہ ان کے ہاتھ میں تھا۔","ترکوں کے دباؤ پر اس نے اپنے بھائیوں معتز اور مؤید کو ولی عہدی سے دستبردار کروایا؛ اس نے علویوں سے نرمی برتی اور ان پر سے پابندیاں ہٹائیں۔","اس کا دورِ خلافت بہت مختصر (تقریباً چھ ماہ) تھا، تاہم اس دور میں کچھ فتوحات بھی ہوئیں۔","چھ ماہ بعد بیمار ہوا اور تین دن کی بیماری کے بعد فوت ہو گیا؛ اس کے بعد معتصم کا پوتا مستعین باللہ تخت نشین ہوا۔"]},{"q":[["ihist12-l13-exercise-64",2]],"s":["ابو العباس احمد بن متوکل المعتمد علی اللہ 256ھ میں 25 سال کی عمر میں تخت نشین ہوا اور تقریباً 23 سال حکومت کی، مگر حکومت درحقیقت اس کے بھائی موفق باللہ کے ہاتھ میں تھی؛ اسی لیے وہ صرف نام کا حکمران تھا۔","تمام اختیارات موفق کے پاس تھے: فوج، خزانہ اور انتظام؛ معتمد صرف خطبے اور سکے میں نام کا خلیفہ تھا؛ جب اس نے اپنی بے بسی سے تنگ آ کر مصر میں ابنِ طولون کے پاس پناہ لینا چاہی تو موفق نے اسے راستے سے واپس بلوا لیا اور نظر بند جیسا رکھا۔","ملک انتشار اور بغاوتوں کی لپیٹ میں تھا: صفاریوں نے سجستان، کرمان، فارس اور خراسان پر قبضہ کیا اور یعقوب صفار نے طاہری حکومت ختم کی؛ صفار سے مقابلے میں معتمد زخمی ہو کر ہارا۔","زنج کی بغاوت (صاحب الزنج/ابن صوفی) طوفان کی طرح بڑھی، بصرہ کو تباہ کیا؛ عباسی فوجیں ناکام ہوتی رہیں؛ آخرکار موفق نے ہی برسوں کی جنگ کے بعد زنج کو کچلا اور صفاریوں کا مقابلہ کیا۔","مصر میں ابنِ طولون خود مختار ہو گیا؛ اس طرح خلافت کی طاقت گھٹتی گئی؛ معتمد رجب 279ھ میں فوت ہوا — ان حالات سے ثابت ہے کہ وہ محض نام کا حکمران تھا اور اصل حاکم موفق تھا۔"]}]}},"16":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l16-exercise-71",4]],"tf":"yn","s":["ہاں۔ بابک خرمی کی سرگرمیاں مامون کے دور سے شروع ہو چکی تھیں؛ معتصم کے دور میں افشین نے اسے گرفتار کیا۔"],"c":0},{"q":[["ihist12-l16-exercise-71",5]],"tf":"yn","n":"تاریخی روایات میں منکجور کے خلاف بھیجی گئی فوج کی قیادت بغا الکبیر کے پاس بتائی جاتی ہے؛ افشین کا نام سبق میں اس واقعے کے ساتھ نہیں آیا۔","s":["نہیں۔ سبق کے مطابق منکجور کو خلیفہ کی فوجوں نے شکست دی اور اس کے اپنے ساتھیوں نے اسے گرفتار کر کے خلیفہ کے حوالے کیا۔"],"c":1},{"q":[["ihist12-l16-exercise-71",6]],"tf":"yn","s":["ہاں۔ معتمد نے اپنے بھتیجے معتضد باللہ کو ولی عہد نامزد کیا تھا اور ربیع الاول 279ھ میں وہ تخت نشین ہوا۔"],"c":0},{"q":[["ihist12-l16-exercise-71",7]],"tf":"yn","s":["ہاں۔ بدر معتضد کے خاص امرا میں شمار ہوتا تھا؛ وزیر قاسم کی سازش میں شامل نہ ہونے کی وجہ سے قاسم نے اسے قتل کروا دیا۔"],"c":0},{"q":[["ihist12-l16-exercise-71",9]],"s":["عبیداللہ بن سلیمان","معتضد باللہ نے عبیداللہ بن سلیمان کو اپنا وزیر مقرر کیا۔"],"a":"عبیداللہ بن سلیمان"},{"q":[["ihist12-l16-exercise-71",10]],"s":["ہوشیار، دلیر اور بہادر","سیوطی کے مطابق معتضد بڑا ہوشیار، دلیر اور بہادر تھا اور اس نے خلافت کا وقار بحال کیا۔"],"a":"ہوشیار، دلیر اور بہادر"},{"q":[["ihist12-l16-exercise-71",11]],"s":["سفاحِ ثانی","خلافت کا وقار بحال کرنے کی وجہ سے معتضد کو سفاحِ ثانی (دوسرا سفاح) کہا جاتا ہے۔"],"a":"سفاحِ ثانی"},{"q":[["ihist12-l16-exercise-71",12]],"s":["مکتفی باللہ","معتضد کی وفات کے بعد اس کا بیٹا مکتفی باللہ تخت نشین ہوا جو اس وقت رقہ میں تھا۔"],"a":"مکتفی باللہ"},{"q":[["ihist12-l16-exercise-71",13]],"s":["مظالم","قرامطہ نے ایک دفعہ پھر مسلمانوں پر مظالم ڈھانا شروع کر دیے؛ ان کا سردار شیخ یحییٰ اپنے گروہ سمیت مارا گیا۔"],"a":"مظالم"},{"q":[["ihist12-l16-exercise-71",14]],"n":"بعض تاریخی کتب میں اس کا سال 306ھ لکھا ہے۔","s":["305","سبق کے مطابق 305ھ میں حسین بن حمدان کو قتل کر دیا گیا۔"],"a":"305"},{"q":[["ihist12-l16-exercise-71",15]],"s":["فاطمی","مصر (افریقہ) میں فاطمی حکومت قائم ہو گئی جو ہر لحاظ سے خود مختار تھی اور کسی کی سرپرستی قبول نہیں کرتی تھی؛ اس کا بانی ابو محمد عبیداللہ تھا۔"],"a":"فاطمی"},{"q":[["ihist12-l16-exercise-71",16]],"s":["مونس","مونس مقتدر کا معمولی غلام (خادم) تھا مگر اپنی صلاحیتوں سے ترقی کرتا گیا۔"],"a":"مونس"},{"q":[["ihist12-l16-exercise-71",17]],"s":["امیر الامراء","مقتدر نے مونس کو امیر الامراء بنا دیا۔"],"a":"امیر الامراء"},{"q":[["ihist12-l16-exercise-72",0]],"s":["محمد بن قاسم","قاہر نے مونس، علی اور بلیق کو قتل کروایا اور مونس کی جگہ محمد بن قاسم کو وزیر مقرر کیا۔"],"a":"محمد بن قاسم"},{"q":[["ihist12-l16-exercise-72",1]],"s":["قاہر باللہ","ترک کمانڈر سیما کی فوجوں نے محل کا محاصرہ کر کے قاہر باللہ کو گرفتار کیا اور اس کی آنکھوں میں گرم سلائیاں پھیر دیں۔"],"a":"قاہر باللہ"},{"q":[["ihist12-l16-exercise-72",2]],"s":["ابراہیم متقی باللہ","راضی (م 329ھ) کے بعد امرا نے اس کے بھائی ابراہیم متقی باللہ کو خلیفہ منتخب کیا۔"],"a":"ابراہیم متقی باللہ"},{"q":[["ihist12-l16-exercise-72",3]],"n":"تاریخی کتب کے مطابق بجکم کو کرد ڈاکوؤں نے قتل کیا تھا؛ جواب سبق کے الفاظ کے مطابق دیا گیا ہے۔","s":["شاگرد","سبق کے مطابق بجکم ایک شاگرد کے ہاتھوں مارا گیا۔"],"a":"شاگرد"},{"q":[["ihist12-l16-exercise-72",4]],"s":["خلیفہ","بویہی (دیلمی) حکمرانوں نے خلیفہ کو مفلوج کر کے وظیفہ مقرر کر دیا؛ صرف خطبے میں خلیفہ کا نام لیا جاتا تھا۔"],"a":"خلیفہ"}],"longQuestions":[{"q":[["ihist12-l16-exercise-71",1]],"n":"کتاب کے سوال میں نام \"محمد بن جعفر باللہ\" چھپا ہے؛ ترتیب کے لحاظ سے یہ مشق ابواب 14–16 (معتضد، مکتفی، مقتدر) سے متعلق ہے، اس لیے جواب مکتفی باللہ کے دور کا لکھا گیا ہے۔","s":["(یہ سوال مکتفی باللہ کے باب سے متعلق ہے) معتضد کی وفات کے بعد اس کا بیٹا ابو محمد علی مکتفی باللہ تخت نشین ہوا؛ وہ اس وقت رقہ میں تھا، معتضد کے وزیر نے بیعت لی اور پندرہ دن بعد جمادی الاولیٰ 289ھ میں وہ بغداد پہنچ کر حکومت سنبھال سکا۔","بدر کا قتل: بدر معتضد کے خاص امرا میں تھا؛ وزیر قاسم نے سازش کی اور معتضد کی وفات کے بعد مکتفی پر قابو پا لیا؛ بدر سازش میں شامل نہ تھا اس لیے قاسم نے اسے قتل کروا دیا۔","قرامطہ کی سرکوبی: قرامطہ نے پھر مظالم شروع کیے؛ ان کا سردار شیخ یحییٰ اپنے گروہ سمیت مارا گیا؛ بنو کلب کے زیب بن قاسم نے قرمطی سردار نصر کو قتل کر کے اس کا سر دربار میں پیش کیا؛ آخرکار قرامطہ کی قوت توڑ دی گئی۔","مصر کی بازیابی: طولونی حکومت کا خاتمہ کر کے مصر کو دوبارہ خلافت میں شامل کیا گیا؛ رومیوں کے خلاف مہمات اور انطاکیہ کی فتح۔","مکتفی نے تقریباً چھ سال حکومت کی اور 295ھ میں وفات پائی؛ وفات سے پہلے اپنے تیرہ سالہ چھوٹے بھائی جعفر (مقتدر) کو جانشین نامزد کیا۔"]},{"q":[["ihist12-l16-exercise-71",2]],"s":["جعفر بن معتضد المقتدر باللہ صرف 13 سال کی عمر میں مکتفی کی نامزدگی پر خلیفہ بنا؛ وزیر عباس بن حسن نے ذاتی مفاد کے لیے حمایت کی جبکہ امرا مخالف تھے۔","ابنِ معتز کی ایک دن کی خلافت: والیٔ موصل حسین بن حمدان نے عباس کو قتل کر کے ابنِ معتز کو \"مرتضیٰ باللہ\" کے لقب سے تخت پر بٹھایا؛ ابنِ حمدان کے موصل جانے پر مقتدر کی خلافت بحال ہوئی اور مخالف امرا قید یا قتل ہوئے؛ 305ھ میں حسین بن حمدان قتل ہوا۔","بغاوتیں: آرمینیا اور آذربائیجان کے حاکم ابنِ ابی الساج کو شکست دے کر گرفتار کیا؛ رے کی بدانتظامی پر قابو؛ کمزور صفاری حکومت 298ھ میں ختم ہوئی؛ قرامطہ کی لوٹ مار جاری رہی۔","فاطمی حکومت کا قیام: اب تک کی حکومتیں (صفاری، طاہری، سامانی، طولونی) خلیفہ کو مذہبی پیشوا مانتی تھیں، مگر افریقہ/مصر میں عبیداللہ کی قائم کردہ فاطمی حکومت ہر لحاظ سے خود مختار تھی۔","رومی مہمات: 296ھ میں مونس مظفر نے اناطولیہ پر حملہ کر کے مالِ غنیمت اور قیدی حاصل کیے؛ مونس کا عروج اور انجام: معمولی غلام سے امیر الامراء بنا، پھر اختلاف ہوا اور 320ھ کی جنگ میں مقتدر مارا گیا — یوں اس کا طویل دور (تقریباً 25 سال) زوال اور امرا کے غلبے کا دور ثابت ہوا۔"]}]}},"20":{"lang":"ur","items":{"mcqs":[{"q":[["ihist12-l20-exercise-79",4]],"ob":1,"s":["عقیدے کے لحاظ سے بنو بویہ (دیلمی) شیعہ تھے اور ان کی ہمدردیاں اہلِ بیت کے ساتھ تھیں۔"],"c":0},{"q":[["ihist12-l20-exercise-79",5]],"ob":1,"s":["سبکتگین نے 363ھ میں مطیع للہ کو بیٹے کے حق میں دستبردار ہونے پر مجبور کیا؛ مطیع واسط آیا اور وہیں فوت ہو گیا۔"],"c":2},{"q":[["ihist12-l20-exercise-79",6]],"ob":1,"n":"یہ سال سبق کے متن میں درج نہیں؛ جواب تاریخ کی معروف روایت سے ہے۔ (415ھ اور 416ھ سبق میں سلطان الدولہ اور شرف الدولہ کی وفات کے سال ہیں۔)","s":["سلطان محمود غزنوی نے 421ھ (1030ء) میں وفات پائی۔"],"c":2}],"objective":[{"q":[["ihist12-l20-exercise-79",8]],"s":["نابینا (اندھے)","مستکفی کو بھی اندھا کر دیا گیا؛ اب بغداد میں تین نابینا معزول خلفا (قاہر، متقی، مستکفی) گلیوں میں پھر رہے تھے۔"],"a":"نابینا (اندھے)"},{"q":[["ihist12-l20-exercise-79",9]],"s":["بنو بویہ","بنو بویہ (شیعہ) اور بنو حمدان (سنی) کے درمیان کافی عرصے تک اختلافات اور لڑائیاں جاری رہیں، آخرکار صلح ہوئی۔"],"a":"بنو بویہ"},{"q":[["ihist12-l20-exercise-79",10]],"s":["سنی","عقیدے کے لحاظ سے بنو حمدان سنی تھے۔"],"a":"سنی"},{"q":[["ihist12-l20-exercise-79",11]],"s":["خانہ جنگی","دیلمیوں میں خانہ جنگی شروع ہو گئی تو رومیوں نے سرحدی علاقوں میں تباہی پھیلائی۔"],"a":"خانہ جنگی"},{"q":[["ihist12-l20-exercise-79",12]],"s":["سیف الدولہ (حمدانی)","سرحدی علاقوں پر سیف الدولہ حمدانی کی حکومت قائم تھی جس نے 336ھ سے 363ھ تک رومیوں کا خوب مقابلہ کیا۔"],"a":"سیف الدولہ (حمدانی)"},{"q":[["ihist12-l20-exercise-79",13]],"s":["بختیار","بختیار نے جہاد کے لیے کافی رقم جمع کی مگر بعد میں اسے عیش و عشرت میں اڑا دیا۔"],"a":"بختیار"},{"q":[["ihist12-l20-exercise-79",14]],"s":["حمدانی خاندان","حمدانی خاندان نے مسلمانوں کو رومیوں کے مظالم سے نجات دلائی۔"],"a":"حمدانی خاندان"},{"q":[["ihist12-l20-exercise-79",15]],"s":["طائع للہ (عبدالکریم)","مطیع کی دستبرداری کے بعد اس کا بیٹا ابو الفضل عبدالکریم طائع للہ تخت نشین ہوا۔"],"a":"طائع للہ (عبدالکریم)"},{"q":[["ihist12-l20-exercise-79",16]],"s":["عضد الدولہ","بختیار کے چچا زاد بھائی عضد الدولہ نے بغداد پر قبضہ کر لیا اور بعد میں بختیار کو قتل کر کے اپنے نام کا خطبہ پڑھوایا۔"],"a":"عضد الدولہ"},{"q":[["ihist12-l20-exercise-79",17]],"s":["سبکتگین","غزنوی حکومت سبکتگین نے قائم کی جو الپتگین کا غلام تھا اور ترقی کر کے سپہ سالار بنا؛ اس خاندان کا مشہور حکمران سلطان محمود غزنوی تھا۔"],"a":"سبکتگین"},{"q":[["ihist12-l20-exercise-80",0]],"s":["بہاء الدولہ","شرف الدولہ کی وفات کے بعد اس کا بھائی بہاء الدولہ تخت نشین ہوا جس نے دولت کے لیے خلیفہ (طائع) کو گرفتار کر لیا۔"],"a":"بہاء الدولہ"},{"q":[["ihist12-l20-exercise-80",1]],"s":["402ھ","402ھ میں بہاء الدولہ فوت ہوا اور اس کا بیٹا سلطان الدولہ تخت نشین ہوا۔"],"a":"402ھ"},{"q":[["ihist12-l20-exercise-80",2]],"s":["422","عبداللہ (قائم بامر اللہ) 422ھ میں تخت نشین ہوا۔"],"a":"422"},{"q":[["ihist12-l20-exercise-80",3]],"s":["31","تخت نشینی کے وقت عبداللہ (قائم) کی عمر 31 سال تھی۔"],"a":"31"},{"q":[["ihist12-l20-exercise-80",4]],"s":["سلجوقی","دیلمی خانہ جنگی کا شکار ہوئے اور سلجوقی حکومت قائم ہو گئی جس نے عباسی خلافت پر قبضہ کر لیا۔"],"a":"سلجوقی"},{"q":[["ihist12-l20-exercise-80",5]],"s":["سلاجقہ (سلجوقی)","ملک شاہ کے بعد سلاجقہ خانہ جنگی کا شکار ہو گئے؛ اسی دور میں پہلی صلیبی جنگ ہوئی۔"],"a":"سلاجقہ (سلجوقی)"}],"longQuestions":[{"q":[["ihist12-l20-exercise-79",1]],"s":["ابو القاسم فضل بن مقتدر المطیع للہ مقتدر کا بیٹا تھا؛ بویہی معز الدولہ نے مستکفی کو معزول کر کے علوی حکومت قائم کرنا چاہی مگر سیاسی مصلحت کے تحت 334ھ میں 34 سالہ فضل بن مقتدر کو خلیفہ بنا دیا؛ مستکفی کو اندھا کر دیا گیا اور بغداد میں تین نابینا معزول خلفا رہ گئے۔","بنو بویہ اور بنو حمدان کی کشمکش: شیعہ بویہیوں اور سنی حمدانیوں کے درمیان خونریز جھڑپیں ہوتی رہیں، آخر صلح ہوئی؛ 338ھ میں عمران بن شاہین نے بطیحہ میں ریاست قائم کی؛ 356ھ میں معز الدولہ اس کے مقابلے کو نکلا مگر بیمار ہو کر مر گیا اور بختیار تخت پر بیٹھا۔","رومی حملے: دیلمیوں کی خانہ جنگی کے دوران رومیوں نے جزیرہ، شام، آرمینیا اور آذربائیجان پر حملے کیے؛ سیف الدولہ حمدانی نے 336ھ سے 363ھ تک مقابلہ کیا؛ بختیار نے جہاد کے لیے رقم جمع کر کے عیاشی میں اڑا دی؛ حمدانیوں نے مسلمانوں کو رومی مظالم سے نجات دلائی۔","خلیفہ کی بے بسی: تمام اختیارات بویہیوں کے پاس، خلیفہ کا وظیفہ مقرر اور صرف خطبے میں نام؛ ملک میں تباہی اور قحط — لوگ بھوک سے مرنے لگے۔","دستبرداری اور وفات: سبکتگین نے 363ھ میں اسے بیٹے (طائع) کے حق میں دستبردار ہونے پر مجبور کیا؛ مطیع واسط چلا گیا اور وہیں فوت ہوا؛ اس نے تقریباً 29 سال نام کی خلافت کی۔"]},{"q":[["ihist12-l20-exercise-79",2]],"s":["ابو جعفر عبداللہ بن قادر القائم بامر اللہ 422ھ میں 31 سال کی عمر میں تخت نشین ہوا؛ وہ دین دار، عالم، پرہیزگار اور باوقار خلیفہ تھا، مگر دیلمی طاقت بدستور قائم رہی اور اصل اختیار جلال الدولہ کے پاس تھا۔","فوجی بغاوت: حکومت کی آمدنی فوجی افسروں کے ہاتھ میں تھی، فوج کو تنخواہ نہ ملی تو جلال الدولہ کے خلاف بغاوت ہوئی جسے دبا دیا گیا؛ 435ھ میں جلال الدولہ فوت ہوا۔","دیلمیوں کی خانہ جنگی اور سلجوقیوں کا عروج: دیلمی آپس میں لڑنے لگے؛ سلجوقیوں نے اپنی حکومت مضبوط کی اور طغرل بیگ نے 447ھ میں بغداد میں داخل ہو کر بویہی اقتدار ختم کیا اور خلافت کو اپنی سرپرستی میں لے لیا؛ طغرل بیگ اور الپ ارسلان قابلِ ذکر ہیں۔","بساسیری کا فتنہ: ترک سردار بساسیری نے فاطمیوں کی حمایت سے بغداد پر قبضہ کر کے فاطمی خلیفہ کے نام کا خطبہ پڑھوایا اور قائم کو جلاوطن کیا؛ طغرل بیگ نے واپس آ کر بساسیری کو قتل کیا اور قائم کو عزت سے دوبارہ تخت پر بٹھایا۔","قائم نے تقریباً 45 سال خلافت کی اور 467ھ میں فوت ہوا؛ اس کے بعد اس کا پوتا مقتدی بامر اللہ تخت نشین ہوا؛ اس کا دور سلجوقیوں کے عروج اور دیلمی اقتدار کے خاتمے کا دور تھا۔"]}]}},"22":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l22-exercise-86",4]],"s":["ابو منصور (فضل المسترشد)","مستظہر نے اپنی زندگی ہی میں اپنے بیٹے ابو منصور (مسترشد باللہ) کو ولی عہد نامزد کر دیا تھا۔"],"a":"ابو منصور (فضل المسترشد)"},{"q":[["ihist12-l22-exercise-86",5]],"s":["سلجوقی","سلجوقی نہیں چاہتے تھے کہ خلیفہ اپنی حیثیت بحال کرے؛ اسی وجہ سے سلطان اور مسترشد کے اختلافات جنگ تک پہنچے۔"],"a":"سلجوقی"},{"q":[["ihist12-l22-exercise-86",6]],"s":["فاطمی خلفا","فاطمی خلفا بھی امرا اور وزرا کے ہاتھوں کٹھ پتلی بن چکے تھے؛ تمام اختیارات وزیروں کے پاس تھے۔"],"a":"فاطمی خلفا"},{"q":[["ihist12-l22-exercise-86",7]],"s":["تاتاری طوفان","اسی دور میں تاتاری طوفان اٹھا جس نے اسلامی سلطنتوں کو اپنی لپیٹ میں لے کر تباہ کر دیا۔"],"a":"تاتاری طوفان"},{"q":[["ihist12-l22-exercise-86",9]],"tf":"yn","s":["ہاں۔ ابو منصور (مسترشد) 512ھ میں تخت نشین ہوا۔"],"c":0},{"q":[["ihist12-l22-exercise-86",10]],"tf":"yn","s":["ہاں۔ اس وقت ابو منصور کی عمر 27 سال تھی۔"],"c":0},{"q":[["ihist12-l22-exercise-86",11]],"tf":"yn","s":["ہاں۔ مسترشد سلجوقی شکنجے سے نکل کر خلافت کو دوبارہ باوقار اور طاقتور بنانا چاہتا تھا اور خود جنگوں میں حصہ لیتا تھا۔"],"c":0},{"q":[["ihist12-l22-exercise-86",12]],"tf":"yn","s":["ہاں۔ 525ھ میں سلطان محمود (سلجوقی) فوت ہوا اور اس کے بعد سلطان مسعود برسرِ اقتدار آیا۔"],"c":0},{"q":[["ihist12-l22-exercise-86",13]],"tf":"yn","s":["ہاں۔ خوارزمی حکومت کا بانی خوارزم شاہ تھا؛ یہ حکومت صوبۂ خوارزم میں قائم ہوئی۔"],"c":0},{"q":[["ihist12-l22-exercise-86",14]],"tf":"yn","n":"سوال میں سن \"ء\" (عیسوی) لکھا ہے جبکہ سبق میں 536ھ ہے؛ اسی فرق کی بنا پر جواب \"نہیں\" ہے۔","s":["نہیں۔ خوارزم شاہ نے سلطان سنجر کو 536ھ (1141ء) میں شکست دی تھی، 536ء میں نہیں۔"],"c":1},{"q":[["ihist12-l22-exercise-86",15]],"tf":"yn","s":["ہاں۔ یوسف (مستنجد) کے دور میں نور الدین زنگی عیسائیوں (صلیبیوں) کے خلاف لڑتا رہا۔"],"c":0},{"q":[["ihist12-l22-exercise-86",16]],"tf":"yn","s":["ہاں۔ مقتفی نے 555ھ میں وفات پائی اور اس کے بعد اس کا بیٹا یوسف (مستنجد باللہ) تخت نشین ہوا۔"],"c":0},{"q":[["ihist12-l22-exercise-86",17]],"tf":"yn","s":["ہاں۔ فاطمی خلفا بھی امرا اور وزرا کے ہاتھوں کٹھ پتلی بن چکے تھے۔"],"c":0},{"q":[["ihist12-l22-exercise-87",0]],"tf":"yn","s":["ہاں۔ 567ھ میں فاطمی خلیفہ العاضد کی وفات پر فاطمی خلافت ختم ہوئی اور سلطان صلاح الدین ایوبی نے مصر میں ایوبی حکومت قائم کی۔"],"c":0},{"q":[["ihist12-l22-exercise-87",1]],"tf":"yn","s":["ہاں۔ مستضی کی وفات کے بعد اس کا بیٹا احمد (الناصر لدین اللہ) تخت نشین ہوا۔"],"c":0},{"q":[["ihist12-l22-exercise-87",2]],"tf":"yn","s":["ہاں۔ ستمبر 1187ء میں صلاح الدین ایوبی کی فتح کے بعد بیت المقدس مسلمانوں کے حوالے کر دیا گیا۔"],"c":0},{"q":[["ihist12-l22-exercise-87",3]],"tf":"yn","s":["ہاں۔ لین پول کے مطابق کئی مسلمان امرا نے غریب عیسائیوں کا فدیہ خود ادا کیا اور انہیں امن سے صور (ٹائر) پہنچایا گیا۔"],"c":0},{"q":[["ihist12-l22-exercise-87",4]],"tf":"yn","s":["ہاں۔ چنگیز خان اور اس کے بیٹوں نے مسلمانوں کے خون سے ہولی کھیلی؛ اس تباہی کی ایک وجہ خوارزم شاہ کی کوتاہ اندیشی تھی۔"],"c":0}],"longQuestions":[{"q":[["ihist12-l22-exercise-86",1]],"s":["ابو منصور فضل بن مستظہر المسترشد باللہ کو مستظہر نے اپنی زندگی میں ولی عہد بنایا؛ 512ھ میں 27 سال کی عمر میں تخت نشین ہوا اور عباسی خاندان نے اس کی بیعت کی۔","وہ ذہین، باہمت اور حوصلہ مند خلیفہ تھا؛ سلجوقی شکنجے سے نکل کر خلافت کو دوبارہ باوقار اور طاقتور بنانا چاہتا تھا اور خود جنگوں میں حصہ لیتا تھا۔","سلجوقی اس کی خود مختاری نہیں چاہتے تھے؛ سلطان محمود سے اختلافات جنگ تک پہنچے مگر صلح ہو گئی؛ 525ھ میں سلطان محمود کی وفات کے بعد سلطان مسعود سے کشیدگی رہی اور آخرکار جنگ ہوئی جس میں خلیفہ کو شکست ہوئی اور وہ گرفتار ہوا۔","سلطان سنجر نے مسعود کو ہدایت کی کہ خلیفہ کو باعزت واپس بھیجا جائے، مگر اسی دوران فرقہ باطنیہ کے فدائیوں نے 529ھ میں اسے قتل کر دیا؛ اس وقت اس کی عمر 43 سال تھی؛ سیوطی کے مطابق وہ بہادر، خوش خط اور اعلیٰ صفات کا حامل تھا۔"]},{"q":[["ihist12-l22-exercise-86",2]],"s":["ابو العباس احمد بن مستضی الناصر لدین اللہ (575–622ھ) نے تقریباً 47 سال حکومت کی جو عباسیوں میں سب سے طویل ہے؛ وہ قابل اور باصلاحیت خلیفہ تھا اور اس نے عباسی خلافت کا وقار کافی حد تک بحال کیا۔","بیت المقدس کی بازیابی: اس کے دور کا مشہور واقعہ صلاح الدین ایوبی کی فتحِ بیت المقدس (ستمبر 1187ء) ہے؛ صلیبیوں کے برعکس مسلمانوں نے فاتحانہ رواداری دکھائی — کسی عیسائی پر زیادتی نہ ہوئی، فدیہ دینے والوں کو امن سے جانے دیا گیا، کئی امرا نے غریب عیسائیوں کا فدیہ خود ادا کیا اور عورتوں کو عزت سے رخصت کیا گیا۔","سلجوقی حکومت کا خاتمہ: آخری سلجوقی حکمران طغرل بن ارسلان نے اعلان کیا کہ خلیفہ صرف امامت اور خطبے تک محدود رہے؛ ناصر نے خوارزم شاہ کی مدد سے سلجوقی اقتدار ختم کر کے خلافت کو بیرونی تسلط سے آزاد کرایا۔","خوارزم شاہ سے کشمکش: بعد میں خوارزم شاہ سے اختلاف ہوا؛ خوارزم شاہ کی کوتاہ اندیشی سے تاتاری طوفان اٹھا اور چنگیز خان نے اسلامی سلطنتوں کو تباہ کیا۔","انتظامی و رفاہی خدمات: خلافت کی خود مختاری، فتوت (جوانمردی) کی تنظیم کی سرپرستی، مدارس، کتب خانوں، سرائے اور مساجد کی تعمیر؛ 622ھ میں وفات — وہ آخری خلیفہ تھا جس میں اپنے اسلاف کی کچھ اچھی خصوصیات موجود تھیں۔"]}]}},"23":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l23-exercise-91",5]],"s":["منصور (المستنصر باللہ)","ظاہر کی وفات کے بعد اس کا بیٹا ابو جعفر منصور المستنصر باللہ 623ھ میں تخت نشین ہوا۔"],"a":"منصور (المستنصر باللہ)"},{"q":[["ihist12-l23-exercise-91",6]],"s":["خوارزمی","جلال الدین خوارزم شاہ تاتاریوں سے بچ کر ایک کرد کے پاس پناہ گزین ہوا مگر دوسرے کرد نے نیزہ مار کر قتل کر دیا؛ اس کی موت سے خوارزمی حکومت ختم ہو گئی۔"],"a":"خوارزمی"},{"q":[["ihist12-l23-exercise-91",7]],"s":["640","مستنصر نے 640ھ میں وفات پائی۔"],"a":"640"},{"q":[["ihist12-l23-exercise-91",8]],"s":["مستنصریہ","مستنصر کا سب سے بڑا کارنامہ بغداد میں مدرسہ مستنصریہ کا قیام ہے جس میں چاروں فقہی مذاہب کی تعلیم دی جاتی تھی۔"],"a":"مستنصریہ"},{"q":[["ihist12-l23-exercise-91",9]],"s":["نظامیہ","نظام الملک طوسی کی یادگار مدرسہ نظامیہ کہلاتا تھا جو مستنصریہ کے سامنے ماند پڑ گیا۔"],"a":"نظامیہ"},{"q":[["ihist12-l23-exercise-91",10]],"s":["وظیفہ (مفت کھانا اور رہائش)","مدرسے میں طلبہ کو مفت کھانا، رہائش اور وظیفہ بھی دیا جاتا تھا؛ ساتھ حمام بھی تھا۔"],"a":"وظیفہ (مفت کھانا اور رہائش)"},{"q":[["ihist12-l23-exercise-91",11]],"s":["248","مدرسے میں تقریباً 248 طلبہ تھے۔"],"a":"248"},{"q":[["ihist12-l23-exercise-91",12]],"s":["آخری","مستعصم باللہ (1243–1257ء) بنو عباس کا آخری حکمران تھا۔"],"a":"آخری"},{"q":[["ihist12-l23-exercise-91",13]],"s":["خاتمہ","مستعصم کے دور میں صلاح الدین کی قائم کردہ ایوبی حکومت کا خاتمہ ہوا (مصر میں مملوکوں نے اقتدار سنبھالا)۔"],"a":"خاتمہ"},{"q":[["ihist12-l23-exercise-91",14]],"s":["ابنِ علقمی","مستعصم کا وزیر ابنِ علقمی تھا جس نے فوج برخاست کر کے تاتاریوں کو بغداد پر حملے کی دعوت دی۔"],"a":"ابنِ علقمی"},{"q":[["ihist12-l23-exercise-91",15]],"s":["ہلاکو خان","ہلاکو خان نے 656ھ (1258ء) میں بغداد پر حملہ کیا۔"],"a":"ہلاکو خان"},{"q":[["ihist12-l23-exercise-91",16]],"s":["فرقہ","تاتاری مسلمانوں کے لیے عذاب بن کر آئے اور اس تباہی سے مسلمانوں کا کوئی فرقہ محفوظ نہ رہا۔"],"a":"فرقہ"},{"q":[["ihist12-l23-exercise-91",17]],"s":["سولہ لاکھ","ایک اندازے کے مطابق ہلاکو خان نے تقریباً سولہ لاکھ انسانوں کا خون بہایا۔"],"a":"سولہ لاکھ"}],"longQuestions":[{"q":[["ihist12-l23-exercise-91",2]],"s":["ابو جعفر منصور المستنصر باللہ ظاہر کا بیٹا تھا اور 623ھ میں تخت نشین ہوا؛ اس نے عباسی خلافت میں نئی روح پھونکنے کی کوشش کی اور ملک میں ترقی کا سلسلہ شروع ہوا۔","اہم واقعات: صلاح الدین ایوبی کی وفات کے بعد اس کے بیٹوں کی خانہ جنگی سے فائدہ اٹھا کر عیسائیوں نے عارضی طور پر بیت المقدس پر قبضہ کر لیا؛ جلال الدین خوارزم شاہ تاتاریوں سے بھاگ کر ایک کرد کے ہاتھوں مارا گیا اور خوارزمی حکومت ختم ہوئی۔","مدرسہ مستنصریہ: اس کا سب سے بڑا کارنامہ بغداد میں مدرسہ مستنصریہ کا قیام ہے جس کے سامنے مدرسہ نظامیہ بھی ماند پڑ گیا؛ اس میں چاروں فقہی مذاہب کی تعلیم دی جاتی تھی؛ تقریباً 248 طلبہ کو مفت کھانا، رہائش اور وظیفہ ملتا تھا؛ ساتھ حمام، کتب خانہ، ہسپتال اور باورچی خانہ بھی تھا۔","وہ علم دوست، عادل اور رفاہِ عامہ کا شوقین تھا؛ تاتاری خطرے کے مقابلے کے لیے فوج تیار کی؛ 640ھ میں وفات پائی۔"]},{"q":[["ihist12-l23-exercise-91",3]],"s":["ابو احمد عبداللہ بن مستنصر المستعصم باللہ بنو عباس کا آخری حکمران (1243–1257ء) تھا؛ خلافت کا حق دار مستنصر کا بھائی تھا مگر امرا نے اپنے مفاد میں 640ھ میں مستنصر کے بیٹے کو تخت پر بٹھایا۔","وہ ذاتی طور پر شریف آدمی تھا مگر حکومت چلانا اس کے بس میں نہیں تھا؛ اس کے دور میں دو بڑے واقعات ہوئے: صلاح الدین کی ایوبی حکومت کا خاتمہ اور تاتاریوں کے ہاتھوں بغداد کی تباہی۔","بغداد میں شیعہ سنی اختلافات عروج پر تھے؛ خلیفہ کے بیٹے ابوبکر اور امیر نور الدین نے کرخ کا شیعہ محلہ لٹوایا؛ شیعہ وزیر ابنِ علقمی عباسی حکومت ختم کر کے علوی حکومت قائم کرنا چاہتا تھا؛ اس نے فوج برخاست کر دی اور ابنِ خلدون کے مطابق اربل کے گورنر کے ذریعے (اور ابو الفدا کے مطابق اپنے بھائی کے ذریعے) تاتاریوں کو حملے کی دعوت دی۔","سقوطِ بغداد: محرم 656ھ (1258ء) میں ہلاکو خان نے بغداد پر حملہ کیا؛ مرد، عورتیں، بوڑھے اور بچے قتل ہوئے؛ کتب خانے کی کتابیں دجلہ میں بہا دی گئیں؛ تقریباً سولہ لاکھ انسان مارے گئے؛ ابنِ علقمی نے اپنی جان بخشی کروا کر خلیفہ کو علما و فقہا سمیت قتل کروا دیا اور خود چند دن بعد ذلت سے مرا۔","اس طرح تقریباً پانچ سو سالہ عباسی خلافت کا بغداد میں خاتمہ ہو گیا؛ اس کا سبق یہ ہے کہ باہمی نفرت کی دیواریں کھڑی کرنے والوں کا انجام تباہی ہے۔"]}]}},"24":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l24-exercise-107",7]],"s":["مخلوق","معتزلہ کے عقیدے کے مطابق قرآن مخلوق ہے (خلقِ قرآن)؛ مامون اس عقیدے کا بہت بڑا حامی تھا۔"],"a":"مخلوق"},{"q":[["ihist12-l24-exercise-107",8]],"s":["واصل بن عطاء","معتزلہ کا بانی واصل بن عطاء تھا جو حضرت حسن بصریؒ کا شاگرد تھا؛ کبیرہ گناہ کے مسئلے پر استاد سے الگ ہو کر بیٹھ گیا، اسی لیے معتزلہ (الگ ہونے والے) کہلائے۔"],"a":"واصل بن عطاء"},{"q":[["ihist12-l24-exercise-107",9]],"s":["حمدان (قرمط)","قرامطہ کا بانی حمدان تھا جو چھوٹے چھوٹے قدم چلتا تھا؛ ایسے شخص کو عربی میں \"قرمطی\" کہتے ہیں۔"],"a":"حمدان (قرمط)"},{"q":[["ihist12-l24-exercise-107",10]],"s":["اسماعیلیہ باطنیہ","قرامطہ دراصل فرقہ اسماعیلیہ باطنیہ کی ایک شاخ تھے؛ یہ اشتراکیت سے ملتا جلتا فرقہ تھا۔"],"a":"اسماعیلیہ باطنیہ"},{"q":[["ihist12-l24-exercise-107",11]],"s":["110","بویہی خاندان نے 945ء سے 1055ء تک تقریباً ایک سو دس سال بنو عباس کو دبائے رکھا؛ ان کا دار الحکومت شیراز تھا۔"],"a":"110"},{"q":[["ihist12-l24-exercise-107",12]],"s":["عضد الدولہ","بویہی سلاطین میں عضد الدولہ پہلا حکمران تھا جسے ملک الملوک یا شہنشاہ کہا گیا۔"],"a":"عضد الدولہ"},{"q":[["ihist12-l24-exercise-107",13]],"s":["طغرل بیگ","18 دسمبر 1055ء کو سلجوقی حکمران طغرل بیگ خلیفہ قائم کی درخواست پر بغداد میں داخل ہوا۔"],"a":"طغرل بیگ"},{"q":[["ihist12-l24-exercise-107",14]],"s":["اصفہان","سلجوقی دار الحکومت مرو سے اصفہان منتقل ہو چکا تھا؛ بغداد کی نگرانی صرف ایک سلجوقی فوجی گورنر کرتا تھا۔"],"a":"اصفہان"},{"q":[["ihist12-l24-exercise-107",15]],"s":["سنی","عقیدے کے لحاظ سے سلجوقی سنی تھے اور بویہی (دیلمی) شیعہ؛ سلجوقی عباسی خلفا کا بہت احترام کرتے تھے۔"],"a":"سنی"},{"q":[["ihist12-l24-exercise-107",16]],"s":["فاطمیوں","اسی دور میں عبیداللہ نے مصر (شمالی افریقہ) میں فاطمی حکومت قائم کی۔"],"a":"فاطمیوں"},{"q":[["ihist12-l24-exercise-108",0]],"s":["صلیب","عیسائی یہ جنگیں صلیب کے نام پر لڑ رہے تھے، اسی لیے یہ صلیبی جنگیں کہلاتی ہیں۔"],"a":"صلیب"},{"q":[["ihist12-l24-exercise-108",1]],"s":["فرانس","26 نومبر 1095ء کو پوپ نے فرانس (کلیرمونٹ) میں کونسل بلا کر مسلمانوں کے خلاف جنگ کی اپیل کی۔"],"a":"فرانس"},{"q":[["ihist12-l24-exercise-108",2]],"s":["بیت المقدس","پہلی صلیبی جنگ میں عیسائیوں نے بیت المقدس پر قبضہ کر کے مسلمانوں کا قتلِ عام کیا اور گاڈفرے کو حکمران بنایا۔"],"a":"بیت المقدس"},{"q":[["ihist12-l24-exercise-108",3]],"s":["صلاح الدین ایوبی","دوسری صلیبی جنگ (کے مرحلے) میں سلطان صلاح الدین ایوبی نے 1187ء میں بیت المقدس پر قبضہ کر لیا۔"],"a":"صلاح الدین ایوبی"},{"q":[["ihist12-l24-exercise-108",4]],"s":["رچرڈ، فریڈرک، فلپ","تیسری صلیبی جنگ میں انگلستان کا رچرڈ شیر دل، جرمنی کا فریڈرک اور فرانس کا فلپ مسلمانوں کے خلاف متحد ہوئے۔"],"a":"رچرڈ، فریڈرک، فلپ"},{"q":[["ihist12-l24-exercise-108",5]],"s":["فدیہ","صلاح الدین ایوبی نے دس ہزار عیسائی سپاہیوں کا فدیہ اپنی جیب سے ادا کیا۔"],"a":"فدیہ"},{"q":[["ihist12-l24-exercise-108",6]],"s":["ناکام","صلاح الدین نے مسلمان حکمرانوں سے مدد لینے کی کوشش کی مگر ناکام رہا اور اکیلے میدان میں اترا۔"],"a":"ناکام"},{"q":[["ihist12-l24-exercise-108",7]],"s":["صلح","تیسری صلیبی جنگ کے بعد (1192ء) عیسائیوں اور مسلمانوں کے درمیان صلح (صلح نامہ رملہ) ہوئی۔"],"a":"صلح"},{"q":[["ihist12-l24-exercise-108",8]],"s":["دوائیں اور پھل","رچرڈ اور فلپ بیمار ہوئے تو صلاح الدین ایوبی نے ان کے لیے دوائیں اور پھل بھیجے۔"],"a":"دوائیں اور پھل"}],"longQuestions":[{"q":[["ihist12-l24-exercise-107",1]],"s":["مسلمانوں اور عیسائیوں کے درمیان بیت المقدس کے لیے تقریباً دو سو سال (1095–1291ء) جنگیں ہوتی رہیں؛ عیسائی یہ جنگیں صلیب کے نام پر لڑتے تھے اس لیے یہ صلیبی جنگیں کہلائیں۔","اسباب: (1) عیسائیوں کی مسلمانوں پر برتری کی خواہش، حسد اور نفرت؛ (2) زائرین کے ساتھ راستے کی وارداتوں کو مسلمانوں سے منسوب کر کے پروپیگنڈا؛ (3) یورپی حکمرانوں کی خانہ جنگیاں — پادریوں نے ان کی فوجی طاقت کا رخ مقدس شہر کی طرف موڑا؛ (4) تجارتی مفادات — بحیرۂ روم پر مسلمانوں کا قبضہ؛ (5) عباسیوں کی کمزوری اور خانہ جنگیاں؛ (6) فوری سبب — سلجوقیوں نے کومنینس کے ایشیائی مقبوضات لیے، اس نے پوپ سے فریاد کی اور پوپ نے 26 نومبر 1095ء کو فرانس میں کونسل بلا کر جنگ کی اپیل کی۔","نتائج: (1) یورپ میں علمی ترقی — مشرق و مغرب کے میل سے مسلمانوں کے علمی خزانے سے یورپی دانشوروں نے فائدہ اٹھایا؛ (2) تجارتی منڈیاں — ایشیائی اشیا کی تجارت بڑھی؛ (3) زراعت — کاشت اور آبپاشی کے جدید طریقے یورپ پہنچے۔","دیگر نتائج: جاگیرداری اور پوپ کے اقتدار کو دھچکا؛ یورپ میں نشاۃِ ثانیہ کی راہ ہموار؛ مسلمانوں میں اتحاد کا جذبہ (زنگی، ایوبی) مگر جانی و مالی نقصان؛ مسلم و مسیحی تعلقات میں صدیوں کی تلخی۔"]},{"q":[["ihist12-l24-exercise-107",2]],"s":["سلجوقی ترک قبیلہ تھا جس کا جدِ امجد سلجوق تھا؛ طغرل (بن میکائیل) اور اس کا بھائی خراسان آئے اور غزنویوں کی ملازمت کی؛ محمود غزنوی کے بعد غزنوی حکومت کمزور ہوئی تو انہوں نے نیشاپور اور مرو پر قبضہ کیا؛ طغرل نے جرجان، طبرستان اور خوارزم فتح کیے اور رے کو دار الحکومت بنایا۔","خلیفہ قائم کی درخواست پر 18 دسمبر 1055ء کو طغرل بیگ بغداد میں داخل ہوا اور دیلمی اقتدار ختم کیا؛ سلجوقی سنی تھے اور عباسی خلفا کا بہت احترام کرتے تھے، خلیفہ سے رشتہ داری قائم کی۔","الپ ارسلان: متقی اور قابل حکمران؛ آرمینیا کا دار الحکومت فتح کیا؛ ملازکرد (1071ء) میں رومی قیصر کو شکست دی؛ 1072ء میں وفات۔","ملک شاہ: اس کا دور امن و امان کا دور تھا؛ وزیر نظام الملک طوسی نے مدارسِ نظامیہ قائم کیے؛ سلجوقی دار الحکومت مرو سے اصفہان منتقل ہوا؛ سلجوقیانِ روم کی سلطنت (قونیہ) سلیمان نے 1077ء میں قائم کی۔","ملک شاہ کے بعد سلجوقی خانہ جنگی کا شکار ہوئے؛ صلیبی جنگوں کا مقابلہ کیا مگر کمزور ہوتے گئے؛ آخری حکمران طغرل بن ارسلان کو خوارزم شاہ نے ناصر کے دور میں ختم کیا۔"]},{"q":[["ihist12-l24-exercise-107",3]],"s":["پہلی صلیبی جنگ: پادریوں نے تقریباً تیرہ لاکھ کی فوج جمع کی جس کا سربراہ پیٹر راہب تھا؛ راستے میں آپس کی لڑائی، وبا اور قحط سے صرف بیس ہزار بیت المقدس پہنچے؛ بیت المقدس مصر کے پاس تھا، کسی مسلم حکمران نے مقابلہ نہ کیا؛ عیسائیوں نے قبضہ کر کے قتلِ عام کیا اور گاڈفرے کو حکمران بنایا۔","دوسری صلیبی جنگ: مسلمان حکمران وقتی طور پر بیدار ہوئے؛ عماد الدین زنگی (اتابک موصل) اور اس کے بیٹے نور الدین زنگی نے جہاد کیا؛ نور الدین کے نائب صلاح الدین ایوبی نے فاطمی خلیفہ کی وفات کے بعد مصر میں عباسی خطبہ جاری کیا، حجاز اور یمن کو شامل کیا اور 1187ء میں (حطین کے بعد) بیت المقدس کا محاصرہ کر کے فتح کیا۔","تیسری صلیبی جنگ: صلاح الدین کے قبضے پر یورپ میں آگ لگ گئی؛ رچرڈ شیر دل (انگلستان)، فریڈرک (جرمنی) اور فلپ (فرانس) عکہ کے قریب جمع ہوئے؛ 1189–1192ء تک سخت جنگیں؛ فریڈرک دریا عبور کرتے ڈوب گیا؛ رچرڈ مجبور ہو کر صلح پر راضی ہوا اور دونوں طرف آزادانہ آمد و رفت کا اعلان ہوا۔","سلطان صلاح الدین کی خدمات: مسلمانوں کو متحد کیا؛ بیت المقدس آزاد کرایا جو صدیوں مسلمانوں کے پاس رہا؛ فتح کے بعد بدلے کے بجائے رحم — صلیبی فوج کو چالیس دن کی مہلت، دس ہزار سپاہیوں کا فدیہ اپنی جیب سے ادا کیا، عورتوں کو عزت سے رخصت کیا؛ دشمن رچرڈ اور فلپ کی بیماری میں دوائیں اور پھل بھیجے؛ مسلم حکمرانوں کی بے رخی کے باوجود اکیلے یورپ کا مقابلہ کیا؛ صلح کے چھ ماہ بعد دمشق میں وفات پائی۔"]},{"q":[["ihist12-l24-exercise-107",5]],"s":["بویہی یا دیلمی خاندان کا جدِ امجد ابو شجاع بویہ بن فناخسرو تھا؛ یہ دیلم (بحیرۂ کیسپین کے جنوب) کے رہنے والے تھے اس لیے دیلمی کہلائے؛ عقیدے کے لحاظ سے شیعہ تھے۔","بویہ کے تین بیٹے علی، حسن اور احمد تھے؛ انہوں نے فارس، رے اور اصفہان پر حکومت قائم کی؛ سب سے چھوٹا احمد (معز الدولہ) 945ء میں بغداد میں داخل ہوا؛ خلیفہ مستکفی نے استقبال کیا مگر جنوری 946ء میں احمد نے اسے معزول کر کے اندھا کر دیا؛ بغداد کی گلیوں میں تین نابینا معزول خلفا پھرتے تھے۔","بویہیوں نے 945ء سے 1055ء تک تقریباً 110 سال عباسی خلفا کو دبائے رکھا؛ ان کا دار الحکومت شیراز تھا اور عراق صوبے کی حیثیت رکھتا تھا؛ خلیفہ کا وظیفہ مقرر کیا اور صرف خطبے میں نام رہ گیا۔","عضد الدولہ سب سے نمایاں بویہی سلطان تھا: پہلا حکمران جسے ملک الملوک یا شہنشاہ کہا گیا؛ اپنی بیٹی طائع سے بیاہی؛ بغداد میں رفاہِ عامہ کے بڑے کام — عمارتیں، مساجد، ہسپتال (بیمارستان عضدی)، نہروں کی صفائی؛ علم و ادب کی سرپرستی۔","زوال: عضد الدولہ کے بعد خانہ جنگی؛ بہاء الدولہ، سلطان الدولہ، شرف الدولہ اور جلال الدولہ کمزور ثابت ہوئے؛ آخرکار 1055ء میں طغرل بیگ سلجوقی نے بغداد میں داخل ہو کر بویہی اقتدار ختم کر دیا۔"]}]}},"25":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l25-exercise-124",13]],"s":["سپاہی","معتصم باللہ علم سے بالکل کورا مگر بہت بہادر اور دلیر تھا، اس لیے مورخین اسے \"سپاہی خلیفہ\" بھی کہتے ہیں۔"],"a":"سپاہی"},{"q":[["ihist12-l25-exercise-124",14]],"s":["احمد بن حنبل","معتصم نے امام احمد بن حنبلؒ پر بہت ظلم کیا اور کوڑے لگوائے کیونکہ وہ معتزلی عقائد (خلقِ قرآن) کے سخت خلاف تھے۔"],"a":"احمد بن حنبل"},{"q":[["ihist12-l25-exercise-124",15]],"s":["معتزلی","متوکل کا سب سے بڑا کارنامہ معتزلی عقائد کا قلع قمع ہے؛ اس نے مناظروں کا سلسلہ بند کروایا۔"],"a":"معتزلی"},{"q":[["ihist12-l25-exercise-124",16]],"s":["تاتار (منگولیا)","چنگیز خان ترکستان کے شمال میں منگولیا کے وسیع صحرا کے علاقے تاتار سے تعلق رکھتا تھا؛ اس نے قراقرم کو دار الحکومت بنایا۔"],"a":"تاتار (منگولیا)"},{"q":[["ihist12-l25-exercise-125",0]],"n":"تاریخ کے مطابق چنگیز خان کا فوری جانشین اس کا بیٹا اوگدائی خان تھا؛ منگو خان بعد میں (1251ء) خاقان بنا۔ جواب سبق کے مطابق دیا گیا ہے۔","s":["منگو خان","سبق کے مطابق چنگیز خان کی وفات کے بعد اس کا پوتا منگو خان تخت نشین ہوا جس نے اپنے بھائی ہلاکو خان کو اسلامی علاقے فتح کرنے کی ہدایت کی۔"],"a":"منگو خان"},{"q":[["ihist12-l25-exercise-125",1]],"s":["شیعہ","عقیدے کے لحاظ سے ابنِ علقمی شیعہ تھا۔"],"a":"شیعہ"},{"q":[["ihist12-l25-exercise-125",2]],"s":["شیعانِ علی","شروع میں عباسیوں نے شیعانِ علیؓ کے ساتھ مل کر بنو امیہ کے خلاف تحریک چلائی مگر اقتدار خود سنبھال لیا۔"],"a":"شیعانِ علی"},{"q":[["ihist12-l25-exercise-125",3]],"s":["ابو مسلم","منصور نے ایرانیوں سے شک کی بنا پر ابو مسلم خراسانی کو قتل کروایا۔"],"a":"ابو مسلم"},{"q":[["ihist12-l25-exercise-125",4]],"n":"سوال کے انگریزی ترجمے میں نام \"مستعصم\" ہے؛ سبق کے مطابق یہ کام معتصم نے کیا تھا۔","s":["ترکوں","معتصم نے خلا کو پُر کرنے کے لیے ترکوں کو بڑے بڑے عہدے دیے اور اقتدار میں شامل کیا — یہ عباسیوں کی خطرناک غلطی تھی۔"],"a":"ترکوں"},{"q":[["ihist12-l25-exercise-125",5]],"s":["نسلی","عباسیوں کے دور میں نسلی تعصب عروج پر پہنچ گیا تھا؛ عرب، عجمی اور ایرانی ایک دوسرے کو نیچا دکھانے میں مصروف رہے۔"],"a":"نسلی"},{"q":[["ihist12-l25-exercise-125",6]],"s":["ہلاکو خان","ہلاکو خان نے 656ھ (1258ء) میں بغداد کو تباہ و برباد کر دیا۔"],"a":"ہلاکو خان"},{"q":[["ihist12-l25-exercise-125",7]],"s":["وزارت","عباسی خلفا نے اپنی آسانی کے لیے وزارت کا باقاعدہ عہدہ قائم کیا جو ایرانی حکومتوں میں موجود تھا۔"],"a":"وزارت"},{"q":[["ihist12-l25-exercise-125",8]],"s":["امیر الامراء (مدار المہام)","وزیرِ تفویض کو مدار المہام بھی کہتے تھے اور اسے امیر الامراء بھی کہا جاتا تھا؛ خلیفہ کے بعد اسی کا دوسرا مقام تھا۔"],"a":"امیر الامراء (مدار المہام)"},{"q":[["ihist12-l25-exercise-125",9]],"s":["حاجب","وزیر کے بعد دوسرا مقام حاجب کا تھا؛ اس کی اجازت کے بغیر کوئی خلیفہ سے نہیں مل سکتا تھا۔"],"a":"حاجب"},{"q":[["ihist12-l25-exercise-125",10]],"s":["صاحب الشرطہ","پولیس (دیوان الاحداث) کا سربراہ صاحب الشرطہ کہلاتا تھا۔"],"a":"صاحب الشرطہ"},{"q":[["ihist12-l25-exercise-125",11]],"s":["امیر (والی، عامل)","صوبے کا سربراہ امیر، والی یا عامل کہلاتا تھا جسے خلیفہ خود مقرر کرتا تھا۔"],"a":"امیر (والی، عامل)"},{"q":[["ihist12-l25-exercise-125",12]],"s":["چوبیس (24)","بنو عباس کے دور میں تقریباً چوبیس صوبے تھے جن میں مصر اور شمالی افریقہ بڑے صوبے تھے۔"],"a":"چوبیس (24)"},{"q":[["ihist12-l25-exercise-125",13]],"s":["دو","اسلامی فوج دو قسم کی تھی: باقاعدہ فوج اور رضاکار فوج۔"],"a":"دو"},{"q":[["ihist12-l25-exercise-125",14]],"s":["ایک ہزار سپاہیوں","ایک ہزار سپاہیوں (دس نقیبوں) کا افسر قائد کہلاتا تھا؛ دس سپاہیوں کا عریف، سو کا نقیب اور دس ہزار کا سپہ سالار۔"],"a":"ایک ہزار سپاہیوں"}],"longQuestions":[{"q":[["ihist12-l25-exercise-123",5]],"s":["بنو عباس کے زوال کے اسباب: (1) عیش پرست حکمران — ابتدائی چند خلفا کے بعد خلفا شراب، موسیقی اور کنیزوں کی محفلوں میں ڈوب گئے اور عوام سے دور ہو گئے؛ (2) شیعانِ علیؓ سے سلوک — ان کے ساتھ مل کر تحریک چلائی مگر اقتدار خود لے لیا؛ منصور کے دور سے بغاوتیں؛ طبرستان اور مصر میں شیعہ حکومتیں؛ آخرکار ابنِ علقمی نے ہلاکو کو بلایا۔","(3) عجمیوں سے سلوک — ایرانیوں کو ساتھ لائے مگر ان سے خائف رہے؛ ابو مسلم کا قتل اور برامکہ کی تباہی؛ (4) ترکوں کی شمولیت اور صوبوں کی خود مختاری — معتصم نے ترکوں کو بڑے عہدے دیے، ترکوں نے خلفا کو مفلوج کر دیا اور صوبے خود مختار ہوتے گئے۔","(5) نسلی تعصب — عرب، عجمی اور ایرانی ایک دوسرے کے خلاف سازشیں کرتے رہے؛ (6) فوج سے غفلت — فوج عیش پسند اور ناکارہ ہو گئی؛ (7) شخصی اور مطلق العنان طرزِ حکومت — حکمران نااہل ہوا تو ملک ڈوب گیا۔","(8) معاشی بدحالی — فضول خرچی کے لیے بھاری ٹیکس، سیلاب اور قحط؛ (9) مرکز اور صوبوں کے ناخوشگوار تعلقات اور گورنروں کی سازشیں؛ (10) ہلاکو خان کا حملہ — جس نے صدیوں پرانی حکومت اور تہذیب کے خزانے بہا دیے؛ دجلہ کا پانی پہلے خون سے سرخ پھر کتابوں کی سیاہی سے سیاہ ہو گیا۔"]},{"q":[["ihist12-l25-exercise-123",6]],"s":["مرکزی حکومت: بنو عباس کا انتظام تقریباً بنو امیہ جیسا تھا، صرف وزارت اور حاجب کے عہدے اور کچھ نئے محکمے شامل ہوئے؛ خلیفہ سربراہِ حکومت کے ساتھ مذہبی پیشوا اور افواج کا سپہ سالار تھا؛ مجلسِ شوریٰ نہیں تھی اور خلیفہ مطلق العنان تھا۔","وزارت: (الف) وزیرِ تفویض (مدار المہام/امیر الامراء) — لامحدود اختیارات، خلیفہ کے بعد دوسرا مقام؛ (ب) وزیرِ تنفیذ — محدود اختیارات، خلیفہ اور عوام کے درمیان رابطہ اور احکام پر عمل درآمد۔ حاجب — وزیر کے بعد دوسرا مقام، ملاقات اسی کی اجازت سے، خلیفہ کا مشیر؛ شاہی جلاد۔","مرکزی محکمے (دواوین): دیوان العزیز (نگرانِ اعلیٰ، سربراہ وزیرِ اعظم)، دیوان الخراج (آمدنی و خرچ، خراج، زکوٰۃ، جزیہ، عشر)، دیوان الرسائل (شاہی فرامین، معاہدے، خطوط)، دیوان البرید (ڈاک، تیز گھوڑے اور کبوتر، صاحب البرید)، دیوان الاحداث (پولیس، صاحب الشرطہ)، دیوان العرض (فوج اور اسلحہ ساز کارخانے)، دیوان الغمام (غیر مسلم اقلیتیں)، دیوان التوقیع (درخواستوں کے جواب)، دیوان الضیاع (شاہی جائیدادیں)، دیوان العطاء (سرکاری عطیات)، دیوان الموالی (غلاموں کے حقوق)، دیوان الاقرحہ (نہریں)۔","صوبائی نظام: سلطنت تقریباً چوبیس صوبوں میں تقسیم تھی (مصر، شمالی افریقہ وغیرہ)؛ صوبے کا سربراہ امیر، والی یا عامل خلیفہ مقرر کرتا؛ شروع میں جلد تبادلے ہوتے مگر بعد میں امرا مستقل ہو کر خود مختاری کا اعلان کرنے لگے؛ امیر صوبائی عملہ خود مقرر کرتا؛ قاضی اور سپہ سالار خلیفہ مقرر کرتا تھا۔","عدلیہ: قاضی القضاۃ کا عہدہ (امام ابو یوسف پہلے قاضی القضاۃ)؛ ہر صوبے اور شہر میں قاضی؛ محتسب بازاروں کی نگرانی کرتا۔"]},{"q":[["ihist12-l25-exercise-123",7]],"s":["بنو عباس کی فوج دنیا کی بہترین افواج میں شمار ہوتی تھی؛ بنو امیہ کی فوج صرف عربوں پر مشتمل تھی جبکہ عباسیوں نے سلطنت کے تمام لوگوں کو بھرتی کیا اور سب سے یکساں سلوک کیا؛ تنخواہوں میں بھی فرق نہیں تھا۔","فوج کے حصے: منصور کے دور میں تین بڑے دستے — شمالی عرب (مضری)، جنوبی عرب (یمانی) اور خراسانی؛ معتصم کے دور میں ترکی اور افریقی دستے بھی شامل ہوئے؛ یہ پالیسی آخرکار خطرناک ثابت ہوئی کیونکہ ان دستوں میں اقتدار کی کشمکش شروع ہو گئی۔","فوج کی دو قسمیں: (الف) باقاعدہ فوج — نقد تنخواہ (بنو امیہ کے مقابلے میں کم)؛ (ب) رضاکار فوج — جہاد کے جذبے سے جنگ کے وقت شامل؛ باقاعدہ تنخواہ نہیں مگر جنگ کے دوران اسلحہ اور خوراک اور ان کے بیوی بچوں کے وظیفے مقرر۔","فوجی عہدے: دس سپاہیوں کا افسر عریف، سو کا نقیب، ہزار کا قائد اور دس ہزار کا سپہ سالار؛ دیوان العرض فوجی انتظامات اور اسلحہ سازی کا ذمہ دار تھا۔","اسلحہ: پیادہ فوج — نیزے، تیر کمان، تلواریں، کلہاڑے اور زرہ؛ سوار فوج، منجنیق اور آتش گیر مادہ (نفط)؛ سرحدوں پر قلعے اور چھاؤنیاں؛ بعد کے دور میں خلفا کی غفلت سے فوج عیش پسند اور ناکارہ ہو گئی۔"]},{"q":[["ihist12-l25-exercise-124",1]],"s":["منصور بنو عباس کا حقیقی بانی ہے کیونکہ سفاح نے صرف چار سال خون ریزی میں گزارے اور خلافت کمزور تھی؛ منصور نے بائیس سال انتھک محنت سے اسے مستحکم کیا۔","دلائل: (1) خطرناک حریفوں کا خاتمہ — چچا عبداللہ بن علی، طاقتور ابو مسلم خراسانی، راوندیہ، سنباد، نفس زکیہ اور ابراہیم کی بغاوتیں؛ (2) نیا دار الحکومت بغداد آباد کیا جو صدیوں عالمِ اسلام کا مرکز رہا۔","(3) انتظامی ڈھانچہ — وزارت کے ساتھ حاجب اور کاتب؛ صوبوں میں والی، خلیفہ کی طرف سے قاضی اور سپہ سالار؛ جاسوسی کا جال؛ (4) کفایت شعاری سے بھرا ہوا خزانہ اور منظم مالیات؛ (5) فوج میں خراسانیوں کو ترجیح۔","(6) مذہبی پیشوائی کا اعلان اور علما سے فتوے — اسی لیے یہ خاندان پانچ سو سال حکمران رہا؛ (7) اپنے بیٹے مہدی کو ولی عہد بنا کر جانشینی طے کی؛ (8) فتوحات — کوہستان، طبرستان، دماوند؛ رومیوں کی پسپائی؛ (9) علوم کی سرپرستی اور تراجم کا آغاز۔"]},{"q":[["ihist12-l25-exercise-124",2]],"s":["ہارون الرشید (170–193ھ) کا دور تاریخِ اسلام کا سنہری باب ہے؛ اس دور میں خلافت سماجی، علمی اور سیاسی لحاظ سے پورے عروج پر پہنچی؛ طاقت، دولت اور شان و شوکت میں بغداد دنیا کا سب سے بڑا شہر تھا۔","سیاسی عظمت: رومی ملکہ آئرین خراج دیتی تھی؛ نقفور نے خراج بند کر کے توہین آمیز خط لکھا تو ہارون نے خود حملہ کر کے اسے شکست دی اور خراج بحال کیا؛ بغاوتیں (یمنی و مضری قبائل، دمشق، سندھ) کچلی گئیں؛ شارلیمین سے سفارتی تعلقات۔","برامکہ کی وزارت: یحییٰ برمکی اور اس کے بیٹوں فضل اور جعفر نے سترہ سال بہترین انتظام کیا؛ خوشحالی اور امن عام تھا۔","علمی ترقی: بیت الحکمہ کا قیام، یونانی و فارسی کتب کے تراجم؛ امام ابو یوسف قاضی القضاۃ؛ کتاب الخراج؛ شعرا، علما اور اطبا کی سرپرستی؛ کاغذ سازی کا کارخانہ۔","ذاتی سیرت: روزانہ سو رکعت نفل، ایک سال حج اور ایک سال جہاد؛ نصیحت سن کر رو پڑنا؛ رفاہِ عامہ — نہریں، سڑکیں، سرائیں، ہسپتال؛ نہرِ زبیدہ؛ اسی لیے یہ دور سنہری باب کہلاتا ہے — اگرچہ برامکہ کی تباہی اور امین کی ولی عہدی اس کی بڑی غلطیاں تھیں۔"]},{"q":[["ihist12-l25-exercise-124",3]],"s":["مامون (198–218ھ) امین کے قتل کے بعد تخت نشین ہوا؛ فضل بن سہل وزیرِ اعظم بنا؛ ہرثمہ کا قتل، امام علی رضا کی ولی عہدی، بغداد میں ابراہیم بن مہدی کی خلافت اور 204ھ میں مامون کی بغداد واپسی اس کے دور کے اہم واقعات ہیں؛ طاہر کو خراسان کا گورنر بنایا (طاہری خاندان)؛ بابک خرمی، مصر اور رومیوں سے جنگیں۔","علمی ترقی: جعفر برمکی کی تربیت کی وجہ سے علم سے دلی لگاؤ؛ تفسیر، فقہ، حدیث اور فلسفہ میں ماہر؛ بیت الحکمہ کو عظیم کتب خانہ، دار الترجمہ اور تحقیقی مرکز بنایا؛ یونانی، سریانی، فارسی اور سنسکرت کتب کا ترجمہ؛ مترجمین کو کتاب کے وزن کے برابر سونا۔","علما و سائنس دان: حنین بن اسحاق، الکندی (فیلسوف العرب)، الخوارزمی (الجبرا)، بنو موسیٰ؛ بغداد اور دمشق میں رصد گاہیں؛ زمین کے محیط کی پیمائش؛ طب، کیمیا اور جغرافیہ میں ترقی۔","ادبی ترقی: شعرا اور ادبا کی سرپرستی؛ علمی مباحثے اور مناظرے؛ عربی نثر میں ترجموں سے نئی اصطلاحات۔","منفی پہلو: معتزلہ کی سرپرستی اور خلقِ قرآن کا فتنہ جس میں علما (امام احمد بن حنبل) پر سختی ہوئی؛ 218ھ میں طرطوس کے قریب وفات۔"]},{"q":[["ihist12-l25-exercise-124",4]],"s":["صلیبی جنگیں (1095–1291ء) مسلمانوں اور عیسائیوں کے درمیان بیت المقدس کے لیے لڑی گئیں؛ عیسائی صلیب کے نام پر لڑتے تھے۔","اسباب: عیسائیوں کی برتری کی خواہش اور نفرت؛ زائرین کے بہانے پروپیگنڈا؛ یورپ کی خانہ جنگیاں اور پادریوں کی سازش؛ بحیرۂ روم میں تجارتی مفادات؛ عباسیوں کی کمزوری؛ فوری سبب — کومنینس کی فریاد پر پوپ نے 26 نومبر 1095ء کو فرانس میں کونسل بلائی۔","واقعات: پہلی جنگ — پیٹر راہب کی تیرہ لاکھ کی فوج میں سے بیس ہزار پہنچے، بیت المقدس پر قبضہ اور قتلِ عام، گاڈفرے حکمران؛ دوسری جنگ — عماد الدین زنگی، نور الدین زنگی اور صلاح الدین ایوبی کا جہاد، 1187ء میں بیت المقدس کی فتح اور رحم دلانہ سلوک؛ تیسری جنگ — رچرڈ، فریڈرک اور فلپ کا اتحاد، عکہ پر 1189–1192ء جنگیں، فریڈرک ڈوب گیا، صلح؛ بعد کی پانچ جنگیں تاریخی اہمیت نہیں رکھتیں۔","نتائج: یورپ میں علمی ترقی اور نشاۃِ ثانیہ کی بنیاد؛ تجارتی منڈیاں؛ زراعت اور آبپاشی کے جدید طریقے یورپ پہنچے؛ جاگیرداری اور پوپ کی طاقت کمزور؛ مسلم دنیا میں اتحاد کا وقتی جذبہ مگر جانی و مالی نقصان اور صدیوں کی تلخی۔"]},{"q":[["ihist12-l25-exercise-124",5]],"s":["عباسی دور کا مرکزی نظامِ حکومت: خلیفہ — سربراہِ حکومت، مذہبی پیشوا اور سپہ سالار؛ مطلق العنان، کوئی شوریٰ نہیں۔","وزارت: وزیرِ تفویض (مدار المہام/امیر الامراء) — لامحدود اختیارات، آخری دور میں اقتدار اسی کے ہاتھ؛ وزیرِ تنفیذ — محدود اختیارات، احکام پر عمل درآمد اور صوبائی حالات سے باخبر رہنا۔","حاجب — وزیر کے بعد دوسرا مقام (عباسیوں کی ایجاد)؛ ملاقات کی اجازت اور مشورہ؛ کاتب (میر منشی) — خط و کتابت اور فرامین؛ شاہی جلاد۔","محکمے: دیوان العزیز، الخراج، الرسائل، البرید، الاحداث (پولیس)، العرض (فوج)، الغمام (اقلیتیں)، التوقیع، الضیاع، العطاء، الموالی اور الاقرحہ (نہریں) — ہر ایک کا الگ سربراہ اور ذمہ داری؛ عدلیہ میں قاضی القضاۃ اور محتسب۔"]},{"q":[["ihist12-l25-exercise-124",6]],"s":["عروج: برامکہ ایرانی النسل خاندان تھا؛ خالد برمکی عباسی تحریک کا اہم رکن، سفاح کا وزیرِ اعظم اور منصور کا گورنرِ موصل تھا (م 163ھ)؛ اس کا بیٹا یحییٰ آذربائیجان کا گورنر اور مہدی کی طرف سے ہارون کا اتالیق بنا؛ ہارون اسے \"باپ\" کہتا اور تخت نشین ہو کر وزیرِ اعظم اور مختارِ کل بنا دیا۔","یحییٰ کے چار بیٹے فضل، جعفر، موسیٰ اور محمد سب لائق تھے؛ فضل ہارون کا رضاعی بھائی اور جعفر خاص مصاحب، وزیر اور مامون کا اتالیق تھا؛ جعفر نے یمنی و مضری قبائل کے جھگڑے ختم کیے؛ ان کی سخاوت، علم دوستی اور انتظامی قابلیت ضرب المثل بنی؛ خلافت میں ایرانی تہذیب پھیلی۔","زوال: سترہ سالہ وزارت کے بعد محرم 187ھ میں جعفر قتل کیا گیا، یحییٰ اور فضل قید ہوئے اور جائیدادیں ضبط ہوئیں۔","اسباب: ان کا بے پناہ اقتدار اور دولت جس سے ہارون خائف ہوا؛ دشمن فضل بن ربیع کا یہ الزام کہ وہ اہلِ بیت کو اقتدار دینا چاہتے ہیں؛ علویوں (یحییٰ بن عبداللہ) سے نرمی؛ زبیدہ کی دشمنی کیونکہ جعفر مامون کا حامی تھا؛ عباسہ کی شادی کا قصہ جسے ابنِ خلدون، ابنِ قتیبہ اور مولانا عبدالرزاق کانپوری نے بے بنیاد افسانہ قرار دیا۔"]},{"q":[["ihist12-l25-exercise-124",7]],"s":["سلجوقی ترک قبیلہ تھا؛ طغرل اور اس کا بھائی غزنویوں کی ملازمت میں رہے؛ غزنوی کمزور ہوئے تو نیشاپور، مرو، جرجان، طبرستان اور خوارزم فتح کیے؛ رے کو دار الحکومت بنایا؛ ہمدان، عراق اور آرمینیا سلطنت میں شامل ہوئے۔","کارنامے: (1) خلیفہ قائم کی درخواست پر 18 دسمبر 1055ء کو طغرل بیگ بغداد میں داخل ہوا اور شیعہ بویہیوں کا اقتدار ختم کیا؛ سنی ہونے کی وجہ سے خلافت کا احترام بحال کیا؛ بساسیری کو قتل کر کے خلیفہ کو دوبارہ تخت پر بٹھایا۔","(2) الپ ارسلان نے ملازکرد (1071ء) میں رومی قیصر کو شکست دی اور آرمینیا فتح کیا؛ (3) ملک شاہ کا دور امن و امان کا دور تھا؛ وزیر نظام الملک طوسی نے مدارسِ نظامیہ قائم کیے، جلالی تقویم (عمر خیام) بنی؛ (4) سلجوقیانِ روم (قونیہ) کی سلطنت قائم ہوئی جو اناطولیہ کو اسلامی بنانے کا ذریعہ بنی۔","(5) صلیبیوں کا مقابلہ کیا؛ سلجوقی امرا (اتابک) — عماد الدین اور نور الدین زنگی — نے جہاد جاری رکھا؛ ملک شاہ کے بعد خانہ جنگی سے کمزور ہوئے اور آخرکار خوارزم شاہیوں نے ان کا خاتمہ کیا۔"]},{"q":[["ihist12-l25-exercise-124",8]],"s":["دیلمی یا بویہی خاندان کا جدِ امجد ابو شجاع بویہ بن فناخسرو تھا؛ وہ دیلم کے رہنے والے اور عقیدے کے لحاظ سے شیعہ تھے؛ اس کے بیٹوں علی، حسن اور احمد نے فارس، رے اور اصفہان میں حکومت قائم کی۔","احمد (معز الدولہ) 945ء میں بغداد میں داخل ہوا اور جنوری 946ء میں مستکفی کو معزول کر کے اندھا کر دیا؛ وہ علوی حکومت قائم کرنا چاہتا تھا مگر مصلحتاً عباسی مطیع کو خلیفہ بنایا؛ خلیفہ کا وظیفہ مقرر اور صرف خطبے میں نام۔","انہوں نے 945ء سے 1055ء تک تقریباً 110 سال عباسیوں کو دبائے رکھا؛ دار الحکومت شیراز اور عراق صوبہ؛ بنو حمدان (سنی) سے مسلسل لڑائیاں؛ سرحدوں پر رومی حملے جن کا مقابلہ سیف الدولہ حمدانی نے کیا۔","عضد الدولہ نمایاں ترین بویہی سلطان: پہلا ملک الملوک/شہنشاہ؛ رفاہِ عامہ، ہسپتال، مساجد اور نہریں؛ بعد میں بختیار، بہاء الدولہ، شرف الدولہ اور جلال الدولہ کے دور میں خانہ جنگی اور معاشی تباہی؛ 1055ء میں طغرل بیگ سلجوقی نے ان کا اقتدار ختم کیا۔"]},{"q":[["ihist12-l25-exercise-124",9]],"s":["تباہیٔ بغداد (1258ء) کے اسباب: خلافت کی دیرینہ کمزوری، عیش پرست خلفا اور ناکارہ فوج؛ بغداد میں شیعہ سنی دشمنی عروج پر — خلیفہ کے بیٹے نے کرخ کا شیعہ محلہ لٹوایا؛ شیعہ وزیر ابنِ علقمی نے فوج برخاست کی اور ہلاکو کو حملے کی دعوت دی۔","بیرونی سبب: خوارزم شاہ علاء الدین نے چنگیز خان کا تجارتی معاہدہ توڑ کر اس کے سفیر کو قتل کروایا جس سے تاتاری طوفان عالمِ اسلام پر ٹوٹا؛ منگو خان نے ہلاکو کو اسلامی علاقے فتح کرنے کا حکم دیا؛ مسلم حکمرانوں میں اتحاد کا فقدان۔","واقعات: محرم 656ھ میں ہلاکو نے بغداد کا محاصرہ کیا؛ خلیفہ مستعصم کو علما و فقہا سمیت قتل کیا گیا؛ تقریباً سولہ لاکھ انسان قتل ہوئے؛ کتب خانوں کی کتابیں دجلہ میں بہا دی گئیں۔","نتائج: پانچ سو سالہ عباسی خلافت کا بغداد میں خاتمہ؛ اسلامی تہذیب و علوم کے مرکز کی بربادی اور صدیوں کا علمی ذخیرہ ضائع؛ عالمِ اسلام کا سیاسی مرکز ختم (بعد میں مصر میں مملوکوں کے زیرِ سایہ برائے نام عباسی خلافت)؛ مسلمانوں کا علمی زوال؛ ابنِ علقمی کا ذلت آمیز انجام — سبق یہ کہ باہمی نفرت کی دیواریں کھڑی کرنے والوں کا انجام تباہی ہے۔"]},{"q":[["ihist12-l25-exercise-124",10]],"s":["عباسی خلافت کے زوال کے اسباب (خلاصہ): (1) عیش پرست اور نااہل خلفا؛ (2) شیعانِ علیؓ سے وعدہ خلافی اور ان کی مسلسل بغاوتیں؛ (3) ایرانیوں پر شک — ابو مسلم کا قتل اور برامکہ کی تباہی۔","(4) ترکوں کو اقتدار میں شامل کرنا جنہوں نے خلفا کو کٹھ پتلی بنا دیا، پھر بویہیوں اور سلجوقیوں کا تسلط؛ (5) صوبوں کی خود مختاری — طاہری، صفاری، سامانی، طولونی اور فاطمی ریاستیں۔","(6) نسلی اور فرقہ وارانہ تعصب؛ (7) فوج سے غفلت؛ (8) شخصی اور مطلق العنان طرزِ حکومت؛ (9) معاشی بدحالی، بھاری ٹیکس، قحط اور سیلاب؛ (10) مرکز اور صوبوں کی کشمکش۔","(11) بیرونی حملے — صلیبی جنگیں اور آخرکار ہلاکو خان کا حملہ (1258ء) جس نے خلافت کا خاتمہ کر دیا۔"]}]}},"26":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l26-text-131",9]],"tf":"tf","s":["صحیح۔ امام ابو حنیفہ (نعمان بن ثابت) کو اپنے علم اور علمی کمالات کی وجہ سے امامِ اعظم کہا جاتا ہے۔"],"c":0},{"q":[["ihist12-l26-text-131",10]],"tf":"tf","s":["صحیح۔ امام ابو حنیفہ کپڑے کے بہت بڑے تاجر تھے اور اپنے شاگردوں کی مالی مدد بھی کرتے تھے۔"],"c":0},{"q":[["ihist12-l26-text-131",11]],"tf":"tf","s":["صحیح۔ امام مالک 92ھ میں مدینہ منورہ میں پیدا ہوئے۔"],"c":0},{"q":[["ihist12-l26-exercise-132",0]],"tf":"tf","s":["صحیح۔ سبق میں امام جعفر صادق کو امام مالک کے اساتذہ میں شمار کیا گیا ہے۔"],"c":0},{"q":[["ihist12-l26-exercise-132",1]],"tf":"tf","s":["صحیح۔ امام شافعی امام مالک اور امام محمد بن الحسن کے شاگرد تھے۔"],"c":0},{"q":[["ihist12-l26-exercise-132",2]],"tf":"tf","s":["صحیح۔ امام شافعی کی مشہور ترین کتاب \"کتاب الام\" ہے جس میں عبادات، معاملات اور تعزیرات پر مفصل بحث ہے۔"],"c":0},{"q":[["ihist12-l26-exercise-132",3]],"tf":"tf","s":["غلط۔ امام احمد بن حنبل 164ھ میں بغداد میں پیدا ہوئے (مدینہ میں نہیں)۔"],"c":1},{"q":[["ihist12-l26-exercise-132",4]],"tf":"tf","s":["صحیح۔ امام احمد نے امام شافعی سے بھی استفادہ کیا (اور امام ابو یوسف و امام محمد سے بھی)۔"],"c":0},{"q":[["ihist12-l26-exercise-132",5]],"tf":"tf","s":["صحیح۔ بو علی سینا کو طب میں کمال حاصل تھا؛ ان کی \"القانون فی الطب\" سب سے مشہور ہے۔"],"c":0},{"q":[["ihist12-l26-exercise-132",6]],"tf":"tf","s":["صحیح۔ ابنِ سینا کی کتابیں (القانون) لاطینی میں ترجمہ ہو کر صدیوں تک یورپ کی جامعات میں پڑھائی جاتی رہیں؛ القانون روم میں بھی شائع ہوئی۔"],"c":0},{"q":[["ihist12-l26-exercise-132",7]],"tf":"tf","s":["صحیح۔ یعقوب بن اسحاق کندی کوفہ میں پیدا ہوئے؛ وہ خالص عرب نسل اور قبیلہ کندہ سے تھے۔"],"c":0},{"q":[["ihist12-l26-exercise-132",8]],"tf":"tf","s":["غلط۔ فارابی عرب نہیں بلکہ ترک تھا؛ وہ 870ء میں فاراب میں پیدا ہوا۔"],"c":1},{"q":[["ihist12-l26-exercise-132",9]],"tf":"tf","s":["غلط۔ طبری علم حاصل کرنے کے لیے طبرستان سے بغداد آئے اور وہیں فوت ہوئے؛ ہندوستان کا سفر مسعودی نے کیا تھا۔"],"c":1},{"q":[["ihist12-l26-exercise-132",10]],"tf":"tf","s":["غلط۔ مسعودی بغداد میں پیدا ہوا (کوفہ میں کندی پیدا ہوئے تھے)۔"],"c":1}],"longQuestions":[{"q":[["ihist12-l26-text-131",4]],"s":["امام ابو حنیفہ نعمان بن ثابت 80ھ میں کوفہ میں پیدا ہوئے اور زیادہ زندگی وہیں گزاری؛ علمی کمالات کی وجہ سے امامِ اعظم کہلائے؛ اساتذہ میں امام جعفر صادق، حماد اور عبدالرحمٰن بن ہرمز شامل ہیں۔","فقہِ حنفی کی تدوین: قرآن، سنت، اجماع اور قیاس کے ساتھ استحسان کے اصول سے شہرت پائی؛ شاگردوں کی مجلس بنا کر ہزاروں مسائل پر بحث کے بعد فیصلے کیے؛ یوں پہلی منظم فقہ وجود میں آئی جو آج دنیا کے اکثر مسلمانوں کا مذہب ہے۔","شاگرد: امام ابو یوسف (پہلے قاضی القضاۃ، کتاب الخراج) اور امام محمد بن الحسن شیبانی جنہوں نے ان کی فقہ کو کتابی شکل دی۔","کردار: کپڑے کے بڑے تاجر، دیانت دار اور سخی؛ آزادانہ تدریس کی اور شاگردوں کی مالی مدد کی؛ منصور کے دور میں قاضی القضاۃ کا عہدہ قبول کرنے سے انکار کیا اور قید کی سختیاں برداشت کیں؛ خارجی سردار حسان بن مجاہد سے صلح کرائی؛ 150ھ میں وفات۔"]},{"q":[["ihist12-l26-text-131",5]],"s":["موطا امام مالک (93–179ھ) کی حدیث کی مشہور کتاب ہے؛ \"موطا\" کا مطلب ہے روندا ہوا، ہموار کیا ہوا راستہ — یعنی آسان اور متفق علیہ مجموعہ؛ امام مالک نے اسے مدینہ کے علما کے سامنے پیش کیا اور سب نے اس کی تائید کی۔","اس میں احادیثِ نبوی کے ساتھ صحابہ کے آثار، تابعین کے فتاویٰ اور اہلِ مدینہ کا عمل فقہی ابواب کی ترتیب سے جمع ہے؛ یہ حدیث اور فقہ دونوں کی کتاب ہے؛ امام مالک نے کئی سال کی چھان بین کے بعد ہزاروں احادیث میں سے انتخاب کیا۔","ہارون الرشید اور اس کے بیٹوں امین و مامون نے امام مالک کے درس میں موطا پڑھی؛ ہارون اسے سرکاری قانون بنانا چاہتا تھا مگر امام نے منع کیا تاکہ دوسرے علاقوں کے علما کا اجتہاد محدود نہ ہو۔","موطا کو صحاح ستہ سے پہلے کی سب سے مستند کتاب سمجھا جاتا ہے؛ امام شافعی نے کہا: کتاب اللہ کے بعد موطا سے زیادہ صحیح کتاب نہیں؛ اسے عالمگیر شہرت ملی اور مالکی فقہ حجاز، مصر، بصرہ، اندلس اور سوڈان میں غالب رہی۔"]},{"q":[["ihist12-l26-text-131",6]],"s":["امام محمد بن ادریس شافعی 150ھ میں غزہ میں پیدا ہوئے؛ امام مالک اور امام محمد بن الحسن کے شاگرد تھے؛ علم کے لیے عرب، مصر، عراق اور یمن کا سفر کیا۔","وہ نعت، فقہ اور حدیث کے امام تھے؛ تحریر، تقریر اور فصاحت میں کمال رکھتے تھے؛ اپنے مشہور رسالے \"الرسالہ\" میں اصولِ فقہ کو پہلی بار منظم کیا — اسی لیے بانیٔ اصولِ فقہ کہلاتے ہیں۔","ان کی مشہور ترین کتاب \"کتاب الام\" ہے جس میں عبادات، معاملات اور تعزیرات پر مفصل بحث ہے؛ انہوں نے اہلِ حدیث (حجاز) اور اہلِ رائے (عراق) کے طریقوں میں توازن قائم کیا۔","ان کے پیروکار مصر، فلسطین، اردن، شام، لبنان، عراق، پاکستان، بھارت اور انڈونیشیا میں ہیں؛ امام احمد بن حنبل نے بھی ان سے استفادہ کیا؛ 204ھ میں مصر میں وفات پائی۔"]}]}},"28":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l28-exercise-142",4]],"s":["کیلٹ","سب سے پہلے کیلٹ قوم نے اندلس کو اپنا وطن بنایا؛ اس کے بعد آئبیری، لیگوری اور فونیقی قوموں کا ذکر ملتا ہے۔"],"a":"کیلٹ"},{"q":[["ihist12-l28-exercise-142",5]],"s":["مارشل","رومی دور کا مشہور شاعر مارشل تھا (فلسفے میں سینیکا اور مکالمہ نگاری میں لوکان)۔"],"a":"مارشل"},{"q":[["ihist12-l28-exercise-142",6]],"s":["بحرِ اوقیانوس","اندلس کے مغرب میں بحرِ اوقیانوس، مشرق میں بحیرۂ روم اور جنوب میں آبنائے جبل الطارق ہے۔"],"a":"بحرِ اوقیانوس"},{"q":[["ihist12-l28-exercise-142",7]],"s":["1770","اندلس کی لمبائی تقریباً 1770 کلومیٹر اور چوڑائی 966 کلومیٹر ہے۔"],"a":"1770"},{"q":[["ihist12-l28-exercise-142",8]],"s":["طلیطلہ (ٹولیڈو)","گاتھ حکمرانوں کا صدر مقام طلیطلہ (ٹولیڈو) تھا۔"],"a":"طلیطلہ (ٹولیڈو)"},{"q":[["ihist12-l28-exercise-142",9]],"s":["موسیٰ بن نصیر","خلیفہ ولید بن عبدالملک کی طرف سے موسیٰ بن نصیر افریقہ کا گورنر تھا۔"],"a":"موسیٰ بن نصیر"},{"q":[["ihist12-l28-exercise-142",10]],"s":["قیروان","افریقہ کا دار الحکومت قیروان تھا۔"],"a":"قیروان"},{"q":[["ihist12-l28-exercise-142",11]],"s":["فلورنڈا","کاؤنٹ جولین (الیان) کی بیٹی فلورنڈا تھی جس کی بے حرمتی راڈرک نے کی؛ اسی کا بدلہ لینے کے لیے جولین نے مسلمانوں کی مدد کی۔"],"a":"فلورنڈا"},{"q":[["ihist12-l28-exercise-142",12]],"s":["711","طارق بن زیاد نے 711ء میں سات ہزار بربر مجاہدوں کے ساتھ اندلس پر حملہ کیا۔"],"a":"711"},{"q":[["ihist12-l28-exercise-142",13]],"s":["کشتیوں","اندلس پہنچ کر طارق نے کشتیاں جلانے کا حکم دیا اور کہا: ہر ملک ہمارا ہے کیونکہ ساری کائنات کا مالک ہمارا اللہ ہے۔"],"a":"کشتیوں"},{"q":[["ihist12-l28-exercise-142",14]],"s":["تدمیر","اندلس کے ساحلی علاقے میں راڈرک کا گورنر تدمیر تھا جس نے مسلمانوں کو روکنے کی ناکام کوشش کی۔"],"a":"تدمیر"},{"q":[["ihist12-l28-exercise-142",15]],"s":["راڈرک","شکست کھا کر راڈرک دریا میں کود گیا اور دریا کی لہروں نے اس ظالم بادشاہ کو نگل لیا۔"],"a":"راڈرک"},{"q":[["ihist12-l28-exercise-142",16]],"s":["عروس البلاد","غرناطہ کو عروس البلاد (شہروں کی دلہن) کہا جاتا تھا؛ ابنِ بطوطہ نے بھی اسے دلہن شہر قرار دیا۔"],"a":"عروس البلاد"},{"q":[["ihist12-l28-exercise-142",17]],"n":"سبق میں \"مکمل آزادی\" کے ساتھ صفت درج نہیں؛ سیاق کے مطابق کام اور معاش کی آزادی مراد ہے۔","s":["معاشی (کام کی)","مسلمانوں نے کسانوں کو مکمل آزادی دی — وہ اپنی مرضی سے جہاں چاہیں کام کر سکتے تھے اور تاریخ میں پہلی بار انہیں زمین کی ملکیت دی گئی۔"],"a":"معاشی (کام کی)"}],"longQuestions":[{"q":[["ihist12-l28-exercise-142",1]],"s":["اندلس میں پہلے کیلٹ، پھر آئبیری، لیگوری اور فونیقی قومیں آباد ہوئیں؛ پھر قرطاجنہ (247 ق م)، یونانی اور رومی آئے؛ رومیوں نے اصلاحات کیں مگر پانچویں صدی میں وحشی ویزی گاتھ قوم نے ان سے اقتدار چھین لیا۔","سیاسی حالت: مسلمانوں کی آمد سے تقریباً دو سو سال پہلے سے گاتھ حکمران تھے جو وحشی، خونخوار اور جاہل تھے؛ صدر مقام طلیطلہ؛ تمام حکمران راڈرک کہلاتے؛ مضبوط فوج موجود نہیں تھی؛ امرا عیش و عشرت میں ڈوبے ہوئے تھے۔","سماجی حالت: معاشرہ طبقات میں بٹا ہوا تھا — امرا اور جاگیردار ایک طرف، غلام اور مزدور دوسری طرف؛ عوام کی اکثریت غلاموں کی تھی جو دن رات کھیتوں میں کام کرتے مگر کچھ ان کا اپنا نہ تھا؛ زمین پر کام کرنے والے \"سرف\" جاگیرداروں کی اجازت کے بغیر شادی بھی نہیں کر سکتے تھے اور ان کے بچے بھی جاگیردار کی ملکیت ہوتے۔","مذہبی حالت: لوگ مذہباً عیسائی تھے مگر عملی زندگی میں مذہب کا عمل دخل کم تھا؛ پادری حکمرانوں کے ساتھ مل کر عوام کا استحصال کرتے؛ یہودیوں پر سخت مظالم ہوتے تھے؛ اخلاقی گراوٹ کی مثال راڈرک کا فلورنڈا سے سلوک ہے — اسی لیے مظلوم عوام نے مسلمانوں کو نجات دہندہ سمجھا۔"]},{"q":[["ihist12-l28-exercise-142",2]],"s":["پس منظر: گاتھ روایت کے مطابق ماتحت حکمرانوں کے بچے شاہی محل میں تربیت پاتے تھے؛ سبتہ کے حاکم کاؤنٹ جولین کی بیٹی فلورنڈا کی راڈرک نے بے حرمتی کی؛ جولین نے انتقام کے لیے طارق اور موسیٰ بن نصیر (گورنرِ افریقہ، دار الحکومت قیروان) سے مل کر راڈرک کی کمزوریاں بتائیں اور تعاون کا یقین دلایا؛ موسیٰ نے آزمائشی مہمات بھیج کر تصدیق کی اور اپنے آزاد کردہ غلام طارق بن زیاد کو فوج دے کر بھیجا۔","711ء میں طارق سات ہزار بربر مجاہدوں کے ساتھ کشتیوں میں روانہ ہوا؛ خواب میں نبی کریم ﷺ نے فتح کی بشارت دی؛ ساحل پر اتر کر کشتیاں جلا دیں؛ جس پہاڑ پر اترے وہ جبل الطارق (جبرالٹر) کہلایا۔","جنگِ وادیٔ لکہ: ساحلی گورنر تدمیر ناکام رہا اور راڈرک کو لکھا کہ ایک نئی قوم اتری ہے؛ راڈرک تقریباً ایک لاکھ فوج کے ساتھ شاہی لباس میں رتھ پر سوار ہو کر جھیل لا جاندا (صوبہ قادس) کی طرف بڑھا؛ طارق کی ولولہ انگیز تقریر کے بعد معرکہ ہوا، راڈرک بھاگ کر دریا میں کودا اور ڈوب گیا۔","فتوحات: استجہ کو مرکز بنا کر طلیطلہ کی طرف پیش قدمی؛ قرطبہ، غرناطہ، ویلنسیا، مالقہ اور تدمیر کی طرف دستے بھیجے؛ موسیٰ بن نصیر بھی آیا اور فتوحات مشرق میں بارسلونا اور مغرب میں قادس تک پہنچیں؛ لوٹ مار سے منع کیا اور عیسائی مذہب کے احترام کی تاکید کی؛ کسانوں کو آزادی اور زمین کی ملکیت دی۔","واپسی: ولید نے مبارک باد کا خط لکھ کر واپسی کا حکم دیا؛ موسیٰ نے بیٹے عبدالعزیز کو اندلس کا گورنر بنایا جس نے قرطبہ کو دار الحکومت بنایا؛ موسیٰ مالِ غنیمت لے کر دمشق پہنچا اور ولید کے حوالے کیا؛ یوں اندلس تقریباً آٹھ سو سال کے لیے اسلامی سلطنت کا حصہ بن گیا۔"]}]}},"30":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l30-exercise-150",4]],"tf":"yn","s":["ہاں۔ رومی پانچویں صدی عیسوی تک اندلس میں برسرِ اقتدار رہے، پھر گاتھ قوم نے انہیں شکست دے کر قبضہ کر لیا۔"],"c":0},{"q":[["ihist12-l30-exercise-150",5]],"tf":"yn","s":["ہاں۔ کاؤنٹ جولین کی بیٹی کا نام فلورنڈا تھا۔"],"c":0},{"q":[["ihist12-l30-exercise-150",6]],"tf":"yn","s":["ہاں۔ موسیٰ بن نصیر نے اپنے بیٹے عبدالعزیز بن موسیٰ کو اندلس کا والی مقرر کیا۔"],"c":0},{"q":[["ihist12-l30-exercise-150",7]],"tf":"yn","s":["ہاں۔ ولید بن عبدالملک کی وفات (موسیٰ کی دمشق آمد کے چالیس دن بعد) کے بعد سلیمان بن عبدالملک تخت نشین ہوا۔"],"c":0},{"q":[["ihist12-l30-exercise-150",8]],"tf":"yn","s":["ہاں۔ عبدالعزیز نے راڈرک کی بیوہ ملکہ ایجیلونا سے شادی کی تھی؛ اسی کو بنیاد بنا کر اس کے خلاف پروپیگنڈا کیا گیا۔"],"c":0},{"q":[["ihist12-l30-exercise-150",9]],"tf":"yn","s":["ہاں۔ ایوب بن حبیب نے اشبیلیہ کی جگہ قرطبہ کو اسلامی اندلس کا دار الحکومت بنایا۔"],"c":0},{"q":[["ihist12-l30-exercise-150",10]],"tf":"yn","s":["ہاں۔ پلایو کی سلطنت شروع میں صرف 5 میل لمبی اور 3 میل چوڑی تھی، مگر مسلمانوں کی خانہ جنگیوں سے بڑھتی گئی۔"],"c":0},{"q":[["ihist12-l30-exercise-150",11]],"tf":"yn","s":["ہاں۔ ڈیوک آف ایکوٹین نے چھوٹی ریاستوں کو مسلمانوں کے خلاف متحد کیا اور مسلمانوں کے خلاف بڑی طاقت بن گیا۔"],"c":0},{"q":[["ihist12-l30-exercise-150",12]],"tf":"yn","s":["ہاں۔ 732ء میں امیرِ اندلس بننے والا فہری ایک عمر رسیدہ بزرگ تھا؛ فرانس پر حملوں میں کامیابی نہ ملی تو گورنرِ افریقہ نے اسے معزول کر دیا۔"],"c":0},{"q":[["ihist12-l30-exercise-150",13]],"tf":"yn","s":["ہاں۔ امیر عقبہ بن حجاج سلولی نے پیرینیز عبور کر کے دریائے رون کے کنارے فوجی چھاؤنیاں بنائیں اور سینٹ پال اور برگنڈی فتح کیے۔"],"c":0}],"longQuestions":[{"q":[["ihist12-l30-exercise-150",1]],"s":["عبدالعزیز بن موسیٰ کو موسیٰ بن نصیر نے اندلس کا والی مقرر کیا؛ وہ اپنے والد کی طرح اعلیٰ صلاحیتوں کا مالک تھا۔","جنگ کے اثرات ختم کر کے خوشحال معاشرے کی تشکیل؛ غیر مسلم آبادی کو اعتماد میں لیا؛ زراعت اور تجارت پر خصوصی توجہ دی۔","منظم حکومت قائم کی: مجلسِ شوریٰ بنائی؛ فوجداری اور دیوانی عدالتوں کا نظام قائم کیا؛ غیر مسلم رعایا کے مقدمات ان کی مقامی روایات کے مطابق نمٹائے جانے لگے۔","ہر جگہ فوجی چوکیاں قائم کر کے عوام کو تحفظ دیا؛ قرطبہ کو مرکز بنا کر انتظام سنبھالا؛ فتوحات جاری رکھیں اور ملک میں امن قائم کیا۔","وہ ایک کامیاب حکمران تھا اور اندلس میں عظیم حکومت قائم کر سکتا تھا، مگر سلیمان بن عبدالملک کے انتقام کا نشانہ بنا اور سازش سے قتل کر دیا گیا۔"]},{"q":[["ihist12-l30-exercise-150",2]],"s":["عبدالعزیز کی والیانہ اصلاحات: شوریٰ، دیوانی و فوجداری عدالتیں، غیر مسلموں کو مذہبی و عدالتی آزادی، زراعت و تجارت کی ترقی اور فوجی چوکیاں۔","راڈرک کی بیوہ ملکہ ایجیلونا سے شادی: اس کو بنیاد بنا کر اس کے خلاف پروپیگنڈا کیا گیا کہ وہ عیسائی ملکہ کے زیرِ اثر بادشاہت قائم کرنا چاہتا ہے۔","قتل: ولید کے بعد سلیمان بن عبدالملک تخت پر بیٹھا جس نے موسیٰ اور دوسرے جرنیلوں سے انتقام لیا؛ اس کی سازش سے عبدالعزیز قتل ہوا اور اس کا سر موسیٰ بن نصیر کے سامنے پیش کیا گیا جس سے موسیٰ کے غم مزید بڑھ گئے۔","ایوب بن حبیب: اس کے بعد موسیٰ کا بھتیجا ایوب تقریباً چار ماہ امیر رہا؛ اس کا بڑا کارنامہ اشبیلیہ کی جگہ قرطبہ کو دار الحکومت بنانا تھا؛ گورنرِ افریقہ نے سلیمان کو خوش کرنے کے لیے اس کی جگہ حر بن عبدالرحمٰن کو امیر بنایا۔","پلایو کی عیسائی ریاست: حر خود سر اور ضدی تھا؛ اس کے دور میں راڈرک کا جرنیل پلایو جیل سے فرار ہو کر استوریاس کے پہاڑوں میں ریاست قائم کرنے میں کامیاب ہوا — شروع میں 5 میل لمبی اور 3 میل چوڑی، جو بعد میں مسلمانوں کے اقتدار کے خاتمے کا سبب بنی۔"]}]}},"31":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l31-exercise-157",3]],"s":["بدر","عبدالرحمٰن الداخل کا غلام بدر تھا جو اس کے ساتھ افریقہ گیا اور اندلس کے امرا سے رابطہ کیا۔"],"a":"بدر"},{"q":[["ihist12-l31-exercise-157",4]],"s":["بربر","عبدالرحمٰن کی والدہ بربر قبیلے سے تھیں، اس لیے بربر قبائل نے اس کی بھرپور حمایت کی۔"],"a":"بربر"},{"q":[["ihist12-l31-exercise-157",5]],"s":["دیوانی اور فوجداری","عبدالرحمٰن نے دیوانی اور فوجداری مقدمات کے لیے الگ الگ عدالتیں قائم کیں۔"],"a":"دیوانی اور فوجداری"},{"q":[["ihist12-l31-exercise-157",6]],"s":["قاضی","محکمۂ انصاف کا سربراہ قاضی کہلاتا تھا۔"],"a":"قاضی"},{"q":[["ihist12-l31-exercise-157",7]],"s":["قرطبہ","عبدالرحمٰن الداخل نے قرطبہ میں ٹکسال قائم کی۔"],"a":"قرطبہ"},{"q":[["ihist12-l31-exercise-157",8]],"s":["سنہرے بالوں والے؛ بربر قبائل","سنہرے بالوں والے بیس سالہ عبدالرحمٰن کی والدہ بربر قبائل سے تعلق رکھتی تھیں۔"],"a":"سنہرے بالوں والے؛ بربر قبائل"},{"q":[["ihist12-l31-exercise-157",9]],"s":["قصر الرصافہ","عبدالرحمٰن نے قرطبہ میں اپنے دادا ہشام کے محل کے نام پر \"قصر الرصافہ\" بنوایا۔"],"a":"قصر الرصافہ"},{"q":[["ihist12-l31-exercise-157",10]],"s":["تیزی (فوری کارروائی)","ابنِ اثیر کے مطابق الداخل باغیوں کے خلاف تیزی سے کارروائی کرتا تھا، آرام نہیں کرتا تھا اور اپنا کام دوسروں پر نہیں چھوڑتا تھا۔"],"a":"تیزی (فوری کارروائی)"},{"q":[["ihist12-l31-exercise-157",11]],"s":["امیر","جامع مسجد قرطبہ کا خوبصورت مینار دیکھ کر عبدالرحمٰن کہتا: یہ مسجد خلیفہ چاہتی ہے، میں تو صرف امیر ہوں۔"],"a":"امیر"},{"q":[["ihist12-l31-exercise-157",12]],"s":["تنہائی","آخری دنوں میں عبدالرحمٰن تنہائی چاہتا تھا؛ ہشام کی بیعت لے کر ماردہ جانا چاہتا تھا؛ 788ء میں 58 سال کی عمر میں وفات پائی۔"],"a":"تنہائی"}],"longQuestions":[{"q":[["ihist12-l31-exercise-157",1]],"s":["پس منظر: عباسیوں نے بنو امیہ کا قتلِ عام کیا تو ہشام بن عبدالملک کا پوتا عبدالرحمٰن بن معاویہ اپنے غلام بدر کے ساتھ افریقہ بھاگا؛ گورنرِ افریقہ بھی مخالف تھا، اس لیے پناہ لیتا رہا؛ ننھیالی بربر قبائل کی مدد سے اندلس پہنچا؛ والیٔ اندلس یوسف فہری کو شکست دی اور قرطبہ کو دار الحکومت بنا کر 756ء میں اموی امارت قائم کی — اسے بابر سے تشبیہ دی جاتی ہے جس نے سب کچھ کھو کر نئی سلطنت قائم کی۔","سیرت: بہادر، سخی، فیاض، دور اندیش اور مستقل مزاج؛ باغیوں کے خلاف فوری کارروائی، اپنا کام خود کرنا، سفید لباس پہننا؛ روادار حکمران جس نے مختلف قبائل کو شیر و شکر کیا؛ عوام اسے راستے میں روک کر انصاف مانگ سکتے تھے؛ خود شاعر تھا۔","انتظامی کارنامے: ملک کو چھ صوبوں میں تقسیم کیا؛ ہر صوبے میں گورنر کی مدد کے لیے دو عامل اور چھ وزیر؛ پولیس، انصاف اور جیل مرکز کے پاس؛ حاجب، وزرا اور کاتب کے عہدے؛ دیوانی و فوجداری عدالتیں (سربراہ قاضی)؛ سڑکوں اور ڈاک چوکیوں کا جال؛ خود گشت کر کے عملے کی نگرانی؛ شہزادوں کی دفاتر اور عدالتوں میں عملی تربیت۔","فوجی کارنامے: بربروں اور موالی کو فوج میں شامل کیا؛ بحری بیڑا مضبوط کیا؛ عباسی سازشوں (منصور کے نمائندے)، بربر بغاوتوں، عیسائیوں اور شارلیمین کے حملوں (رونسیوالس) کا کامیاب مقابلہ۔","تعمیری و علمی کارنامے: قرطبہ کی فصیل کی مرمت؛ قصر الرصافہ؛ جامع مسجد قرطبہ کی بنیاد (80 ہزار دینار)؛ ٹکسال؛ باغات؛ علما کے بڑے وظیفے اور مشاعرے — ابو المخشی، یحییٰ بن یحییٰ جیسے علما جمع ہوئے اور قرطبہ علوم و فنون کا گہوارہ بن گیا؛ 788ء میں وفات۔"]}]}},"33":{"lang":"ur","items":{"mcqs":[{"q":[["ihist12-l33-text-165",5]],"ob":1,"s":["عبدالرحمٰن الداخل نے اپنے بیٹے ہشام کو ولی عہد بنایا؛ اس کے بھائیوں سلیمان اور عبداللہ نے تخت چھیننے کی ناکام کوشش کی۔"],"c":1},{"q":[["ihist12-l33-text-165",6]],"ob":1,"s":["ابنِ اثیر کے مطابق ہشام اندلس چھوڑ کر مغرب میں آباد ہو گیا تھا مگر کچھ عرصے بعد مشرقی اندلس میں اپنی کھوئی ہوئی طاقت بحال کرنے میں کامیاب ہوا۔"],"c":1},{"q":[["ihist12-l33-text-165",7]],"ob":1,"s":["عبدالرحمٰن ثانی نے سکے ڈھالنے کے لیے قرطبہ میں ٹکسال قائم کی۔"],"c":1},{"q":[["ihist12-l33-text-165",8]],"ob":1,"s":["عبدالرحمٰن ثانی کا بڑا کارنامہ قیمتوں پر کنٹرول (پرائس کنٹرول) ہے۔"],"c":2},{"q":[["ihist12-l33-text-165",9]],"ob":1,"s":["کہا جاتا ہے کہ زریاب ہارون الرشید کے دربار سے وابستہ تھا؛ وہ اعلیٰ گلوکار اور موسیقار اور آدابِ طعام و مجلس کے لیے مشہور تھا۔"],"c":0},{"q":[["ihist12-l33-text-165",10]],"ob":1,"s":["محکمۂ مالیات کا سربراہ شیخ الخزائن کہلاتا تھا؛ اس کی اجازت کے بغیر امیر بھی کوئی رقم خرچ نہیں کر سکتا تھا۔"],"c":0},{"q":[["ihist12-l33-text-165",11]],"ob":1,"s":["عبدالرحمٰن الاوسط کی وفات کے بعد اس کا بیٹا محمد اوّل تخت نشین ہوا (852–886ء)۔"],"c":1},{"q":[["ihist12-l33-text-165",12]],"ob":1,"s":["نو مسلم منافق باغی عمر بن حفصون پہاڑی چوہا کہلاتا تھا اور سب سے خطرناک باغی تھا۔"],"c":2}],"longQuestions":[{"q":[["ihist12-l33-text-165",2]],"s":["ہشام بن عبدالرحمٰن (788–796ء) باپ کا نامزد ولی عہد تھا؛ بھائیوں سلیمان اور عبداللہ کی بغاوت ناکام بنائی؛ انتظامیہ میں بنیادی تبدیلی کے بجائے کارکردگی بہتر کی اور بدعنوان عمال کو سخت سزائیں دیں — کسی کو رعایت نہیں دی۔","مالیاتی اصلاحات: محکمۂ مال میں تبدیلیاں؛ زکوٰۃ کا نظام نافذ؛ غیر اسلامی ٹیکس ختم؛ زکوٰۃ اور صدقات کتاب و سنت کے مطابق وصول؛ یوں اندلس سیاسی، سماجی اور معاشی لحاظ سے مثالی ریاست بن گیا۔","عدل و انصاف: ہشام عادل حکمران تھا؛ قاضیوں کو انصاف کی تاکید؛ عدلیہ کو مکمل آزادی؛ امام مالک کی فقہ کو رواج دیا۔","تعمیرات اور فنون: فنونِ لطیفہ کی سرپرستی؛ جامع مسجد قرطبہ مکمل کی جس کی بنیاد عبدالرحمٰن نے رکھی تھی؛ دار الحکومت کو خوبصورت بنایا اور باغات لگوائے؛ اسلامی تہذیب یورپ میں مشہور ہوئی جب یورپ جہالت کے اندھیرے میں تھا۔","فوجی مہمات: فوجی نظام کی خامیاں دور کیں؛ عبدالملک بن عبدالواحد کو عیسائیوں کے خلاف بھیجا جس نے گیرونا اور ناربون پر حملے کیے؛ ملک بیرونی حملوں سے محفوظ اور اندرونی طور پر پرامن رہا — تنقیدی جائزہ: اس کا دور مختصر مگر امن، انصاف اور مذہبی اصلاح کا مثالی دور تھا؛ البتہ اس نے فوجی نظام میں کوئی بڑی تبدیلی نہ کی جس کی کمی بعد میں محسوس ہوئی۔"]},{"q":[["ihist12-l33-text-165",3]],"s":["عبدالرحمٰن ثانی (الاوسط) الحکم اوّل کا بیٹا تھا جو 31 سال کی عمر میں تخت نشین ہوا (822–852ء)؛ عبدالرحمٰن الداخل اور عبدالرحمٰن الناصر کے درمیانی دور میں حکومت کرنے کی وجہ سے \"الاوسط\" کہلاتا ہے؛ عوام میں مقبول اور حکمرانی کی تمام خوبیوں کا حامل۔","داخلی امن: بھائی عبداللہ کی بغاوت ختم (823ء میں ویلنسیا میں وفات)؛ مضری اور یمانی قبائل کی رقابت ختم کرنے کے لیے ابو الشماخ مضری کو فوج میں بڑا عہدہ دیا؛ تدمیر کی جگہ مرسیہ کو صدر مقام بنایا۔","بیرونی تعلقات اور جنگیں: ماردہ، طلیطلہ، بارسلونا اور ناوار کے عیسائیوں کو زیر کر کے گلیشیا کی طرف بڑھا؛ الفانسو دوم بھاگ گیا؛ بازنطینی بادشاہ میخائیل نے سفیر بھیجا اور جواب میں شاعر یحییٰ الغزال کو بھیجا گیا؛ نارمن (مجوس) کے حملے پسپا کیے۔","انتظامی کارنامے: پہلی بار تمام وزرا پر مشتمل مشاورتی کونسل؛ حاجب بمنزلہ وزیرِ اعظم (عبدالکریم بن مغیث)؛ شیخ الخزائن کی مالی خود مختاری؛ قرطبہ میں ٹکسال؛ تونسہ میں جہاز سازی کا کارخانہ؛ سب سے بڑا کارنامہ قیمتوں پر کنٹرول؛ زریاب کی آمد سے تہذیب، موسیقی اور آدابِ مجلس کی ترقی۔","عیسائی تحریک: متعصب پادری یولوجیس کی تحریک (مالی مدد الوارو) کے تحت عید الفطر 850ء کو پرفیکٹس نے توہینِ رسالت کی اور سزائے موت پائی؛ پادریوں نے اسے ولی کا درجہ دیا اور شہادت کی جھوٹی تحریک چلائی جسے امیر نے حکمت سے ختم کیا؛ 852ء میں وفات کے بعد محمد اوّل تخت نشین ہوا۔"]}]}},"35":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l35-exercise-177",4]],"s":["عبدالرحمٰن (ثالث الناصر)","سلطان عبداللہ نے اپنے بیٹوں کو چھوڑ کر پوتے عبدالرحمٰن کو ولی عہد بنایا جس کا باپ مطرف زہریلے نشتر سے قتل کیا گیا تھا۔"],"a":"عبدالرحمٰن (ثالث الناصر)"},{"q":[["ihist12-l35-exercise-177",5]],"s":["امیر المومنین","عبدالرحمٰن الناصر پہلا اموی حکمرانِ اندلس تھا جس نے امیر المومنین (خلیفہ) کا لقب اختیار کیا اور \"الناصر لدین اللہ\" کہلایا۔"],"a":"امیر المومنین"},{"q":[["ihist12-l35-exercise-177",6]],"s":["عبدالرحمٰن الناصر","عبدالرحمٰن الناصر نے آخری دنوں میں حکومت بیٹے الحکم ثانی کے حوالے کی اور خود درویش بن کر عبادت میں مصروف ہو گیا۔"],"a":"عبدالرحمٰن الناصر"},{"q":[["ihist12-l35-exercise-177",7]],"s":["بیس","تخت نشینی کے وقت عبدالرحمٰن الناصر کی عمر بیس سال تھی۔"],"a":"بیس"},{"q":[["ihist12-l35-exercise-177",8]],"s":["عبدالملک","الناصر نے وزارت عبدالملک کے سپرد کی۔"],"a":"عبدالملک"},{"q":[["ihist12-l35-exercise-177",9]],"s":["فاطمی","افریقہ میں فاطمی حکومت قائم ہو چکی تھی جس کی نظریں اندلس پر تھیں؛ الناصر نے بڑا جنگی بیڑا تیار کر کے بحیرۂ روم میں گشت کروایا۔"],"a":"فاطمی"},{"q":[["ihist12-l35-exercise-177",10]],"s":["قصر الزہرا","عبدالرحمٰن کی عمارتوں میں قصر الزہرا کو خاص مقام حاصل ہے۔"],"a":"قصر الزہرا"},{"q":[["ihist12-l35-exercise-177",11]],"s":["سلطان","صرف سلطان خود شاہی فرامین جاری کرتا اور سلطنت کے امور کے فیصلے کرتا تھا؛ کسی امیر یا وزیر کو یہ اختیار نہیں تھا۔"],"a":"سلطان"},{"q":[["ihist12-l35-exercise-177",12]],"s":["939ء","جنگِ خندق کا واقعہ 939ء میں پیش آیا۔"],"a":"939ء"},{"q":[["ihist12-l35-exercise-177",13]],"s":["جامع مسجد قرطبہ","جامع مسجد قرطبہ (اور قصر الزہرا) آج بھی فنِ تعمیر کا بہترین نمونہ مانی جاتی ہے؛ مسجد کی لمبائی تقریباً پانچ سو فٹ تھی۔"],"a":"جامع مسجد قرطبہ"},{"q":[["ihist12-l35-exercise-177",14]],"s":["الحکم ثانی (المستنصر باللہ)","الناصر کی وفات کے بعد 350ھ میں الحکم ثانی المستنصر باللہ تخت نشین ہوا۔"],"a":"الحکم ثانی (المستنصر باللہ)"},{"q":[["ihist12-l35-exercise-177",15]],"s":["صاحبِ قلم","الحکم صاحبِ سیف ہونے کے ساتھ صاحبِ قلم (عالم اور علم دوست) بھی تھا۔"],"a":"صاحبِ قلم"},{"q":[["ihist12-l35-exercise-177",16]],"s":["ایک ہزار","الحکم نے ابو الفرج اصفہانی کو ایک ہزار دینار بھیجے تاکہ کتاب الاغانی مکمل ہونے پر وہ اسے بھیج دے۔"],"a":"ایک ہزار"}],"longQuestions":[{"q":[["ihist12-l35-exercise-177",1]],"s":["عبدالرحمٰن ثالث الناصر (912–961ء) کو اس کے دادا سلطان عبداللہ نے ولی عہد بنایا؛ تخت نشینی کے وقت عمر بیس سال تھی اور ملک بغاوتوں، طوائف الملوکی اور انتشار کا شکار تھا؛ اس کے کارنامے معجزے سے کم نہیں۔","بغاوتوں کا خاتمہ: عمر بن حفصون اور اس کے بیٹوں، بربروں اور مقامی سرداروں کی بغاوتیں کچلیں؛ ابنِ خلدون کے مطابق طلیطلہ کو مطیع کیا؛ مضبوط مرکزی حکومت قائم کی۔","خلافت: 929ء میں امیر المومنین اور \"الناصر لدین اللہ\" کا لقب اختیار کیا؛ روم اور قسطنطنیہ کے حکمرانوں نے تحائف بھیجے؛ وزارت عبدالملک کو دی؛ صرف سلطان فرامین جاری کرتا تھا۔","بیرونی خطرات: افریقہ کے فاطمیوں کے خلاف مذہبی اختلافات کو ہوا دی اور بڑا جنگی بیڑا تیار کیا؛ عیسائیوں سے جنگیں — جنگِ خندق (939ء) میں شکست کے باوجود بعد میں عیسائی ریاستوں نے اطاعت قبول کی۔","خوشحالی اور تعمیرات: آمدنی (زمینی محصول 54 لاکھ 80 ہزار دینار اور دیگر ذرائع سے 60 لاکھ 65 ہزار دینار) رفاہِ عامہ پر خرچ؛ قصر الزہرا اور جامع مسجد قرطبہ کی توسیع؛ قرطبہ یورپ کا سب سے بڑا شہر؛ آخری دنوں میں حکومت الحکم ثانی کو دے کر درویش بن گیا اور پچاس سال حکومت کے بعد 350ھ میں ستر سال کی عمر میں وفات پائی۔"]},{"q":[["ihist12-l35-exercise-177",2]],"s":["الحکم ثانی المستنصر باللہ (350–366ھ) غیر متعصب حکمران تھا، جنگ سے نفرت کرتا اور مطالعے کا شوقین تھا؛ صاحبِ قلم ہونے کے ساتھ صاحبِ سیف بھی تھا اور عیسائیوں کو قابو میں رکھا۔","کتب کا شوق: کتابوں کے ترجمے کا بہت شوق تھا؛ اس کے ایجنٹ بغداد، دمشق، قاہرہ، اسکندریہ اور قسطنطنیہ سے کتابیں لاتے؛ یونانی فلسفے کی کتب کا ترجمہ ہوا؛ ابو الفرج اصفہانی کو کتاب الاغانی کے لیے ایک ہزار دینار بھیجے۔","کتب خانہ: قرطبہ کا شاہی کتب خانہ یورپ کا پہلا عظیم کتب خانہ تھا جس میں تقریباً چار لاکھ کتابیں تھیں؛ صرف فہرست 44 جلدوں میں تھی؛ وہ خود کتابوں پر حواشی لکھتا تھا۔","تعلیم: قرطبہ کی جامعہ کو عروج دیا؛ غریب بچوں کے لیے مفت مدارس قائم کیے؛ اساتذہ کو بڑی تنخواہیں؛ ابو بکر بن عمر جیسے مورخ اور علما اساتذہ؛ جامع مسجد قرطبہ کی توسیع (261537 دینار خرچ، پائپوں سے پانی، رنگین پتھر اور شیشہ)۔","اس کی علم دوستی کی وجہ سے قرطبہ علم و فن کا عالمی مرکز بنا اور یورپ کے طلبہ یہاں پڑھنے آتے — اسی لیے کہا جاتا ہے کہ الحکم ثانی علم دوست حکمران تھا۔"]}]}},"36":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l36-text-183",5]],"tf":"yn","s":["ہاں۔ اشبیلیہ، قرطبہ، غرناطہ اور دوسرے شہروں کے علما اور مدبرین کا وفد مراکش میں یوسف بن تاشفین کے پاس پہنچا اور الفانسو ششم کے مظالم بتائے۔"],"c":0},{"q":[["ihist12-l36-text-183",6]],"tf":"yn","s":["ہاں۔ الفانسو ششم نے حصن اللیط کا محاصرہ کر رکھا تھا؛ مرابطون کی آمد کا سن کر قشتالہ کی طرف لوٹ گیا۔"],"c":0},{"q":[["ihist12-l36-text-183",7]],"tf":"yn","s":["ہاں۔ جنگِ زلاقہ 1086ء میں ہوئی جس میں یوسف بن تاشفین نے عیسائیوں کو تاریخی شکست دی۔"],"c":0},{"q":[["ihist12-l36-text-183",8]],"tf":"yn","s":["ہاں۔ مرابطون نے تقریباً اسی سال حکومت کی؛ ان کے پانچ حکمران گزرے اور آخری حکمران اسحاق تھا۔"],"c":0},{"q":[["ihist12-l36-text-183",9]],"tf":"yn","s":["ہاں۔ محمد بن تومرت کی تحریک موحدون کہلائی جو توہم پرستی کے خلاف اور توحید کی دعوت پر مبنی تھی۔"],"c":0},{"q":[["ihist12-l36-text-183",10]],"tf":"yn","s":["ہاں۔ (یعقوب) منصور کی والدہ ایک عیسائی کنیز تھی۔"],"c":0},{"q":[["ihist12-l36-text-183",11]],"tf":"yn","s":["ہاں۔ منصور نے مراکش میں ایک شاندار ہسپتال بنوایا جس میں ماہر طبیب اور جراح موجود تھے؛ مورخ عبدالواحد مراکشی نے اسے بے مثال کہا۔"],"c":0},{"q":[["ihist12-l36-text-183",12]],"tf":"yn","s":["نہیں۔ 1212ء میں الفانسو ہشتم نے ہسپتال نہیں بلکہ یورپ کے حکمرانوں کی مدد سے بڑی فوج تیار کی اور العقاب (لاس ناواس دی تولوسا) میں مسلمانوں کو شکست دی؛ ہسپتال منصور نے مراکش میں بنوایا تھا۔"],"c":1},{"q":[["ihist12-l36-text-183",13]],"tf":"yn","s":["ہاں۔ غرناطہ میں اسلامی حکومت 1232ء سے 1492ء تک قائم رہی۔"],"c":0},{"q":[["ihist12-l36-text-183",14]],"tf":"yn","s":["ہاں۔ منصور 1184ء سے 1199ء تک برسرِ اقتدار رہا۔"],"c":0}],"longQuestions":[{"q":[["ihist12-l36-text-183",2]],"s":["افریقی صحرا کے لمتونہ قبیلے کی شاخ جدالہ کے شیخ یحییٰ نے حج سے واپسی پر عبداللہ بن یاسین کو ساتھ لیا جن کی تربیت سے مرابطون کی تحریک اٹھی؛ یوسف بن تاشفین اسی تحریک کا عظیم سپہ سالار اور حکمران تھا جس نے مراکش (شہر) آباد کر کے مغرب میں مضبوط سلطنت قائم کی؛ وہ متقی، سادہ اور مجاہد تھا۔","اندلس آمد کا پس منظر: اندلس طوائف الملوکی کا شکار تھا اور الفانسو ششم مسلمانوں پر ظلم کر رہا تھا (طلیطلہ 1085ء میں چھین لیا)؛ اشبیلیہ، قرطبہ اور غرناطہ کے علما اور مدبرین کا وفد مراکش پہنچا؛ یوسف نے عزت سے پیش آ کر مکمل تعاون کا یقین دلایا اور سات ہزار جانباز مجاہدوں کے ساتھ اندلس پہنچا؛ معتمد (اشبیلیہ) نے استقبال کیا۔","جنگِ زلاقہ (1086ء): الفانسو نے حصن اللیط کا محاصرہ چھوڑ کر قشتالہ سے مزید فوج جمع کی؛ یوسف نے اسلام یا جزیہ کی دعوت دی تو الفانسو نے توہین آمیز جواب دیا اور پیر کا وعدہ کر کے جمعہ کو نماز کے وقت حملہ کر دیا؛ معتمد زخمی ہو کر بھی ڈٹا رہا؛ یوسف نے نماز کے بعد پیچھے سے حملہ کر کے فوجی ذخائر پر قبضہ کیا اور عیسائیوں کو تاریخی شکست دی؛ الفانسو زخمی ہو کر بھاگا۔","دوسری آمد اور اتحاد: یوسف واپس گیا تو عیسائیوں نے پھر لوٹ مار شروع کی؛ امیر ابنِ ابی بکر نے چھوٹی ریاستوں کے حکمرانوں کی مخالفانہ سوچ سے آگاہ کیا؛ فقہا نے فتویٰ دیا کہ ان حکمرانوں کو معزول کرنا جائز ہے؛ یوسف نے غرناطہ سے شروع کر کے تمام اسلامی ریاستیں ختم کیں اور ایک متحدہ حکومت قائم کی جس نے اندلس کو مزید کئی سال بچائے رکھا۔"]},{"q":[["ihist12-l36-text-183",3]],"s":["مرابطون شروع میں بہادر اور محنتی تھے مگر دولت کی فراوانی سے عیش پرستی، حکومت سے بے رغبتی، توہم پرستی اور عقیدے کی کمزوری کا شکار ہو گئے؛ ایسے میں محمد بن تومرت نے توہم پرستی کے خلاف آواز اٹھائی اور توحید کی دعوت دی — اسی لیے ان کی تحریک \"موحدون\" کہلائی؛ اس کی بنیاد ایک مسجد میں رکھی گئی۔","عبدالمومن: ابنِ تومرت نے اسے اپنا وزیرِ اعظم بنایا؛ موحدین جلد طاقتور ہوئے، آخری مرابطی حکمران اسحاق (539–542ھ) گرفتار ہوا؛ عبدالمومن (1130–1163ء) نے مراکش کو دار الحکومت بنایا، 1145ء میں اندلس پر حملے شروع کیے، امیر المومنین کا لقب اختیار کیا؛ الجزائر (1153ء)، تیونس (1158ء) اور طرابلس (1160ء) فتح کر کے پورے شمالی افریقہ کو سلطنت میں شامل کیا؛ علم و ادب کو ترقی دی۔","یعقوب منصور (1184–1199ء): والدہ عیسائی کنیز تھی؛ صلاح الدین ایوبی کی درخواست پر صلیبیوں کے خلاف ایک سو ستر جہاز بھیجے؛ اشبیلیہ کو اسلامی سپین کا دار الحکومت بنایا؛ جیرالڈا مسجد کا مینار، رباط الفتح اور مراکش میں بے مثال ہسپتال بنوایا؛ عیسائیوں کو شکست دی (الارک 1195ء)۔","زوال: منصور کے بعد محمد الناصر (1199–1214ء) کو 1212ء میں الفانسو ہشتم کی قیادت میں متحدہ یورپی فوج نے العقاب (لاس ناواس دی تولوسا) میں شکست دی؛ اس کے بعد مسلمان عیسائیوں کا مقابلہ نہ کر سکے؛ عیسائیوں نے اسلامی سپین بانٹ لیا اور صرف غرناطہ میں 1232ء سے 1492ء تک مسلمانوں کی حکومت باقی رہی۔"]}]}},"38":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l38-exercise-201",5]],"s":["غالب","محمد بن یوسف (بن نصر، الاحمر) نے غرناطہ میں \"غالب\" کا لقب اختیار کیا۔"],"a":"غالب"},{"q":[["ihist12-l38-exercise-201",6]],"n":"سبق میں نصری دربار کے وزیر ابن الخطیب کا بھی ذکر ہے جس نے اپنی کتابوں میں غرناطہ کے مفصل حالات لکھے؛ وہ بھی درست جواب ہو سکتا ہے۔","s":["ابنِ خلدون","مشہور مورخ ابنِ خلدون اس خاندان کے ایک جانشین کا درباری رہا اور اس دور کے حالات قلمبند کیے۔"],"a":"ابنِ خلدون"},{"q":[["ihist12-l38-exercise-201",7]],"s":["ناکام","زغل (محمد دواز دہم) بڑی بہادری سے لڑا مگر ناکام رہا؛ اس نے مسلم ممالک سے مدد کی اپیل کی۔"],"a":"ناکام"},{"q":[["ihist12-l38-exercise-201",8]],"n":"سوال میں سن 1690ء چھپا ہے جبکہ سبق اور تاریخ کے مطابق یہ قانون 1609ء میں بنا تھا (ہندسوں کی ترتیب کی غلطی)۔","s":["فلپ سوم","فلپ سوم نے ایک قانون پر دستخط کیے جس کے مطابق تمام مسلمانوں کو اندلس سے نکال دیا گیا؛ تقریباً تیس لاکھ مسلمان متاثر ہوئے۔"],"a":"فلپ سوم"},{"q":[["ihist12-l38-exercise-201",9]],"s":["فرڈیننڈ؛ ملکہ ازابیلا","جنوری 1492ء میں فرڈیننڈ اور ملکہ ازابیلا شاہی جلوس کے ساتھ الحمرا میں داخل ہوئے اور ابو عبداللہ نے الحمرا کی چابیاں ان کے حوالے کیں۔"],"a":"فرڈیننڈ؛ ملکہ ازابیلا"},{"q":[["ihist12-l38-exercise-201",10]],"s":["حاجب","حجابت کا سربراہ حاجب کہلاتا تھا؛ بادشاہ کے بعد دوسری بڑی شخصیت اور بادشاہ کا محافظ اور مشیرِ اعلیٰ۔"],"a":"حاجب"},{"q":[["ihist12-l38-exercise-201",11]],"s":["قلب","فوج کا درمیانی حصہ قلب کہلاتا تھا جس میں سپہ سالار ہوتا تھا۔"],"a":"قلب"},{"q":[["ihist12-l38-exercise-201",12]],"s":["میمنہ؛ میسرہ","فوج کا دایاں حصہ میمنہ اور بایاں حصہ میسرہ کہلاتا تھا۔"],"a":"میمنہ؛ میسرہ"}],"longQuestions":[{"q":[["ihist12-l38-exercise-201",1]],"s":["موحدین کی شکست کے بعد اندلس چھوٹی ریاستوں میں بٹ گیا؛ ایسے میں مدینہ کے قبیلہ خزرج سے تعلق رکھنے والے محمد بن یوسف بن نصر (الاحمر) نے غرناطہ میں نصری (بنو احمر) خاندان کی بنیاد رکھی جو تقریباً 260 سال (1232–1492ء) قائم رہا؛ وہ خود 1232ء سے 1273ء تک حکمران رہا اور \"غالب\" کا لقب اختیار کیا۔","تہذیبی ترقی: غالب نے غرناطہ کی جنوب مشرقی پہاڑی پر قلعے کے کھنڈرات پر الحمرا محل بنوایا (سرخ پلستر کی وجہ سے یہ نام)؛ جانشینوں نے اسے مزید وسعت دی؛ علما اور اہلِ علم دور دور سے جمع ہوئے؛ غرناطہ ریشمی کپڑے اور تجارت کی وجہ سے یورپ کے امیر ترین شہروں میں شمار ہوا؛ عرب اسے دمشق کہتے تھے؛ ابنِ خلدون اور ابن الخطیب جیسے علما اس دربار سے وابستہ رہے۔","زوال: عیسائی ریاستیں متحد ہوتی گئیں؛ 1469ء میں اراگون کے فرڈیننڈ نے قشتالہ کی ملکہ ازابیلا سے شادی کی اور دونوں ریاستیں ایک طاقت بن گئیں؛ غرناطہ کے حکمرانوں میں خانہ جنگی — ابو الحسن، اس کا بیٹا ابو عبداللہ اور بھائی زغل۔","سقوط: ابو عبداللہ 1483ء میں لوسینا پر حملے میں گرفتار ہوا اور فرڈیننڈ کا آلۂ کار بن گیا؛ اس کی مدد سے غرناطہ پر حملہ کیا؛ زغل بہادری سے لڑا مگر ناکام رہا؛ آخرکار ابو عبداللہ نے جنوری 1492ء میں شرائط پر غرناطہ فرڈیننڈ کے حوالے کر دیا اور الحمرا پر صلیب نصب ہوئی۔","انجام: شرائط کی خلاف ورزی کر کے مسلمانوں کو جبراً عیسائی بنایا گیا، کتب خانے جلائے گئے؛ 1499 اور 1501ء کے شاہی فرامین؛ 1609ء میں فلپ سوم کے قانون سے تقریباً تیس لاکھ مسلمان نکالے یا قتل کیے گئے — یوں اندلس سے اسلامی حکومت کا خاتمہ ہو گیا۔"]},{"q":[["ihist12-l38-exercise-201",2]],"s":["مقصد سے دوری: مسلمان اندلس میں توحید و رسالت کی دعوت اور قرآن و سنت کے مطابق معاشرہ قائم کرنے آئے تھے؛ جب یہ مقصد نظر سے اوجھل ہوا تو زوال شروع ہوا۔","جذبۂ جہاد کا خاتمہ اور عیش پرستی: سرسبز اندلس میں مسلمان آرام طلب اور سست ہو گئے؛ دولت کی فراوانی سے یادِ خدا کی جگہ دولت پرستی، غیر اسلامی ثقافتی سرگرمیاں، رشوت، ظلم اور حرام خوری عام ہو گئی۔","خانہ جنگی اور قبائلی عصبیت: مضری و یمانی، عرب و بربر کی رقابتیں؛ نظریۂ توحید اور خلافت کمزور ہوا تو صوبے خود مختار ہوتے گئے؛ طوائف الملوکی — چھوٹی ریاستوں کے حکمران ایک دوسرے کے خلاف عیسائیوں سے مدد لیتے رہے؛ حکمرانوں کی ہوسِ اقتدار۔","نااہل حکمران: الناصر جیسے حکمران پیدا نہ ہوئے؛ اکثر حکمران عیش پرست اور نااہل تھے؛ سیاسی شعور ختم ہو گیا؛ علاقائی تنگ نظری نے آفاقی سوچ کی جگہ لے لی۔","عیسائیوں کی سازشیں اور اتحاد: عیسائی اور یہودی پس پردہ تیاری کرتے رہے؛ پوپ نے مسلمانوں کو نکالنے کی تحریک (ریکونکوئسٹا) اور صلیبی جنگیں شروع کیں؛ بھائی کو بھائی سے لڑایا؛ اراگون اور قشتالہ کا اتحاد (فرڈیننڈ و ازابیلا)؛ عالمِ اسلام سے بروقت مدد نہ ملی — سبق: مسلمان ملتِ واحدہ ہیں اور جہاد اسلام کی روح ہے۔"]},{"q":[["ihist12-l38-exercise-201",3]],"s":["مرکزی حکومت: مرکز میں مجلسِ شوریٰ کو مرکزی حیثیت حاصل تھی جو وزرا پر مشتمل تھی اور اس کا سربراہ امیر یا بادشاہ تھا؛ اندلس کے حکمران امیر کہلاتے (عبدالرحمٰن الناصر سے خلیفہ)؛ سب سے قابل وزیر وزیرِ اعظم بنتا؛ وزرا کو وسیع اختیارات تھے اور وہ جنگ میں بھی شریک ہوتے۔","بڑے محکمے: مالیات، امورِ خارجہ، عدلیہ اور فوج؛ حاجب — بادشاہ کے بعد دوسری بڑی شخصیت، محافظ اور مشیرِ اعلیٰ، محل کی سازشوں سے باخبر رکھنا، اس کی اجازت سے ملاقات؛ کاتب (محکمۂ رسائل) — شاہی فرامین، سیاسی معاہدے اور غیر ملکی خطوط؛ کوتوال؛ مہر کا محکمہ — ہر فرمان پر شاہی مہر۔","عدلیہ: مکمل آزاد، بادشاہ بھی مداخلت نہیں کر سکتا تھا؛ عدالت کا سربراہ قاضی اور تمام عدالتیں قاضی القضاۃ کے ماتحت — اس کی نقل آج بھی یورپ میں رائج ہے۔","مالیات: زمینیں ناپی گئیں، آبپاشی بہتر ہوئی؛ آمدنی کے ذرائع — زمینی محصول، چنگی و محصول، جزیہ، جنگلات، معدنیات اور زکوٰۃ؛ محکمۂ مال کے پاس حساب؛ خوشحالی کا دور۔","فوج، پولیس اور نگرانی: عبدالرحمٰن الداخل نے فوج کو جدید خطوط پر منظم کیا، بربر اور موالی شامل، ایک لاکھ سوار، قلعے اور چھاؤنیاں، بحری بیڑا؛ فوج کے حصے — مقدمہ، قلب، میمنہ، میسرہ، ساقہ؛ پولیس کی تنظیمِ نو؛ ہشام کا قائم کردہ محکمۂ احتساب (خفیہ رپورٹیں)؛ ڈاک کا نظام اور الناصر کے دور میں کبوتروں کا استعمال؛ صوبے والیوں کے ماتحت۔"]}]}},"39":{"lang":"ur","items":{"mcqs":[{"q":[["ihist12-l39-exercise-209",6]],"tf":"yn","s":["ہاں۔ یحییٰ بن یحییٰ اللیثی \"حکیمِ اندلس\" (اندلس کا دانا) کہلاتے تھے۔"],"c":0},{"q":[["ihist12-l39-exercise-209",7]],"tf":"yn","s":["ہاں۔ ابنِ حزم کے مطابق مشرق میں حنفی فقہ کو امام ابو حنیفہ اور قاضی ابو یوسف کی وجہ سے اور مغرب میں مالکی فقہ کو یحییٰ کی وجہ سے بادشاہ کی حمایت ملی۔"],"c":0},{"q":[["ihist12-l39-exercise-209",8]],"tf":"yn","s":["ہاں۔ قاضی منذر بن سعید البلوطی اعلیٰ پائے کے شاعر بھی تھے؛ ان کی شاعری میں دینی رنگ زیادہ ہے۔"],"c":0},{"q":[["ihist12-l39-exercise-209",9]],"tf":"yn","s":["ہاں۔ قاضی محمد بشیر امام مالک کے شاگرد تھے اور مالکی مذہب سے وابستہ رہے۔"],"c":0},{"q":[["ihist12-l39-exercise-209",10]],"tf":"yn","s":["ہاں۔ الزہراوی کی کتاب میں جراحی کے آلات کی تصاویر بھی دی گئی ہیں۔"],"c":0},{"q":[["ihist12-l39-exercise-209",11]],"tf":"yn","s":["ہاں۔ ابو مروان (ابنِ زہر) اپنے دور کا بے مثال طبیب تھا؛ ابنِ رشد اس کا شاگرد تھا اور اس کی کتاب \"التیسیر\" مستند ہے۔"],"c":0},{"q":[["ihist12-l39-exercise-209",12]],"tf":"yn","s":["ہاں۔ ابنِ جبیر صلاح الدین ایوبی کے دور میں بیت المقدس آیا۔"],"c":0},{"q":[["ihist12-l39-exercise-209",13]],"tf":"yn","n":"سبق میں \"جغرافیہ\" لکھا ہے؛ بیان میں \"تاریخ\" کا لفظ اسے غلط بناتا ہے۔","s":["نہیں۔ الادریسی کا نام تاریخ نہیں بلکہ جغرافیہ میں بلند مقام رکھتا ہے؛ اس نے روجر دوم کے لیے چاندی کا گلوب بنایا اور \"نزہۃ المشتاق\" لکھی۔"],"c":1},{"q":[["ihist12-l39-exercise-209",14]],"tf":"yn","s":["ہاں۔ الادریسی نے قرطبہ یونیورسٹی سے تعلیم حاصل کی۔"],"c":0},{"q":[["ihist12-l39-exercise-209",15]],"tf":"yn","n":"سبق میں سنِ پیدائش \"733ء\" چھپا ہے؛ درست 732ھ (1332ء) ہے۔","s":["ہاں۔ ابنِ خلدون تیونس میں یکم رمضان 732/733ھ کو پیدا ہوئے۔"],"c":0},{"q":[["ihist12-l39-exercise-209",16]],"tf":"yn","s":["ہاں۔ غرناطہ کے حکمران محمد پنجم نے 764ھ میں ابنِ خلدون کا شاندار استقبال کیا اور سفیر بنا کر اشبیلیہ بھیجا۔"],"c":0},{"q":[["ihist12-l39-exercise-209",17]],"tf":"yn","s":["ہاں۔ ابنِ خلدون کو رئیس المورخین کا لقب دیا گیا۔"],"c":0},{"q":[["ihist12-l39-exercise-210",0]],"tf":"yn","s":["ہاں۔ ابنِ خلدون نے مقدمہ لکھ کر فلسفۂ تاریخ کی بنیاد رکھی اور تاریخ کو علم کا درجہ دیا۔"],"c":0},{"q":[["ihist12-l39-exercise-210",1]],"tf":"yn","s":["نہیں۔ لسان الدین ابن الخطیب کا خاندان شام سے تعلق رکھتا تھا جو غرناطہ میں آباد ہو گیا تھا۔"],"c":1},{"q":[["ihist12-l39-exercise-210",2]],"tf":"yn","s":["ہاں۔ زریاب بغداد کے مشہور موسیقار اسحاق موصلی کا شاگرد تھا اور جلد ہی استاد سے آگے نکل گیا۔"],"c":0},{"q":[["ihist12-l39-exercise-210",3]],"tf":"yn","s":["ہاں۔ ابنِ رشد کو مراکش میں ابنِ طفیل کی جگہ درباری طبیب مقرر کیا گیا۔"],"c":0}],"longQuestions":[{"q":[["ihist12-l39-exercise-209",1]],"s":["یحییٰ بن یحییٰ اللیثی بربر قبیلہ مصمودہ سے تھے؛ \"حکیمِ اندلس\" کہلاتے تھے؛ حج کے بعد 795ء میں امام مالک کے شاگرد بنے اور موطا پڑھی؛ مصر میں لیث بن سعد اور مکہ میں سفیان بن عیینہ سے علم حاصل کیا۔","موطا کی روایت: ان کی روایت کردہ موطا (روایتِ یحییٰ) آج سب سے مشہور اور متداول نسخہ ہے۔","مالکی فقہ کا فروغ: عبدالرحمٰن ثانی کے دربار میں بلند مقام؛ قاضیوں کی تقرری میں ان سے ضرور مشورہ لیا جاتا؛ ابنِ حزم کے مطابق مغرب میں مالکی فقہ کو یحییٰ کی وجہ سے سرکاری سرپرستی ملی — یوں اندلس اور مغرب میں مالکی مذہب غالب ہوا۔","کردار: اعلیٰ درجے کے متقی اور پرہیزگار؛ فوجداری مقدمات کے فیصلے سناتے؛ بے باک اور نڈر — انصاف میں امیر و غریب، امرا اور وزرا حتیٰ کہ خلیفہ کے خلاف بھی فرق نہ کرتے؛ کسی ملامت کرنے والے کی ملامت سے نہ ڈرتے؛ 849ء میں وفات پائی۔"]},{"q":[["ihist12-l39-exercise-209",2]],"s":["ابنِ خلدون (عبدالرحمٰن بن محمد) تیونس میں یکم رمضان 732ھ کو پیدا ہوئے؛ یمنی سردار وائل بن حجر کی نسل سے تھے؛ ان کا خاندان پہلی صدی ہجری کے آخر میں اندلس آیا اور بعد میں تیونس منتقل ہوا؛ خاندان میں دولت کی فراوانی تھی۔","تعلیم: ابتدائی تعلیم تیونس میں؛ حدیث (موطا، صحیح مسلم، صحیح بخاری)، مالکی فقہ (المدونہ)، نحو، لغت اور التسہیل پڑھی؛ 749ھ میں طاعون سے والدین فوت ہو گئے۔","سیاسی زندگی: سیاست میں حصہ لینا چاہا اور کئی بار جیل گئے؛ 759ھ میں رہا ہوئے؛ 764ھ میں اندلس آئے جہاں غرناطہ کے حکمران محمد پنجم نے شاندار استقبال کیا اور سفیر بنا کر اشبیلیہ بھیجا؛ وزیر ابن الخطیب کے حسد کی وجہ سے 766ھ میں واپس آئے؛ بجایہ، تلمسان اور فاس کے درباروں میں عہدے؛ بعد میں مصر میں مالکی قاضی القضاۃ بنے اور تیمور سے ملاقات کی؛ 808ھ میں قاہرہ میں وفات۔","علمی کارنامے: \"رئیس المورخین\" کا لقب؛ ان سے پہلے تاریخ صرف قصے کہانیاں تھی، انہوں نے مقدمہ لکھ کر اسے علم کا درجہ دیا اور فلسفۂ تاریخ و عمرانیات کی بنیاد رکھی (عصبیت کا نظریہ، قوموں کا عروج و زوال)؛ مقدمہ دنیا کی کئی زبانوں میں ترجمہ ہوا؛ کئی جلدوں میں تاریخ \"کتاب العبر\" لکھی جس سے مورخین استفادہ کرتے ہیں۔"]},{"q":[["ihist12-l39-exercise-209",3]],"s":["زریاب عباسی خلیفہ مہدی کے دور میں نمایاں ہوا؛ بغداد کے مشہور موسیقار اسحاق موصلی کا شاگرد تھا مگر جلد ہی استاد سے آگے نکل گیا اور ہارون الرشید کے دربار تک رسائی حاصل کی؛ استاد کی ہدایت (حسد) پر بغداد چھوڑ کر اندلس آیا جہاں امیر عبدالرحمٰن ثانی نے بڑی حوصلہ افزائی کی۔","موسیقی میں: اندلس میں موسیقی کو نئے انداز میں پیش کیا؛ تقریباً ایک ہزار راگ راگنیاں یاد تھیں؛ موسیقی کے آلات ایجاد کیے (عود میں پانچواں تار)؛ قرطبہ میں موسیقی کا مدرسہ قائم کیا۔","تہذیب و ثقافت میں: وہ فنکار ہونے کے ساتھ نجوم، ادب اور شاعری کا ماہر تھا؛ شیشے کے برتنوں کا استعمال رائج کیا؛ ترچھی مانگ نکالنے کا طریقہ؛ بہت سے کھانے اس سے منسوب؛ موسم کے مطابق مناسب رنگوں کے کپڑے پہننے کا تصور؛ آدابِ طعام و مجلس۔","ایس پی سکاٹ کے مطابق ترچھی مانگ، ننگے سر چلنا، چھری کانٹے سے کھانا، کھانوں کی ورائٹی اور لباس کا فرق — یہ سب اسی کے ذہن کی ایجادات ہیں؛ یوں زریاب نے اندلس کی پوری تہذیبی زندگی بدل دی جس کا اثر یورپ تک پہنچا۔"]},{"q":[["ihist12-l39-exercise-209",4]],"s":["ابنِ رشد (ابو الولید محمد بن احمد) ایک علمی خاندان سے تعلق رکھتے تھے؛ 1126ء میں قرطبہ میں پیدا ہوئے؛ 1169ء میں اشبیلیہ کے قاضی مقرر ہوئے اور بعد میں قرطبہ کے قاضی القضاۃ بھی رہے۔","مراکش میں ابنِ طفیل کی جگہ درباری طبیب مقرر ہوئے؛ وہ ابو مروان (ابنِ زہر) کے شاگرد تھے؛ طب اور فلکیات میں مہارت رکھتے تھے؛ طب پر مشہور کتاب \"الکلیات\"۔","فلسفہ: انہوں نے ارسطو کی تحریروں کی بہترین شرحیں لکھیں جن سے آج کا یورپ بہت متاثر ہے؛ یورپ میں \"شارح\" (Averroes) کے نام سے مشہور؛ امام غزالی کی \"تہافت الفلاسفہ\" کے جواب میں \"تہافت التہافت\" لکھی؛ فقہ میں \"بدایۃ المجتہد\"۔","یورپ میں ابن رشدیت (Averroism) کی تحریک چلی جس نے عقلیت پسندی اور نشاۃِ ثانیہ کو متاثر کیا؛ 1198ء میں مراکش میں وفات پائی۔"]}]}},"40":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l40-exercise-214",11]],"s":["1232ء؛ 1492ء","نصری خاندان 1232ء سے 1492ء تک (تقریباً 260 سال) برسرِ اقتدار رہا۔"],"a":"1232ء؛ 1492ء"},{"q":[["ihist12-l40-exercise-214",12]],"s":["محمد بن یوسف بن نصر (الاحمر)","نصری خاندان کا بانی محمد بن یوسف بن نصر تھا جو الاحمر کے لقب سے مشہور تھا۔"],"a":"محمد بن یوسف بن نصر (الاحمر)"},{"q":[["ihist12-l40-exercise-215",0]],"s":["1609ء","1609ء میں فلپ سوم نے مسلمانوں کو ملک سے نکالنے کے قانون پر دستخط کیے۔"],"a":"1609ء"},{"q":[["ihist12-l40-exercise-215",1]],"s":["جنوری 1492ء","جنوری 1492ء میں فرڈیننڈ اور ملکہ ازابیلا الحمرا میں داخل ہوئے۔"],"a":"جنوری 1492ء"},{"q":[["ihist12-l40-exercise-215",2]],"s":["ہشام (بن عبدالملک)","بنو امیہ کے مشہور حکمران ہشام نے شام میں الرصافہ محل بنوایا تھا؛ عبدالرحمٰن الداخل نے قرطبہ کے باہر اسی طرز کا محل بنوا کر وہی نام رکھا۔"],"a":"ہشام (بن عبدالملک)"},{"q":[["ihist12-l40-exercise-215",3]],"s":["قرطبہ","علامہ اقبال نے اندلس میں جامع مسجد قرطبہ میں اذان دے کر نماز پڑھی اور اس کی تعریف میں نظم \"مسجدِ قرطبہ\" لکھی۔"],"a":"قرطبہ"},{"q":[["ihist12-l40-exercise-215",4]],"s":["تیس","جامع مسجد قرطبہ کی چھت کی اونچائی تیس فٹ ہے۔"],"a":"تیس"},{"q":[["ihist12-l40-exercise-215",5]],"s":["570؛ 425","جامع مسجد قرطبہ کی لمبائی 570 فٹ اور چوڑائی 425 فٹ ہے (ہشام المؤید کے دور میں محمد بن ابی عامر کی نگرانی میں توسیع کے بعد)۔"],"a":"570؛ 425"},{"q":[["ihist12-l40-exercise-215",6]],"s":["بت خانہ (گرجا)","فرڈیننڈ نے قرطبہ میں داخل ہو کر سب سے پہلے جامع مسجد قرطبہ کو بت خانے (گرجا) میں بدل دیا اور اس میں مجسمے نصب کیے۔"],"a":"بت خانہ (گرجا)"},{"q":[["ihist12-l40-exercise-215",7]],"s":["محمد بن الاحمر","الحمرا کی عمارت کا آغاز محمد بن الاحمر نے کیا؛ سرخ پلستر کی وجہ سے یہ الحمرا کہلائی۔"],"a":"محمد بن الاحمر"}],"longQuestions":[{"q":[["ihist12-l40-exercise-214",2]],"s":["عباسیوں نے بنو امیہ کا قتلِ عام کیا تو ہشام بن عبدالملک کا پوتا عبدالرحمٰن بن معاویہ اپنے غلام بدر کے ساتھ فرار ہو کر افریقہ پہنچا؛ گورنرِ افریقہ عبدالرحمٰن بن حبیب بھی مخالف تھا اس لیے چھپتا پھرا اور ننھیالی بربر قبائل میں پناہ لی۔","اندلس کے حالات: اندلس میں والیوں کے دور میں مضری و یمانی، عرب و بربر کی خانہ جنگی جاری تھی؛ والی یوسف بن عبدالرحمٰن فہری کی حکومت کمزور تھی؛ بدر نے اندلس جا کر بنو امیہ کے حامیوں (موالی) اور یمانی قبائل سے رابطہ کیا۔","آمد اور فتح: عبدالرحمٰن 755ء میں اندلس پہنچا؛ اس کی آمد سے یوسف کی فوج میں پھوٹ پڑ گئی؛ ابنِ خلدون کے مطابق یوسف بہادری سے لڑا مگر شکست کھا کر بھاگا اور قرطبہ کے قریب ایک ساتھی نے اسے قتل کر کے سر عبدالرحمٰن کے سامنے پیش کیا۔","حکومت کا قیام (756ء): قرطبہ کو دار الحکومت بنایا؛ شروع میں عباسی خلفا کا نام خطبے سے نکال دیا اور خود \"امیر\" کہلایا؛ عباسی منصور کی سازشوں، بربر بغاوتوں اور عیسائیوں کا مقابلہ کیا؛ یوں سب کچھ کھو دینے والے شہزادے نے خالی ہاتھوں سے بنو امیہ کی عظیم حکومت قائم کی جو تقریباً پونے تین سو سال رہی۔"]},{"q":[["ihist12-l40-exercise-214",3]],"s":["حکمران کی حیثیت سے: فاتح، بہادر، دور اندیش اور مستقل مزاج؛ ابنِ اثیر کے مطابق باغیوں کے خلاف فوری کارروائی کرتا، آرام نہ کرتا، کام دوسروں پر نہ چھوڑتا، رائے پر قائم رہتا؛ سخی اور فیاض؛ روادار — مختلف قبائل کو شیر و شکر کیا اور مقامی آبادی کو رعایتیں دیں؛ عوام راستے میں روک کر انصاف مانگ سکتے تھے۔","مستحکم حکومت: عباسی سازشوں، فہری اور بربر بغاوتوں اور عیسائیوں کا کامیاب مقابلہ؛ پوری زندگی مسلسل جدوجہد میں گزری۔","منتظم کی حیثیت سے: سلطنت کو چھ صوبوں میں تقسیم کیا؛ ہر صوبے میں گورنر کے ساتھ دو عامل اور چھ وزیر، قاضی اور دوسرے افسر؛ پولیس، انصاف اور جیلیں مرکز کے ماتحت؛ حاجب، وزرا اور کاتب؛ دیوانی و فوجداری عدالتیں؛ سڑکوں اور ڈاک چوکیوں کا جال؛ مسافروں کی حفاظت؛ خود گشت کر کے عملے کی نگرانی اور ضرورت مندوں کی فوری مدد؛ شہزادوں کی عملی تربیت۔","فوج اور تعمیرات: بربر اور موالی پر مشتمل منظم فوج، بحری بیڑا؛ قرطبہ کی فصیل کی مرمت، قصر الرصافہ، جامع مسجد قرطبہ کی بنیاد، ٹکسال، باغات؛ علما کی سرپرستی — قرطبہ علوم و فنون کا گہوارہ بنا؛ 788ء میں وفات۔"]},{"q":[["ihist12-l40-exercise-214",4]],"s":["عبدالرحمٰن ثانی الاوسط (822–852ء) نے 31 سال کی عمر میں تخت سنبھالا؛ عوام میں مقبول اور حکمرانی کی تمام خوبیوں کا مالک تھا؛ اس کا دور امن و خوشحالی کا دور تھا۔","داخلی استحکام: بھائی عبداللہ کی بغاوت ختم کی؛ مضری و یمانی رقابت مٹانے کے لیے ابو الشماخ مضری کو فوج میں اعلیٰ عہدہ دیا؛ تدمیر کی جگہ مرسیہ کو صدر مقام بنایا؛ یولوجیس کی عیسائی \"شہادت\" کی تحریک کو حکمت سے ختم کیا۔","انتظامی اصلاحات: اندلس کی تاریخ میں پہلی بار تمام وزرا پر مشتمل مشاورتی کونسل؛ حاجب بمنزلہ وزیرِ اعظم (عبدالکریم بن مغیث)؛ محنتی اور دیانت دار کابینہ؛ شیخ الخزائن کی مالی خود مختاری؛ قرطبہ میں ٹکسال؛ تونسہ میں جہاز سازی؛ سب سے بڑا کارنامہ قیمتوں پر کنٹرول۔","بیرونی کامیابیاں: ماردہ، طلیطلہ، بارسلونا اور ناوار کے عیسائیوں کو زیر کیا؛ گلیشیا میں الفانسو دوم بھاگا؛ بازنطینی بادشاہ میخائیل سے سفارتی تعلقات (یحییٰ الغزال کی سفارت)؛ نارمن حملے پسپا۔","تہذیبی ترقی: زریاب کے ذریعے موسیقی، لباس اور آدابِ مجلس میں انقلاب؛ علما اور شعرا کی سرپرستی — ان خدمات نے بنو امیہ کی حکومت کو استحکام دیا۔"]},{"q":[["ihist12-l40-exercise-214",5]],"s":["شخصیت: عبدالرحمٰن ثالث الناصر کو دادا سلطان عبداللہ نے بیٹوں کو چھوڑ کر ولی عہد بنایا؛ بیس سال کی عمر میں تخت نشین ہوا؛ بہادر، مدبر، روادار، عادل اور علم دوست تھا؛ پچاس سال (912–961ء) حکومت کی؛ آخری عمر میں درویش بن گیا۔","کارنامے — داخلی امن: جب تخت پر آیا تو سلطنت بغاوتوں اور طوائف الملوکی کی لپیٹ میں تھی؛ عمر بن حفصون، بربروں اور سرداروں کی بغاوتیں کچلیں؛ طلیطلہ کو مطیع کیا؛ مضبوط مرکزی حکومت؛ صرف سلطان فرامین جاری کرتا۔","خلافت اور بیرونی پالیسی: 929ء میں امیر المومنین اور الناصر لدین اللہ کا لقب؛ فاطمیوں کے مقابلے کے لیے بڑا جنگی بیڑا؛ عیسائی ریاستوں سے جنگیں (خندق 939ء) اور بالآخر ان کی اطاعت؛ روم اور قسطنطنیہ کے حکمرانوں کے تحائف اور سفارتیں۔","خوشحالی اور تعمیرات: آمدنی ایک کروڑ سے زیادہ دینار جو رفاہِ عامہ پر خرچ؛ قصر الزہرا اور مدینۃ الزہرا؛ جامع مسجد قرطبہ کی توسیع؛ قرطبہ یورپ کا سب سے ترقی یافتہ شہر؛ علوم و فنون کی سرپرستی — اس کا دور اندلس کی بنو امیہ کا سنہری دور کہلاتا ہے۔"]},{"q":[["ihist12-l40-exercise-214",6]],"s":["یوسف بن تاشفین مرابطون کا عظیم حکمران تھا؛ مرابطون افریقی صحرا کے لمتونہ قبیلے سے اٹھے؛ جدالہ کے شیخ یحییٰ اور عبداللہ بن یاسین کی دینی تحریک سے یہ منظم ہوئے؛ یوسف نے مراکش (شہر) آباد کر کے مغرب میں سلطنت قائم کی؛ وہ متقی، سادہ اور مجاہد تھا۔","اندلس آمد: طوائف الملوکی اور الفانسو ششم کے مظالم سے تنگ آ کر اشبیلیہ، قرطبہ اور غرناطہ کے علما اور مدبرین کا وفد مراکش پہنچا؛ یوسف سات ہزار مجاہدوں کے ساتھ اندلس آیا؛ معتمد نے استقبال کیا؛ الفانسو نے حصن اللیط کا محاصرہ چھوڑ کر فوج جمع کی۔","جنگِ زلاقہ (1086ء): یوسف نے اسلام یا جزیہ کی دعوت دی؛ الفانسو نے دھوکے سے جمعہ کو حملہ کیا؛ معتمد ڈٹا رہا؛ یوسف نے پیچھے سے حملہ کر کے فیصلہ کن فتح حاصل کی۔","دوسری آمد: چھوٹی ریاستوں کے حکمران جہاد میں شریک نہ ہوئے بلکہ عیسائیوں سے ملتے رہے؛ فقہا کے فتوے پر یوسف نے غرناطہ سے شروع کر کے ان سب کو معزول کیا اور متحدہ حکومت قائم کی جس سے اندلس مزید کئی دہائیاں محفوظ رہا؛ مرابطون نے تقریباً اسی سال حکومت کی۔"]},{"q":[["ihist12-l40-exercise-214",7]],"s":["مرکز: مجلسِ شوریٰ (وزرا پر مشتمل) جس کا سربراہ امیر یا بادشاہ؛ سب سے قابل وزیر وزیرِ اعظم؛ چار بڑے محکمے — مالیات، امورِ خارجہ، عدلیہ اور فوج؛ حاجب (بادشاہ کے بعد دوسری بڑی شخصیت، محافظ اور مشیرِ اعلیٰ)، کاتب (فرامین، معاہدے، خطوط) اور کوتوال؛ مہر کا محکمہ؛ ڈاک کا نظام۔","عدلیہ: مکمل آزاد؛ بادشاہ بھی مداخلت نہیں کر سکتا تھا؛ سربراہ قاضی القضاۃ؛ ہر شہر میں قاضی؛ غیر مسلموں کے مقدمات ان کی روایات کے مطابق۔","مالیات: زمینوں کی پیمائش، آبپاشی، زمینی محصول، چنگی، جزیہ، جنگلات، معدنیات اور زکوٰۃ؛ ہشام کے دور میں غیر اسلامی ٹیکس ختم اور زکوٰۃ کا نظام۔","فوج اور پولیس: عبدالرحمٰن الداخل کی جدید تنظیم، بربر اور موالی، ایک لاکھ سوار، قلعے، چھاؤنیاں، بحری بیڑا؛ الحکم اوّل نے باقاعدہ تنخواہ دار فوج قائم کی؛ پولیس کی تنظیمِ نو؛ محکمۂ احتساب (ہشام) کی خفیہ رپورٹیں؛ صوبے والیوں کے ماتحت (الداخل کے دور میں چھ صوبے)۔"]},{"q":[["ihist12-l40-exercise-214",8]],"s":["مقصد سے انحراف: توحید کی دعوت اور اسلامی معاشرے کا قیام نظروں سے اوجھل ہوا؛ جذبۂ جہاد ختم اور عیش پرستی، سستی اور دولت پرستی عام ہوئی۔","خانہ جنگیاں اور عصبیت: عرب و بربر، مضری و یمانی کی رقابت؛ الحکم ثانی کے بعد کمسن ہشام ثانی کی تخت نشینی اور منصور بن ابی عامر کا غلبہ؛ اس کے بیٹوں کے بعد قرطبہ میں خانہ جنگی (فتنۂ قرطبہ) اور 1031ء میں اموی خلافت کا خاتمہ۔","نااہل حکمران اور ہوسِ اقتدار: الناصر جیسا حکمران نہ آیا؛ اکثر عیش پرست؛ سیاسی شعور کا خاتمہ؛ رشوت اور بدعنوانی۔","طوائف الملوکی: سلطنت چھوٹی ریاستوں میں بٹ گئی اور یہ ایک دوسرے کے خلاف عیسائیوں سے مدد لینے لگیں۔","عیسائیوں کا اتحاد اور سازشیں: پلایو کی ریاست سے شروع ہونے والی عیسائی تحریک پوپ کی سرپرستی میں مضبوط ہوئی؛ بھائی کو بھائی سے لڑایا؛ علاقائی تنگ نظری اور عالمِ اسلام سے کٹ جانا — یوں بنو امیہ کا اندلس زوال کا شکار ہوا۔"]}]}},"41":{"lang":"ur","items":{"objective":[{"q":[["ihist12-l41-exercise-222",7]],"s":["نجات دہندہ","مسلمان اندلس کے مظلوموں کی دعوت پر نجات دہندہ کی حیثیت سے سپین میں داخل ہوئے اور غریبوں کے محافظ بنے۔"],"a":"نجات دہندہ"},{"q":[["ihist12-l41-exercise-222",8]],"s":["قرطبہ","اسلامی سپین کا دار الحکومت قرطبہ تھا جو یورپ کا سب سے ترقی یافتہ اور مہذب شہر تھا۔"],"a":"قرطبہ"},{"q":[["ihist12-l41-exercise-222",9]],"s":["امیر ترین (اور گنجان آباد)","اسلامی سپین دنیا کے امیر ترین اور گنجان آباد ممالک میں شمار ہوتا تھا۔"],"a":"امیر ترین (اور گنجان آباد)"},{"q":[["ihist12-l41-exercise-222",10]],"s":["زیادہ","اسلامی سپین کی آمدنی پورے یورپ کی آمدنی سے زیادہ تھی۔"],"a":"زیادہ"},{"q":[["ihist12-l41-exercise-222",11]],"s":["الحمرا","غرناطہ میں الحمرا کے باغات عالمی شہرت رکھتے تھے اور آج بھی سیاح انہیں دیکھنے آتے ہیں۔"],"a":"الحمرا"},{"q":[["ihist12-l41-exercise-222",12]],"s":["برآمدات","اسلامی سپین کی برآمدات (ریشم، اون، کاغذ، چمڑا، زیتون کا تیل، خشک میوہ، ہتھیار، شیشہ) پوری دنیا کو بھیجی جاتی تھیں۔"],"a":"برآمدات"},{"q":[["ihist12-l41-exercise-222",13]],"s":["گرجا","قرطبہ کی شاندار جامعہ کو جدید دور کے مہذب لوگوں نے گرجا (عیسائی عبادت گاہ) میں بدل دیا۔"],"a":"گرجا"}],"longQuestions":[{"q":[["ihist12-l41-exercise-222",2]],"s":["مسلمان نجات دہندہ بن کر آئے جب یورپ جہالت میں ڈوبا ہوا تھا اور جاگیردارانہ نظام نے عوام کی زندگی اجیرن کر رکھی تھی؛ مسلمانوں نے غلامی اور جاگیرداری کا خاتمہ کر کے کسانوں کو آزادی اور ملکیت دی اور مساوات قائم کی۔","شہری ترقی: دار الحکومت قرطبہ یورپ کا سب سے ترقی یافتہ شہر تھا — ایک لاکھ تیرہ ہزار مکانات، اکیس مضافاتی محلے، ستر کتب خانے، سینکڑوں دکانیں اور مساجد؛ پختہ سڑکیں اور شاہراہیں، رات کو سڑکوں پر روشنی کا انتظام، صفائی، حمام اور پانی کی فراہمی — جبکہ یورپ کے شہروں میں لوگ گھر سے نکلتے ہی کیچڑ میں پھنس جاتے تھے۔","آبادی اور بلدیات: اول درجے کی اسی اور دوم درجے کی تین سو بلدیات؛ قرطبہ اور اشبیلیہ کی آبادی پانچ پانچ لاکھ اور غرناطہ کی سوا چار لاکھ؛ دنیا بھر سے سیاح آتے تھے۔","معاشرت: لباس، کھانے اور آدابِ مجلس کی نفاست (زریاب)؛ خواتین کی آرائش اور شائستگی دوسرے ملکوں کے بادشاہوں کو شرمندہ کرتی؛ مذہبی رواداری — عیسائی اور یہودی آزادی سے رہتے؛ ہسپتال، سرائیں اور رفاہی ادارے — ایسا سماجی معیار قائم کیا جو آج بھی کئی ممالک کو حاصل نہیں۔"]},{"q":[["ihist12-l41-exercise-222",3]],"s":["عرب زراعت اور تجارت کے اصولوں سے واقف اور تجربہ کار تھے؛ سیدیو کے بقول انہوں نے اندلس کے شہروں کو باغ بنا دیا۔","آبپاشی: ویلنسیا اور غرناطہ کی بنجر اور ناہموار زمینوں کو سیراب کرنے کے لیے جدت سے کام لیا؛ سمندر سے چھ میل کے فاصلے پر بند باندھ کر دریا کا پانی روکا گیا، ڈیم بنایا اور اس سے سات نہریں نکالی گئیں جو مزید شاخوں میں تقسیم ہو کر کھیتوں تک پہنچیں؛ رہٹ اور پن چکیاں۔","نئی فصلیں اور پھل: چاول، گنا، کپاس، زعفران، کھجور، انار، نارنگی، زیتون، انجیر، بادام اور مختلف سبزیاں متعارف کرائیں؛ زراعت پر کتابیں لکھیں (ابن العوام)؛ کھاد اور پیوند کاری کے طریقے۔","باغات: ہر جگہ باغات لگائے؛ غرناطہ میں الحمرا کے باغات عالمی شہرت رکھتے ہیں؛ کسانوں کو آزادی اور زمین کی ملکیت دی، زمین کی پیمائش اور پیداوار کے مطابق محصول — یہی طریقے بعد میں یورپ پہنچے۔"]},{"q":[["ihist12-l41-exercise-222",4]],"s":["جب ملک معاشی طور پر خوشحال اور مستحکم ہو تو صنعتیں پھلتی پھولتی ہیں؛ مسلمانوں نے رومیوں کے فنون سیکھ کر ان میں اپنے نئے طریقے شامل کیے؛ پارہ اور یاقوت دریافت کیے، قیمتی پتھر اور موتی نکالے۔","کپڑا: کپاس سے کپڑا بنانے میں کمال حاصل کیا؛ ہر جگہ ریشمی اور سوتی کپڑے کے کارخانے؛ غرناطہ کا ریشم پوری دنیا میں مشہور؛ قرطبہ، غرناطہ، مالقہ اور المریہ میں اونی اور ریشمی کپڑے؛ قالین بافی۔","چمڑا اور دستکاری: چمڑے پر گل کاری کی صنعت مراکش سے آئی، اندلس نے اسے ترقی دے کر فرانس اور انگلستان پہنچایا؛ قرطبہ میں زینیں اور فر کوٹ؛ کاغذ سازی (شاطبہ)۔","معدنیات اور دیگر صنعتیں: معدنیات نکالنے کا مستقل محکمہ؛ مرسیہ کے یاقوت اور طراغونہ کے مرجان برآمد؛ لوہا اور چاندی بکثرت؛ المریہ میں شیشے اور پیتل کی صنعتیں؛ اسلحہ سازی (طلیطلہ کی تلواریں)، برتن، جہاز سازی — ان مصنوعات کی پوری دنیا میں مانگ تھی اور المریہ کی بندرگاہ تجارت کا بڑا مرکز تھی۔"]},{"q":[["ihist12-l41-exercise-222",5]],"s":["عباسیوں نے دنیا بھر سے علوم کے خزانے بغداد میں جمع کیے تھے جو وقت کے ساتھ اسلامی سپین منتقل ہوئے؛ ملک کے ہر کونے میں سکول، کالج اور سائنسی تجربہ گاہیں قائم ہوئیں؛ مباحثوں، مناظروں اور مشاعروں کے لیے شاندار ہال تھے جہاں علما ہر وقت موجود رہتے۔","اعلیٰ تعلیم: قرطبہ، غرناطہ، اشبیلیہ، طلیطلہ کی جامعات؛ قرطبہ کی جامعہ میں دنیا بھر (یورپ سمیت) کے طلبہ پڑھتے؛ علما کی تنخواہوں اور وظیفوں کے لیے بڑی جائیدادیں وقف؛ مشرقی علما کو ترجیح — افسوس کہ یہ جامعہ بعد میں گرجا بنا دی گئی۔","کتب خانے: الحکم ثانی کے شاہی کتب خانے میں تقریباً چار لاکھ کتابیں؛ اس کے ایجنٹ دنیا بھر میں کتابوں کی تلاش میں رہتے؛ ستر کتب خانے صرف قرطبہ میں۔","علوم کو عام کرنا: جب یورپ علم کی روشنی سے محروم تھا اور علم صرف چند پادریوں کی اجارہ داری تھا، مسلمانوں نے علم کو عوام کے لیے عام کیا؛ علما — ابنِ رشد، ابنِ زہر، الزہراوی، ابنِ حزم، ابنِ خلدون، الادریسی، ابنِ طفیل؛ یہیں سے علوم یورپ پہنچے اور نشاۃِ ثانیہ کی بنیاد بنے۔"]}]}}});
